pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let pr = post_residual as f64;
    score -= 12.0 * (1.0 - pr / bin_capacity as f64).powi(6);

    // Penalize dead space that is too small for typical future items
    // (residual < 20 is nearly unusable).
    if post_residual < 20 {
        score += 25.0 * (20 - post_residual) as f64;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward for a two-item perfect chain.
            if bin_residual == item_size + next_item_size {
                score -= 15.0;
            }
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 4.0; // blocks the next item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins with smaller-than-average residual (consolidate).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for opening new bins early in the stream (more future
    // items to fill them), slight aversion late.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so it only wins when open bins fit badly.
        score += 18.0;
        // Early stream: new bins are cheaper to open.
        score -= 10.0 * (1.0 - t);
        // Very late stream: avoid leaving a nearly-empty new bin.
        score += 15.0 * t * t;
    }

    // Mild pressure against accumulating many open bins.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // for future items (sizes >= 1, but typical items are large), so punish
    // them super-linearly.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead <= 20.0 {
            score += (21.0 - dead) * (21.0 - dead) * 2.5; // harsh penalty for unusable slivers
        }
    } else {
        // Perfect fit: strong reward.
        score -= 150.0;
    }

    // Reward tight fits relative to item size (low wasted fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 3.0;

    // New-bin candidate: neutral-ish baseline, but allow it when current bin
    // would leave a bad gap AND the next item could use the fresh bin.
    if bin_residual == bin_capacity {
        score = 50.0 + pressure * 0.5;
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 * 0.9 {
            score -= 20.0;
        }
        // Late in the stream, avoid spawning bins for marginal gains.
        score += progress * 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // Penalize if next item barely misses the leftover (wasted pairing).
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Slight preference for bins below mean residual (consolidating slack).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that nothing (>= 1..=100 range,
    // but realistically >= next_item_size) can use are heavily penalized.
    if post_residual > 0 {
        let unusable = (next_item_size as f64) - (post_residual as f64);
        if next_item_size > 0 && unusable > 0.0 {
            // The gap is too small for the next item: dead space.
            score += 3.0 * unusable;
        }
        // Absolute tiny-gap penalty: gaps <= 10 are almost certainly waste.
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 20.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into fewer bins,
    // but only mildly, so dead-space logic dominates.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual is already below the mean (consolidate smalls).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Late in the stream, tighten up: penalize loose fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins less attractive unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow new bins early or when item is large relative to mean residual.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 800.0; // chain fit: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // penalty grows with leftover slack beyond the next item's size
            let slack = post_residual as f64 - nxt;
            score -= 300.0 - slack * 2.0;
        } else {
            // next item cannot follow into this bin; penalize proportionally
            score += 150.0 * (nxt - post_residual as f64) / nxt.max(1.0);
        }
    }

    // Prefer tight fits relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize large dead space (unusable residuals) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // tiny unusable slivers are wasted capacity
    }

    // New-bin candidate handling: an empty bin is attractive early or when
    // current fit is poor; mildly discourage hoarding too many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 80.0 * (1.0 - progress) - 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space that cannot fit even the smallest plausible item is very bad.
        if post_residual < 10 {
            score += 120.0;
        } else if post_residual < 20 {
            score += 45.0;
        } else if post_residual < 30 {
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward filling a bin deeply (high fill ratio).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward for a near-perfect chain fit.
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item would have fit before this placement but won't after: penalize.
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer using existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: bins far below the mean residual are "fresher";
    // prefer placing into bins with residual close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Prefer bins whose residual is below the mean (they are already partly used).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: make it unattractive unless existing bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * -1.0;
        // If no other bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover divisible into small
    // "harmonic" chunks is more reusable than awkward remainders.
    let pr = post_residual;
    if pr > 0 {
        // Perfect fit reward.
        if pr == 0 {
            score -= 1000.0;
        }
        // Harmonic classes of post_residual modulo capacity fractions.
        let cap_frac = bin_capacity as f64;
        let prf = pr as f64;
        // Class 0: tiny dead space (<= 10) is nearly wasted -> penalize hard.
        if pr <= 10 {
            score += 60.0;
        }
        // Class 1: leftover that can host the next item is golden.
        if next_item_size > 0 && pr >= next_item_size {
            score -= 40.0 + 0.5 * (next_item_size as f64);
        }
        // Class 2: modulo arithmetic on residual — leftovers divisible by
        // common small item sizes (mod classes) are reusable.
        let harmonic_bonus = (pr % 10 == 0) as i32 as f64 * 25.0
            + (pr % 5 == 0) as i32 as f64 * 10.0
            + (pr % 25 == 0) as i32 as f64 * 15.0;
        score -= harmonic_bonus;
        // Class 3: awkward primes / large odd remainders -> penalize.
        if pr > 30 && pr % 2 == 1 && pr % 5 != 0 {
            score += 12.0;
        }
        // Fractional capacity coupling: prefer bins whose fill ratio lands
        // on coarse integer-division thresholds (1/4, 1/2, 3/4 full).
        let filled = (bin_capacity - pr) as f64;
        let quarter = bin_capacity / 4;
        if filled as u32 % quarter == 0 {
            score -= 8.0;
        }
        // Scale residual by capacity fraction for cross-capacity sanity.
        score += prf * (1.0 + 0.25 * (prf / cap_frac));
    } else {
        // Perfect fit: strong reward.
        score -= 500.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation elsewhere.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: only attractive when residuals are fragmented or
    // the item barely fits nowhere well.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let tight_fit = next_item_size > 0 && next_item_size >= bin_residual && bin_residual < bin_capacity;
        let _ = tight_fit;
        // Open new bin when open bins are mostly full or stream is early
        // and we can afford spreading.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_bias = if open_bins_count == 0 { -200.0 } else {
            (fragmentation * 90.0) + (1.0 - progress) * 10.0 - open_bins_count as f64 * 4.0
        };
        score += 120.0 + open_bias;
        // Never open a new bin if post_residual would be a perfect fit for next item.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 30.0;
        }
    }

    // Lookahead pairing: if next item exactly complements this bin's residual,
    // big reward (harmonic pair).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    }
    // Next item nearly fits (within harmonic tolerance of 5).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 20.0;
    }

    // Mild preference for fuller bins overall (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // If the next item could fit into this bin's post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // next item won't fit here: dead space risk
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Slight pull toward bins below mean residual (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no good option exists.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * -0.5;
    }

    // Progression-aware mild scaling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are pure waste — penalize them quadratically.
    let dead_threshold: u32 = 10;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
        score += 25.0; // flat penalty for creating unusable sliver
    }

    // Penalize near-full-but-not-full residuals (awkward gaps 11..=20)
    if post_residual >= dead_threshold && post_residual <= 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // creates a gap the next item cannot use
        score += 8.0;
    }

    // Open-bin pressure: when many bins are open, tighten tolerance for waste
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.5;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A gap is "dead" if it's too small for even the smallest plausible item.
    if post_residual > 0 {
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tightness reward: favor bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: with many bins open, avoid spreading; prefer compacting.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score += pressure * 20.0;

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are bad fits.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin if mean residual across open bins is very low (all nearly full).
        if mean_residual < 15.0 {
            score -= 60.0;
        }
    }

    // Progress-based mild compaction: early on, keep bins open; later, be stricter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common small sizes) are more valuable to keep tight.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty grows super-linearly for small unusable leftovers,
    // unless the leftover is a "harmonic" size (divisible by 5 or 10).
    if pr > 0 {
        let harmonic = (pr % 10 == 0) as i32 + (pr % 5 == 0) as i32 + (pr % 20 == 0) as i32;
        if harmonic == 0 {
            // awkward leftover: penalize
            score += 6.0 + (10.0 - (pr % 10) as f64) * 0.8;
        } else {
            // clean leftover: reward proportionally
            score -= 2.0 * harmonic as f64;
        }
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 25.0;
    }

    // Fraction-of-capacity coupling: filling a bin past half is good.
    let fill_frac = (cap - prf) / cap;
    if fill_frac > 0.5 {
        score -= 8.0 * (fill_frac - 0.5);
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residual: mild reward scaled by fit tightness
            let tight = 1.0 - ((pr - next_item_size) as f64) / cap;
            score -= 6.0 * tight;
        } else {
            // next item won't fit here: if this bin is the only option, penalize
            // wasting a near-full bin on the current item
            if pr < 10 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline that keeps it
    // competitive only when open bins have large residuals.
    if bin_residual == bin_capacity {
        // neutral-ish score relative to mean residual of open bins
        score = cap * 0.55 + mean_residual * 0.3 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big next item: fresh bin attractive
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer tightening
    // existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - fill_frac);

    // Mild penalty when bin residual deviates far from mean residual
    // (encourages balanced bin usage across the fleet).
    let dev = (prf - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "large" classes (still reusable) are favored; tiny dead-space classes penalized.
    let cap = bin_capacity as f64;

    // Dead-space penalty: residuals that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Modulo-class logic: residual divisible into common item sizes (10..80)
    // is more likely reusable.
    let r = post_residual;
    if r % 10 == 0 && r > 0 {
        score -= 12.0;
    }
    if r % 20 == 0 && r > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == r {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // fraction of residual consumed by next item
        let frac = next_item_size as f64 / r.max(1) as f64;
        score -= 30.0 * frac;
        if r - next_item_size < 10 {
            score += 10.0; // creates new dead space
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when current bins
    // are already fragmented (high mean residual spread) or many bins are open.
    if bin_residual == bin_capacity {
        score += 40.0;
        if open_bins_count > 3 {
            score -= 15.0 * ((open_bins_count as f64 - 3.0).min(5.0));
        }
        if mean_residual > 30.0 {
            score -= 10.0;
        }
    }

    // Progress: later in the stream, prefer tighter packing (larger residuals
    // become less acceptable).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins whose residual deviates from mean residual toward smaller
    // (fill the emptiest-fitting bins first keeps many mid-size bins open).
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: u32 = 10; // items are >= 1..100; gaps below this are rarely usable
    if post_residual > 0 && post_residual < dead_zone {
        score += (dead_zone - post_residual) as f64 * 6.0; // up to ~54 penalty
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity (waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 40.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer packing into existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // New-bin candidate: make it less attractive unless current bin fits are bad.
    if bin_residual == bin_capacity {
        // Neutralize base score (post_residual == capacity) and add a fixed premium.
        score = bin_capacity as f64 + 15.0;
        // But if no open bin fits tightly, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream with few open bins, prefer consolidation instead.
        if progress > 0.7 && open_bins_count <= 3 {
            score += 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < dead_zone {
            score -= 20.0 - gap as f64 * 2.0;
        }
    }

    // Slight preference for bins below mean residual (denser bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap; // normalized post residual in [0,1]

    // Smooth polynomial base: penalize leftover space, with stronger penalty
    // for mid-range waste (dead space that is hard to reuse) than for
    // near-zero or near-full residuals.
    let x = norm_post;
    let mut score = 12.0 * x - 8.0 * x * x + 16.0 * x * x * x;

    // Tight fit reward: smooth coupling of item size with post residual.
    // Large items leaving small residuals get extra reward.
    let tightness = 1.0 - norm_post;
    let size_factor = item / cap;
    score -= 6.0 * tightness * tightness * (0.5 + size_factor);

    // Dead-space hazard: residuals too small for typical future items.
    // Smooth sigmoid-like gate around half capacity.
    let gate = 1.0 / (1.0 + (norm_post - 0.45) * 14.0).exp();
    score += 5.0 * gate * (1.0 - progress) * norm_post;

    // Stream-progress coupling: late in the stream, waste is costlier.
    let late = progress * progress;
    score += 8.0 * late * norm_post;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post residual, reward heavily;
    // smooth reward decaying with mismatch.
    if next_item_size > 0 {
        let mismatch = (post_residual as f64 - next_item_size as f64).abs() / cap;
        score -= 7.0 * (1.0 - 2.0 * mismatch).max(0.0) * (1.0 - mismatch);
    }

    // Crowd-out penalty: many open bins with high mean residual suggests
    // fragmentation; discourage adding to it mildly, encourage consolidation.
    let frag = mean_residual / cap - norm_post;
    score += 2.0 * frag.max(0.0);

    // New-bin candidate handling: an empty bin has norm_post == 1.0.
    // Its polynomial base is high; only open a new bin when no existing bin
    // offers a reasonable fit (item large relative to best residual is
    // captured by the other bins' scores already). Add a mild adaptive
    // discount so a fresh bin beats very poor fits late in the stream.
    if bin_residual == bin_capacity {
        score -= 4.0 + 3.0 * late + size_factor * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any future item
    // (min item size 1..100 unknown, so treat < ~15 as likely dead) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 20.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is excellent
    } else {
        // larger residuals are more reusable: mild reward relative to baseline
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fits
    // and penalize placements leaving large slack.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.05;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; dead space risk rises with small post_residual
            score += (post_residual as f64).min(40.0) * 0.3;
        }
    }

    // Prefer bins below mean residual when mean residual is high (balance loads).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // New-bin candidate: only attractive when current bin fits are all poor
    // (large post_residual waste). Make fresh bin mildly costly otherwise.
    if bin_residual == bin_capacity {
        score += 8.0 + pressure * 3.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin keeps full flexibility
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // this is a chained perfect fit -> heavily favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 900.0;
    }
    // Next item fits in the leftover space -> mild reward proportional to closeness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
    }
    // Next item does NOT fit in leftover -> penalize dead space creation,
    // worse when leftover is small (unusable).
    else if next_item_size > 0 {
        score += 30.0;
    }

    // Penalize tiny unusable leftovers (below typical small item size).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer bins tighter than the mean residual (best-fit style coupling).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be slightly more willing to open bins (score new bins better),
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it's early or nothing fits well.
        score += 80.0 - 60.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
