    score += 20.0 * w_early * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 30.0 * w_late * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space relative to next item's need (smooth quadratic mismatch).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        score += 15.0 * gap * gap * cap;
        // Reward exact-ish preparation for next item, weighted by progress
        score -= 10.0 * progress * (-gap * gap);
    }

    // Last-chance bonus: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * 0.5);
    }

    // Slight penalty when bin residual far from mean residual (keeps bin pool balanced).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: penalize mildly unless current residuals are all tight.
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits strongly (non-linear squashing of post-residual).
    let tight = post / cap;
    score -= 12.0 * (1.0 - tight).powi(6);

    // Penalize dead space: residuals too small for typical items (1..100 unknown, mid ~30).
    if post > 0.0 && post < 20.0 {
        score += 18.0 * (20.0 - post) / 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual; penalize if it barely misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else if nxt - post <= 15.0 {
            score += 6.0 * (nxt - post) / 15.0;
        }
    }

    // New-bin candidate logic: only attractive when open bins are crowded or fit would be awful.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let fit_quality = (bin_residual - item_size) as f64 / cap; // best achievable fit elsewhere proxy
        let poor_fit_elsewhere = (post_residual as f64) > 0.45 * cap;
        if poor_fit_elsewhere && mean_residual < 0.35 * cap {
            score -= 20.0 + 10.0 * progress + crowded;
        } else {
            score += 30.0 + 15.0 * (1.0 - progress);
        }
        let _ = fit_quality;
    } else {
        // Mild preference for fuller bins among open bins.
        score -= 4.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Global balance: if mean residual is high, encourage consolidation into open bins.
    if mean_residual > 0.5 * cap && !is_new_bin {
        score -= 5.0 * (mean_residual / cap - 0.5);
    }

    score
}

