pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    let min_item = 1u32; // items can be as small as 1; but typical dead space threshold
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize residual that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.0;
        } else {
            score -= 5.0;
        }
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or residual is tight
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(2) as f64);
        score += 20.0 + 60.0 * (1.0 - progress);
    }

    // Mild preference for bins with residual close to item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Mean residual alignment: prefer bins near the mean (balanced usage)
    score += (bin_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward post_residual that exactly matches next_item_size ---
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: strong reward, scaled up as stream progresses.
        if gap == 0.0 {
            score -= 40.0 + 30.0 * progress;
        } else {
            // Penalize mismatch, but only if the next item could still fit.
            if post_residual >= next_item_size {
                score += gap * 0.5;
            } else {
                // Next item cannot follow: dead space penalty grows with gap.
                score += gap * 0.9;
            }
        }
    } else {
        // Last item: pure tightness matters most.
        score += 10.0;
    }

    // --- Tightness reward: small post_residual relative to mean residual is good ---
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) < mean_r {
        score -= (mean_r - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_r) * 0.15;
    }

    // --- Last-chance bonus: if this is the only bin that fits, avoid opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: empty bin should only win when fits are poor ---
    if bin_residual == bin_capacity {
        // Base penalty so new bins lose against decent fits...
        score += 45.0;
        // ...but if many open bins exist with high mean residual (fragmented state),
        // opening a fresh bin becomes more attractive.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        if mean_r > 0.5 * bin_capacity as f64 {
            score -= 20.0;
        }
        // Late in the stream, slightly discourage spawning bins.
        score += 20.0 * progress;
    }

    // --- Discourage leaving residuals that are too small to be useful (dead space) ---
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space under
    // the smallest possible item (<= 10) is pure waste. Penalize residuals
    // in the "dead zone" more aggressively than raw post_residual does.
    let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
    score += dead * 2.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but not perfectly: mild reward proportional to fill
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize large leftovers
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Compare against mean residual: bins with residual much below the mean
    // are "tight" and should be filled first to consolidate small leftovers.
    let tightness = mean_residual - bin_residual as f64;
    score -= 0.3 * tightness;

    // Time horizon: early in the stream, be conservative (favor filling
    // existing bins); late in the stream, allow more aggressive bin opening
    // only for very tight fits. Modulate the new-bin penalty accordingly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= progress * 10.0 * fill_ratio;

    // Discourage opening a fresh bin when decent open bins exist,
    // unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { -8.0 } else { 6.0 };
        score += 15.0 + large_item_bonus + 0.05 * open_bins_count as f64;
    }

    // Small global congestion term: many open bins -> prefer consolidation.
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // early on, larger residuals are fine; late, we penalize wasted space more strongly
    let progress_coupling = pr * (progress * progress) * 0.8;
    score += progress_coupling;

    // Perfect fit reward (smooth, non-linear in item_size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the lookahead item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let unusable = (gap / cap) * (gap / cap) * cap * 0.3;
        score += unusable;
        // Reward residuals that exactly (or nearly) fit the next item
        let next_fit = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= 10.0 * next_fit * next_fit * next_fit;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open and this placement leaves large residual
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += open_pressure * norm_pr * 15.0 * (1.0 - progress);

    // Deviation from mean residual (smooth quadratic): prefer bins near the mean
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: make it attractive only for large items with poor fits
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        // new bin starts with full residual; score relative to best possible placement
        score = pr + 8.0 - 18.0 * fit_ratio * fit_ratio - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fills are perfect, small remainders are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 5 {
        score += 25.0; // tiny unusable sliver
    } else if pr <= 10 {
        score += 10.0;
    } else if pr <= 20 {
        score -= 5.0; // still useful for small items
    }

    // Integer-division thresholds on post_residual: classify by quarters of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr >= half {
        score -= 12.0; // half-open residual, very reusable
    } else if pr >= quarter {
        score -= 3.0;
    } else {
        score += 8.0; // below quarter: mostly dead space
    }

    // Coupling with next item (lookahead): reward leaving exactly room for it.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 40.0;
        } else if pr > next_item_size && (pr - next_item_size) <= 10 {
            score -= 20.0; // next item fits with small waste
        } else if pr < next_item_size && next_item_size - pr <= 10 {
            score += 15.0; // near-miss teases a bad fit
        }
        // modulo harmony: residual divisible chunks matching next item class
        if next_item_size >= 10 && pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals are poor.
    if bin_residual == bin_capacity {
        // neutral base; penalize opening when mean residual is healthy
        score = 70.0 + mean_residual * 0.4 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can host both big items
        }
    }

    // Late-stream consolidation: prefer tightening existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (below min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward gap" penalty: residual too small for a typical next item.
    if post_residual > 0 && post_residual < next_item_size as f64 * 0.9 && next_item_size > 0 {
        score += 25.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate handling: empty bin starts with a big handicap,
    // but becomes attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }

    // Mild progression scaling: tighten criteria later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 1.0 {
            // Perfect 2-step match: next item exactly consumes leftover.
            score -= 60.0;
        } else if nxt <= post {
            // Next item fits: reward proportional to tightness of the pair fit.
            let pair_tightness = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 25.0 * pair_tightness;
        } else {
            // Next item cannot fit in residual: penalize dead space scaled by overshoot.
            let overshoot = (nxt - post) / bin_capacity as f64;
            score += 15.0 * overshoot;
        }

        // Extra bonus if both current and next item leave near-zero residual combined.
        if post >= nxt && post - nxt < 5.0 {
            score -= 20.0;
        }
    } else {
        // Last item: minimize post residual strongly.
        score += (post_residual as f64) * 0.5;
    }

    // Penalize residuals far below mean residual (creating unusable small holes
    // relative to the fleet average), reward bins with large residuals absorbing big items.
    let mean_gap = (post_residual as f64) - mean_residual;
    if mean_gap < 0.0 {
        score += 0.3 * (-mean_gap);
    } else {
        score -= 0.15 * mean_gap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins early/mid stream; slight relief late.
        score += 45.0 - 15.0 * progress;
        // If many fitting bins exist, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Mild preference for tighter fits overall.
    score += 0.2 * (post_residual as f64) / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Items are 1..=100; residual below the smallest item threshold is dead.
    let dead = if post_residual == 0 { 0.0 } else if post_residual < 10 { 60.0 } else { 0.0 };
    score += dead;

    // Lookahead coupling: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // Placing here ruins a residual that could serve the next item — mild penalty.
        score += 8.0;
    }

    // Last-chance bonus: this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state: penalize spreading across many open bins when residuals are large.
    let residual_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * residual_gap;

    // Time horizon: early in the stream, prefer consolidation (favor existing bins);
    // late in the stream, dead space matters less so tighten fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a moderate default score,
    // lowered only when no existing bin fits well or stream is early with few bins.
    if bin_residual == bin_capacity {
        let base = 55.0;
        let relief = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        score = base - relief + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tight fits matter more (amplify small residuals); later, tolerate slack
    let tightness = 1.0 - (pr / cap).powf(2.0 + progress * 3.0);
    let coupling = tightness.powf(1.0 + 2.0 * progress);
    score -= 12.0 * coupling * (1.0 - progress);

    // Penalize dead space relative to mean residual (smooth interaction)
    let dead = (pr - mean_residual).max(0.0);
    score += 0.05 * dead * dead / cap;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward residual that can still hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for opening a new bin when others fit (empty-bin candidate)
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic classes of post_residual (modulo / integer-division thresholds) ---
    // Class 0: perfect fit (post_residual == 0) -> strongest reward
    // Class 1: tiny dead space (1..=5) -> nearly as good
    // Class 2: mid residual (6..=20) -> mildly penalized unless next item fits
    // Class 3: large residual (>20) -> bin stays reusable, mild reward
    let post_class: u32 = if post_residual == 0 {
        0
    } else if post_residual <= 5 {
        1
    } else if post_residual <= 20 {
        2
    } else {
        3
    };

    match post_class {
        0 => { score -= 60.0; }
        1 => { score -= 45.0; }
        2 => {
            score += 8.0;
            // reward if next item can land in the leftover space
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
            }
        }
        _ => {
            // large leftover: reward proportionally to how "harmonically divisible"
            // the residual is by common item-size granularities
            let mut div_bonus = 0.0;
            for g in [10u32, 20, 25, 40, 50] {
                if post_residual % g == 0 {
                    div_bonus += 6.0;
                }
            }
            score -= 10.0 + div_bonus;
        }
    }

    // --- Modulo-10 granularity coupling: items and residuals aligned to 10s pack well ---
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 4.0;
    }

    // --- Lookahead: penalize if this placement strands the next item ---
    if next_item_size > 0 {
        let next_fits_here = next_item_size <= post_residual;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if !next_fits_here {
            // penalty grows late in the stream (less time to recover)
            score += 6.0 + 10.0 * progress;
        } else {
            score -= 3.0;
        }
    }

    // --- Last-chance bin: strongly favor using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- New-bin candidate handling: only attractive when no open bin fits well ---
    if bin_residual == bin_capacity {
        // baseline cost of consuming a fresh bin
        let mut new_bin_score = 35.0;
        // early in stream: opening bins is cheaper (builds a portfolio)
        new_bin_score -= 25.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // many open bins with slack: discourage another
        new_bin_score += 2.0 * open_bins_count as f64;
        // if mean residual is large, existing bins likely suffice
        new_bin_score += 0.3 * mean_residual;
        // big items with no good home: new bin is fine
        if item_size > bin_capacity / 2 && (fitting_bins_count == 0 || post_residual < 10) {
            new_bin_score -= 20.0;
        }
        score = new_bin_score;
    } else {
        // mild preference for filling bins that are already partially loaded
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 8.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that nothing (>= 1..=100 range,
    // but realistically >= next_item_size) can use are heavily penalized.
    if post_residual > 0 {
        let unusable = (next_item_size as f64) - (post_residual as f64);
        if next_item_size > 0 && unusable > 0.0 {
            // The gap is too small for the next item: dead space.
            score += 3.0 * unusable;
        }
        // Absolute tiny-gap penalty: gaps <= 10 are almost certainly waste.
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual < 20 {
            score += 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 20.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Pressure from number of open bins: prefer consolidating into fewer bins,
    // but only mildly, so dead-space logic dominates.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual is already below the mean (consolidate smalls).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Late in the stream, tighten up: penalize loose fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins less attractive unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow new bins early or when item is large relative to mean residual.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain fit: strong reward.
            if slack == 0.0 {
                score -= 60.0;
            } else if slack <= 10.0 {
                score -= 40.0 - slack * 2.0;
            } else {
                // Mild reward proportional to how well next item nests.
                score -= 20.0 * (next_item_size as f64 / post_residual as f64);
            }
        } else {
            // Next item won't fit here: penalize leaving large unusable residue.
            let waste = post_residual as f64;
            if waste > 0.0 && waste < (item_size as f64).min(next_item_size as f64) {
                score += 25.0; // dead space smaller than any plausible item
            }
        }
    }

    // Compare post_residual against mean residual: prefer bins that become
    // tighter than average (good packing) rather than looser.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Slight preference for filling fuller bins early vs late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin would leave tiny waste
    // and the next item is small enough that a fresh bin makes sense.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / cap;
    score -= (1.0 - tightness) * (1.0 - tightness) * 40.0;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that no future item can plausibly use:
    // if post_residual is smaller than the minimum plausible item, it's waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // Next item won't fit here: mild penalty proportional to leftover.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless the item
    // is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut new_bin_cost = 90.0
            - item_size as f64 * 0.6
            - fragmentation * 0.3
            - progress * 15.0;
        // Don't open a new bin when a decent fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual * 0.5 {
            new_bin_cost += 30.0;
        }
        score += new_bin_cost;
    } else {
        // Prefer bins with residual above the mean (keep small holes consolidated).
        let dev = bin_residual as f64 - mean_residual;
        score -= dev * 0.2;
    }

    // Mild bonus for spreading across bins when many bins are open (balance load).
    if open_bins_count > 4 && post_residual as f64 >= mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let poly = pr * pr / (bin_capacity as f64 * bin_capacity as f64);
    score += poly * (1.0 + progress) * 8.0;

    // Reward tight fits increasingly as stream progresses
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= tightness * tightness * (10.0 + 20.0 * progress);

    // Penalize dead space relative to mean residual
    let dead = (pr - mean_residual).abs();
    score += dead * 0.15 * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: favor bins whose post_residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    } else if next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.1;
    }

    // Mild penalty for spreading across many bins late in stream
    score += (open_bins_count as f64).ln() * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: waste classes in residue mod 10
    let waste_class = post_residual % 10;
    // Dead-space penalty: small non-zero residuals are worst (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward
        score -= 60.0;
    } else {
        // Reward residuals in reusable classes (multiples of 10)
        if waste_class == 0 {
            score -= 12.0;
        }
    }

    // Harmonic fraction: how close post_residual is to a capacity fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals in awkward middle band (0.3..0.7) mildly
    if frac > 0.3 && frac < 0.7 {
        score += 6.0 * (1.0 - (2.0 * frac - 1.0).abs());
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // harmonic class of leftover after next item
            if slack % 10 == 0 {
                score -= 15.0;
            } else if slack < 10 {
                score += 10.0;
            }
        } else {
            // next item cannot use this bin's remainder: mild penalty
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish but should lose to decent fits,
    // win only when no open bin gives a reasonable class
    if bin_residual == bin_capacity {
        score += 25.0;
        // late in stream, opening new bins is cheaper than fragmentation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // if many open bins already, discourage proliferation
        score += 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (i.e., tighter bins), pushing toward filling nearly-full bins
    score -= 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any item (1..10)
    // are pure waste. Penalize them super-linearly.
    if post_residual >= 1 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Medium dead space (10..20) can only fit small items; mild penalty.
    else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 10 {
        // small-but-usable residual is fine if next item can use it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        }
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 20.0; // residual unusable for next item too
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 80.0 + open_bins_count as f64 * 2.0;
        // If no existing bin leaves a usable residual for the next item, opening
        // a fresh bin is more attractive.
        let poor_fits = mean_residual < item_size as f64 * 0.15;
        if poor_fits {
            score -= 70.0;
        }
        // Late in the stream, waste in a fresh bin matters less.
        score -= progress * 10.0;
    } else {
        // Prefer bins whose current residual is close to item size (tight fit).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        if gap < 0.5 {
            score -= 60.0;
        } else if gap <= 5.0 {
            score -= 25.0 * (1.0 - gap / 5.0);
        } else {
            // Penalize dead space beyond what the next item can use.
            let excess = (post_residual as f64 - next).max(0.0);
            score += 0.15 * excess;
        }

        // If next item also fits this bin's post-residual, mild reward.
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 10.0;
    }

    // Prefer bins tighter than the mean residual (well-packed bins).
    score += 0.1 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless post_residual is huge dead space.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual > 40 {
            score += 0.2 * (post_residual as f64 - 40.0);
        }
    }

    // New-bin candidate: only attractive when existing bins would leave large waste.
    if bin_residual == bin_capacity {
        score = (post_residual as f64) + 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin pairs perfectly with a large current item.
            if item_size + next_item_size <= bin_capacity {
                score -= 20.0;
            }
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate as the stream progresses.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core: penalize wasted space quadratically (dead space is unusable)
    score += (post_residual as f64).powi(2) / cap;

    // Tight fit reward: small post_residual is very desirable
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly into post_residual
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let slack = (post_residual - next_item_size as u32) as f64;
        score -= 18.0 * (1.0 - slack / cap);
    }
    // Penalize if next item almost fits but not quite (near-miss lookahead)
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        let miss = (next_item_size as u32 - post_residual) as f64;
        if miss <= 15.0 {
            score += 12.0 * (1.0 - miss / 15.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score += 0.35 * crowding;
    // Reward filling bins when mean residual is low (late-phase consolidation)
    score -= 0.10 * mean_residual * (open_bins_count as f64);

    // Time horizon: early in stream, be pickier about residual (keep bins flexible);
    // late in stream, prioritize closing bins out.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - t) * (post_residual as f64 / cap);
    score -= 10.0 * t * (1.0 - post_residual as f64 / cap);

    // New-bin candidate: only attractive when existing fits are poor or none are tight
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / cap) > 0.55 || fitting_bins_count == 0;
        if poor_fit {
            score -= 45.0;
        } else {
            score += 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual, smoothed by a quadratic coupling.
    let mut score = post * (1.0 + 0.35 * post / cap);

    // Non-linear stream-progress coupling: waste tolerance shrinks as stream advances.
    let urgency = 0.5 + 1.5 * progress * progress;
    score *= urgency;

    // Reward tight fits (small post_residual relative to item size) via a smooth ratio.
    let tightness = 1.0 - (post / cap).powf(1.5);
    score -= 6.0 * tightness * (item / cap);

    // Lookahead: penalize leaving a residual that cannot host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // next item fits: slight reward proportional to how well it nests
            let nest = 1.0 - ((post - nxt) / cap);
            score -= 3.0 * nest * (nxt / cap);
        } else {
            // next item won't fit here: penalize dead space, worse late in stream
            score += 4.0 * (nxt - post) / cap * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Penalize opening a brand-new bin when open bins could fit (unless residual is huge).
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
        // A new bin is acceptable only if existing bins are very full (low mean residual).
        score += 0.15 * mean_residual;
        // With many open bins, prefer consolidation.
        score += 0.05 * open_bins_count as f64;
    }

    // Mild penalty for extreme fragmentation: very small post residual is fine, but
    // mid-range residuals (~20-40) are awkward; apply a smooth bump.
    let mid = (post - 30.0) / 15.0;
    score += 2.5 * (-mid * mid) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction of the item
    let item_frac = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fills: post_residual in "harmonic" classes
    // Class 0: exact fit (post_residual == 0) -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class 1: tiny dead space (<= 10) is fine only if next item can use it
        if post_residual <= 10 {
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 60.0;
            } else {
                score += 40.0; // dead space penalty
            }
        }
        // Class 2: post_residual divisible into useful chunk sizes (mod classes)
        let mod10 = post_residual % 10;
        let mod20 = post_residual % 20;
        if mod10 == 0 {
            // residual aligns with 10-unit grid: next items likely fit
            score -= 25.0;
        }
        if mod20 == 0 {
            score -= 10.0;
        }
        // Harmonic penalty: residual in awkward band (11..=19) is hard to fill
        if post_residual % 10 >= 1 && post_residual <= 19 {
            score += 15.0;
        }
    }

    // Integer-division threshold on post_residual: how many "half-capacity" chunks
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual >= half {
        // residual still large: bin is flexible, mild reward scaled by fraction
        score -= 20.0 * post_frac;
    } else if post_residual >= quarter {
        // mid band: neutral-ish, slight penalty to avoid fragmenting
        score += 5.0;
    } else {
        // small residual: penalize unless next item exploits it
        if next_item_size == 0 || next_item_size > post_residual {
            score += 30.0 * (1.0 - post_frac);
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        let leftover = post_residual - next_item_size;
        if leftover % 10 == 0 {
            score -= 40.0;
        } else {
            score += leftover as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: fresh empty bin
    if bin_residual == bin_capacity {
        // Prefer new bin when item is large and open bins are fragmented
        let fragmentation = mean_residual / open_bins_count.max(1) as f64;
        if item_frac > 0.5 {
            score -= 70.0 * item_frac;
        }
        // But penalize opening new bins when plenty of space exists already
        if mean_residual > item_size as f64 * 2.0 {
            score += 45.0;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        let _ = fragmentation;
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    // Small bonus for consolidating when many bins are open
    if open_bins_count > 8 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.5;
    } else {
        score -= 2.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: dead space likely.
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward residuals that exactly fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 800.0;
        } else if post_residual as u32 >= next_item_size {
            // next item fits here afterwards: reward closeness of post_residual to next size
            let gap = (post_residual as f64) - nxt;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // dead space for the next item: penalize proportionally
            score += 60.0 * (nxt - post_residual as f64) / 100.0;
        }
    }

    // Penalize tiny unusable residuals (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when other bins fit; relax if item is large relative to residual space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 90.0 + 60.0 * progress;
        if fitting_bins_count > 0 {
            new_bin_penalty += 80.0;
        }
        if item_size >= 70 {
            new_bin_penalty *= 0.3;
        }
        score += new_bin_penalty;
    }

    // Slight preference for filling larger residual bins when item is large.
    if item_size > 50 {
        score -= 0.2 * (bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure: reward tight fits.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.9;

    // Penalize small unusable dead space (waste zones).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose leftover could host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if leftover matches next item almost exactly.
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 10.0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Leftover too small for next item: mild penalty scaled by waste.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Scarcity pressure: fewer fitting bins -> keep good fits.
    if fitting_bins_count > 0 {
        score -= 3.0 / fitting_bins_count as f64;
    }

    // Prefer bins below mean residual (fill emptier bins less; keep balanced).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Time horizon: early on, be more willing to open new bins (penalize
    // consuming tight space); late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // Consolidation: many open bins -> favor filling existing ones.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer filling bins that are already more than half full.
    if bin_residual <= bin_capacity / 2 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space, amplified as stream progresses.
    let mut score = pr * (1.0 + 2.0 * progress * norm_pr);

    // Cubic coupling: heavily punish tiny residuals early (dead space), less late.
    score += norm_pr * norm_pr * norm_pr * cap * (1.0 - progress);

    // Perfect fit reward (near-zero residual).
    if post_residual == 0 {
        score -= 25.0 + 25.0 * progress;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let gap = (post_residual as f64 - nxt) / cap;
            score -= 8.0 * (1.0 - gap) * (1.0 - progress);
        } else {
            // next item won't fit here; penalize leaving large unusable gap
            score += 4.0 * (nxt / cap) * norm_pr;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral baseline, penalize if open bins are scarce/fragmented.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) + mean_residual * 0.5;
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Mild dispersion incentive: prefer bins deviating from mean residual (consolidation).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res_frac = pr / cap; // fraction of capacity left over

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: residuals divisible by common item sizes are reusable
    let harmonic_bonus = if post_residual >= 10 && post_residual % 10 == 0 {
        12.0
    } else if post_residual % 20 == 0 {
        9.0
    } else if post_residual % 5 == 0 {
        6.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead space penalty for tiny unusable residuals (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (10.0 - pr) / 10.0;
    }

    // Next-item lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 4.0 * res_frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a bin is costly unless current bins are nearly full
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // if many fitting bins exist, opening new bin is wasteful
        if fitting_bins_count > 0 {
            score += 40.0;
        }
        // early in stream, allow new bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if mean residual across open bins is small, new bin is justified
        if mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Slight preference for filling fuller bins (smaller residual before placement)
    score += 0.05 * (bin_residual as f64 - item_size as f64) * 0.0;

    // Mild penalty proportional to wasted fraction, quadratic in residual fraction
    score += 20.0 * res_frac * res_frac;

    // Tie-break: prefer bins whose residual is close to item (tight fit)
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are pure waste — penalize them super-linearly.
    if post_residual > 0 {
        // Any leftover that cannot fit the next item is dead space too.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // Very small absolute gaps (< 10) are almost always unusable.
        if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 20 {
            score += 12.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferating bins when few exist,
    // but allow it when many open bins already exist (consolidate instead).
    if bin_residual == bin_capacity {
        // Candidate is a brand-new bin: penalize more when open bins are few
        // and when mean residual suggests space exists elsewhere.
        let pressure = 15.0 + 2.0 * open_bins_count as f64;
        score += pressure + 0.3 * mean_residual;
        // Early in the stream, opening new bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Using an existing bin: mild reward scaled by congestion.
        score -= 1.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (minimal slack).
    let slack = (bin_residual - item_size) as f64;
    score += 0.1 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Perfect chain: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * diff;
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Post-residual too small to fit the next item: dead space penalty.
        if post_residual < next_item_size {
            score += 0.9 * (next_item_size - post_residual) as f64;
        }
        // Post-residual large enough to hold next item comfortably: reward tight packing.
        if post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 8.0;
        }
    } else {
        // Last item: minimize leftover as tightly as possible.
        score -= 10.0;
    }

    // Tight fit reward relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Penalize bins far tighter/looser than the fleet mean (keep residual spread low).
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: penalize unless the item is huge or fit is desperate.
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size >= 60 {
            score -= 14.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Early in the stream: tolerate new bins (future flexibility); late: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize small post-residuals that are too small for the next item but still "wasted".
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Dead space: next item cannot use this residue.
            score += 0.35 * post_residual as f64;
        } else if post_residual >= next_item_size {
            // Reward leaving room exactly for the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (-slack / 15.0).exp();
        }
    } else {
        // Last item: prefer fullest packing, any residual is pure waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // global residuals are large/fragmented or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        // Cost of a fresh bin decreases when existing bins are fragmented
        // and the item is large; increases early in the stream.
        score = 100.0 * (1.0 - big_item) + 60.0 * fragmentation * (1.0 - progress) + 20.0 * (1.0 - fragmentation);
        // Never open a new bin if this is the only fitting bin among open ones.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
        // If lookahead fits into current mean residual, prefer open bins.
        if next_item_size as f64 <= mean_residual {
            score += 15.0;
        }
    }

    // Mild preference for bins with below-average residual (consolidate waste).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Slight bonus for using fuller bins as stream progresses (harvest bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize opening many bins when open count is already high relative to items.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress - 0.15 * progress);

    // Penalize large dead space quadratically, modulated by progress
    let waste = (pr / cap).powi(2);
    score += 12.0 * waste * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / cap;
    score -= 6.0 * tightness * (1.0 - waste);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
