    // Mild penalty for proliferating open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - pr / cap).abs();

    // New-bin candidate: prefer it only when post_residual is large and progress is low
    if bin_residual == bin_capacity {
        score = pr * (1.0 + 0.5 * (1.0 - progress)) + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
