        score += 10.0 + 0.3 * mean_residual;
        if item_size > 70 {
            score -= 15.0; // big items may justify a fresh bin
        }
    } else {
        // Prefer tighter bins: reward small residual relative to mean
        score -= 5.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;
    }

    // Slight late-stream pressure to consolidate into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (dead space elimination).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize large post-residuals superlinearly (unusable dead space).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if this placement would leave a gap that blocks the next item, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: opening a new bin is attractive early in the
    // stream or when many items remain, and when current bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        // Prefer new bin when open bins are fragmented and it's early/mid stream.
        score -= 20.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        // But discourage new bin if an existing bin fits almost perfectly.
        if post_residual == 0 && item_size < bin_capacity {
            score += 55.0;
        }
        // Penalize new bin if mean residual across open bins is large (plenty of room).
        score += 0.25 * mean_residual;
        let _ = fragmentation;
    } else {
        // Favor bins whose residual is close to the mean (balanced usage),
        // mildly discouraging outlier bins.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.85 && is_new_bin {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual (tight packing).
    let mut score = post;

    // Normalized post residual fraction.
    let post_frac = post / cap;

    // Smooth non-linear penalty for small-but-unusable dead space:
    // dead space that cannot fit a typical item is worse; couple with progress
    // (dead space matters more early, when bins stay open longer).
    let deadness = (1.0 - post_frac).powi(2) - (1.0 - post_frac).powi(4);
    score += 30.0 * deadness * (1.0 - progress);

    // Reward tight fits: quadratic decay of reward as post residual grows.
    let tightness = (1.0 - post_frac).max(0.0);
    score -= 25.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, scaled smoothly by stream progress.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead coupling: if the next item fits exactly into post residual,
    // reward; if post residual is just barely too small for next item, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let match_bonus = (1.0 - gap / cap).max(-1.0);
        score -= 15.0 * match_bonus * match_bonus * match_bonus.signum().max(0.0);
        if post < nxt && post > 0.0 {
            score += 10.0 * (nxt - post) / cap * (1.0 - progress);
        }
    }

    // Mild penalty when this bin's residual deviates from mean residual,
    // encouraging balanced residual distribution (smooth coupling).
    let dev = (post - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Slight preference for filling already-open bins as open bin count grows.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * post_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 8 octiles.
    // Small post_residual classes (tight fits) are strongly rewarded.
    let class = (post_residual * 8 / bin_capacity.max(1)) as i32; // 0..=7
    let class_reward = [12.0, 9.0, 6.5, 4.5, 3.0, 2.0, 1.0, 0.0][class.clamp(0, 7) as usize];
    score -= class_reward;

    // Perfect-fit bonus: leftover is exactly 0 or a "harmonic" residue (divides capacity).
    if post_residual == 0 {
        score -= 25.0;
    } else if bin_capacity % post_residual == 0 {
        // leftover can be tiled exactly by future items of that size
        score -= 6.0;
    }

    // Dead-space penalty: leftover too small for the minimum plausible item (1..100 unknown,
    // but use item_size as a proxy floor for the local distribution).
    let floor_size = item_size.min(next_item_size.max(1));
    if post_residual > 0 && post_residual < floor_size {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // prefer leaving room proportional to how well next item fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 4.0 * fill;
        } else {
            // next item won't fit here: slight penalty, this bin becomes dead-ends
            score += 2.0;
        }
        // harmonic class match: next item size in same capacity-fraction class as residual
        let nclass = (next_item_size * 8 / bin_capacity.max(1)) as i32;
        if nclass == class {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 8.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize mildly so we prefer reusing
    // open bins with decent fits, but keep it competitive when all fits are bad.
    if bin_residual == bin_capacity {
        score += 14.0;
        // late in the stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
    }

    // Prefer bins below mean residual (pack fuller bins first) — mean-reversion term.
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Congestion: many open bins -> push toward consolidating into tightest fits.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let min_item = 10.0; // smallest plausible item size; residual below this is pure dead space

    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is expensive: penalize, growing with how many
        // bins are already open (pressure to consolidate into open bins)
        // and slightly with stream progress.
        score += 45.0 + open_bins_count as f64 * 2.5 + progress * 15.0;
    } else {
        // Perfect fit: eliminate all dead space.
        if post_residual == 0 {
            score -= 60.0;
        } else {
            // Strict dead-space avoidance: residual that no item can ever use
            // is worse than the raw number suggests.
            if (post_residual as f64) < min_item {
                score += (min_item - post_residual as f64) * 3.0 + 20.0;
            }
            // Lookahead coupling: reward bins that can also swallow the next item,
            // penalize bins whose leftover just misses it (near-dead space).
            if next_item_size > 0 {
                if post_residual >= next_item_size {
                    score -= next_item_size as f64 * 0.5;
                } else {
                    score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
                }
            }
            // Last-chance bin: if this is the only bin that fits, use it to
            // avoid opening a new bin.
            if fitting_bins_count == 1 {
                score -= 15.0;
            }
            // Mild preference for fuller bins (best-fit reinforcement).
            score += (bin_residual as f64 / cap) * 4.0;
        }
    }

    // As the stream progresses, tighten tolerance for wasted space.
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item leaves only a tiny sliver.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (20.0 * (-slack / 25.0).exp());
    }

    // Next item does NOT fit here: penalize proportionally to wasted lookahead opportunity.
    if next_item_size > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 + 0.4 * miss;
    }

    // Penalize large dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Brand-new empty bin candidate: make it unattractive unless current bin would
    // leave unusable dead space or the item is huge and next item needs fresh space.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Opening fresh is fine when this big item plus next item pair well.
            score -= 20.0;
        }
    }

    // Slight late-stream conservatism: prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - (slack as f64 / bin_capacity as f64).min(1.0));
        } else {
            // Next item won't fit here: penalize proportionally to waste.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be pickier about loose fits.
        score += 0.1 * (fitting_bins_count as f64 - 3.0) * post_residual as f64;
    }

    // Global state: when many bins are open, discourage spreading; prefer filling.
    let open_pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).max(1.0) / 20.0);
    score += 2.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below average, it is
    // an outlier bin; finishing it off is good.
    let dev = mean_residual - (post_residual as f64);
    if dev > 0.0 {
        score -= 0.3 * dev;
    } else {
        score += 0.15 * (-dev);
    }

    // Time horizon: early in the stream, be conservative about opening bins;
    // late in the stream, allow new bins more readily (less future to plan for).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later.
        score += 60.0 * (1.0 - progress) - 10.0 * progress;
        // If no open bin fits well, new bin becomes attractive.
        if post_residual == 0 {
            score -= 0.0; // item exactly fills a new bin
        }
    } else if progress < 0.5 {
        score += 5.0 * (1.0 - 2.0 * progress);
    }

    // Exact fit celebration.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, dead space matters more -> penalize large residuals
    let coupling = norm_post * (progress * (1.0 - progress) * 4.0); // peaks mid-stream
    score += 20.0 * norm_post * norm_post * (1.0 - coupling);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 5.0 * ((nxt - post) / cap);
        }
    }

    // Mild penalty for spreading across many open bins vs. mean residual alignment
    score += 0.05 * open_bins_count as f64;
    score += 0.1 * (post - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Harmonic class of post_residual: dead space classes are small leftovers
    let dead = post_residual < 10 && post_residual > 0;
    if dead {
        score += 25.0; // tiny unusable sliver
    }

    // Modulo-class coupling: post_residual divisible by common item sizes is reusable
    let pr = post_residual as u32;
    let reusable = (pr >= 10) && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0);
    if reusable {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // extra reward for near-perfect two-item packing
            if pr == next_item_size {
                score -= 20.0;
            }
        } else {
            score += 8.0;
        }
    } else {
        // last item: prefer fullest packing
        score -= 10.0 * fill;
    }

    // Last chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fits poorly
    if bin_residual == bin_capacity {
        let waste_if_open = bin_capacity as f64 - item_size as f64;
        score = bin_capacity as f64 + waste_if_open * 0.5;
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64; // must open a bin
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer bins already below mean residual (consolidate emptier bins)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Many open bins: discourage spreading
    if open_bins_count > 4 && bin_residual > item_size {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever fit
    // another item (min size 1..100, but typical small items ~10) are pure waste.
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0; // unusable gap penalty
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize medium dead space lightly, scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 20.0 * (0.5 + progress);

    // Open-bin pressure: discourage spreading across many bins when residuals are healthy
    score += open_bins_count as f64 * 1.5 * (mean_residual / bin_capacity as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 15.0; // would strand this residual
    }

    // New-bin candidate: keep it competitive only when no open bin fits well
    if bin_residual == bin_capacity {
        // opening a new bin leaves full residual; slight inherent penalty
        score += 8.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // open a fresh bin when open bins are fragmented
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by the base term.

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // strongly reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // If next item fits into post_residual, mildly reward proportional closeness.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let waste = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - waste / bin_capacity as f64);
    }
    // If next item cannot fit here, penalize leaving a mid-range dead zone.
    else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Penalize small unusable residuals (< 10) unless perfect fit achieved.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better candidates.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize it progressively as the stream fills up.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 15.0 * progress;
        // But if next item is large and current fit would strand space, allow new bin.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) && (bin_capacity - item_size) >= next_item_size {
            score -= 40.0;
        }
    }

    // Slight penalty for proliferating open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post-residual is small.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that cannot hold typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are nearly useless
    }

    // Lookahead coupling: if the next item fits the post-residual, reward;
    // if next item is large and post-residual is too small, mild penalty.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes residual elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of a new bin; cheaper late in the stream or when few bins fit.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 15.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            new_bin_cost = 0.0; // no alternative
        } else if fitting_bins_count == 1 {
            new_bin_cost += 30.0; // strongly prefer using the single fitting bin
        }
        // If open bins have large mean residual, opening new bins is worse.
        new_bin_cost += mean_residual * 0.15;
        score += new_bin_cost;
    }

    // Mild preference for bins below mean residual (balance residual spread),
    // keeping fragmented space concentrated rather than spread everywhere.
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Slight scaling with number of open bins: when many bins are open,
    // consolidate into existing bins rather than spreading.
    score += open_bins_count as f64 * 0.02 * (post_residual as f64 / bin_capacity as f64);

    // Time-horizon modulation: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Core: waste after placement, normalized, with smooth non-linear growth.
    let mut score = (pr / cap).powf(1.6 + 0.8 * progress);

    // Dead-space penalty: residuals too small for any plausible item (items >= 1).
    // Smoothly ramp penalty as residual shrinks below the mean item footprint.
    let tightness = 1.0 - (pr / cap);
    score += 12.0 * tightness * tightness * tightness;

    // Chain-fit reward: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (1.0 - slack) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Next item cannot use leftover: mild penalty scaled by leftover smallness.
        score += 2.0 * (pr / cap);
    }

    // Last-chance bonus: only fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * progress;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer bins where this item is a tight fit relative to others.
        score += 1.5 * (pr / cap);
    }

    // Mean-residual coupling: placing into a bin below mean residual helps balance.
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev - 1.0 * dev;

    // New-bin candidate: neutral-ish baseline; chosen only when all fits are poor.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.25 * progress) - 0.5 * (next_item_size as f64 / cap);
    }

    // Late-stream consolidation: favor filling existing bins more aggressively.
    score *= 1.0 + 0.4 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit
    } else if pr <= 10 {
        score -= 80.0;
    } else if pr % 10 == 0 {
        score -= 40.0; // decadal class residuals are reusable
    } else if pr < 20 {
        score += 60.0; // dead space risk
    }

    // Modulo-5 class coupling: residuals that are multiples of 5 pair better
    if pr % 5 == 0 {
        score -= 15.0;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 120.0; // chains nicely
            // harmonic match: next item exactly complements
            if next_item_size == pr {
                score -= 200.0;
            }
        } else {
            score += 25.0;
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening unless item is huge or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_frac = item_size as f64 / cap;
        score += 300.0
            - 200.0 * fill_frac
            + 100.0 * (1.0 - progress);
    }

    // Prefer tighter (fuller) bins overall
    score -= (bin_residual as f64 / cap) * 20.0;

    // Small bonus for reducing mean residual dispersion
    score += ((mean_residual - post_residual as f64).abs()) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest plausible item (1..100 => <10)
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward tight fits (small positive post_residual that is still usable)
    if post_residual > 0 {
        score -= 18.0 * (1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0));
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when it beats poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    // Late-stream tightening: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on wasted space.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Aggressive 2-step lookahead: strongly reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 25.0 * next_tight * next_tight;
        } else {
            // next item cannot fit here: penalize leaving a gap smaller than next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    }

    // Penalize divergence from mean residual: prefer bins consistent with fleet state.
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 40.0 * large_item;
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
        if post_residual as f64 >= next_item_size as f64 && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Slight preference to fill older/more crowded bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the item is huge
    // relative to residual (i.e., existing bins are poor fits anyway).
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
        if item_size > bin_capacity / 2 {
            score -= 30.0;
        }
        // Late in the stream, avoid opening bins that will leave dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Lookahead: reward if the next item fits in the post-residual (pairing),
    // penalize if next item is nearly the post-residual (blocking dead space).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            let waste_ratio = post_residual as f64 / next_item_size as f64;
            score += waste_ratio * 10.0;
        }
    }

    // Prefer bins with residual close to the current mean residual (balanced packing),
    // but break symmetry toward using emptier bins when many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;
    if open_bins_count > 8 {
        score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Small item into a mostly-full bin: reward consolidation.
    if item_size <= 20 && bin_residual <= 40 {
        score -= 12.0;
    }

    // Penalize leaving residuals in the "awkward" range (1..10) that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = norm_post * norm_post * (1.0 - norm_post) * (1.0 - norm_post);
    let mut score = pr
        - 30.0 * poly * (1.0 + progress)
        - 12.0 * norm_post * progress * progress
        + 8.0 * norm_post * norm_post * (1.0 - progress);

    // Tight fits are valuable; dead space is penalized smoothly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Last-chance bonus when this is the only fitting bin.
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - norm_post);
    }

    // Prefer bins below mean residual (balancing), smooth coupling.
    score += 0.3 * (mean_residual - pr) * (1.0 - progress);

    // Lookahead: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 10.0 * gap * (1.0 - gap);
    }

    // Mild pressure to reuse open bins as stream advances.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in the low tail is worse
    // (small residuals can rarely host future items), large residuals are reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit: strongly reward
    } else if pr < 10 {
        score += 25.0; // tiny dead space, nearly unusable
    } else if pr < 25 {
        score += 10.0; // awkward class
    } else if pr < 50 {
        score -= 5.0; // decent class
    } else {
        score -= 12.0; // large reusable residual
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        // Reward more when the leftover closely matches the next item (chain fit).
        let slack = (pr - next_item_size) as f64;
        score -= 15.0 - 0.15 * slack;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize mildly.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item fits nothing else (fitting_bins_count includes this new bin).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or when
        // many bins are open (packing pressure already spent).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 - 20.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no alternative: opening is fine
        }
        if next_item_size > 0 && next_item_size <= pr {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Prefer packing into fuller bins: penalize bins far above mean residual.
    score += 0.08 * (bin_residual as f64 - mean_residual).max(0.0);

    // Modulo harmonic: residuals that are multiples of common item classes (10s)
    // tile better; reward them slightly.
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are nearly unusable
    // for items in [1,100] drawn from unknown distributions -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0 * (11.0 - post_residual as f64) / 10.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0; // mildly awkward gap
    }

    // Reward tight fits (waste below 10 is good, exact fit is best).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading items,
    // favor consolidating into already-open bins over new bins.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: only attractive if item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Baseline new-bin cost; grows with how many bins already fit the item.
        score += 15.0 + 6.0 * fitting_bins_count as f64;
        // Slightly more willing to open a new bin early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
        // If next item is large and this item would leave a tiny gap, new bin helps.
        if post_residual > 0 && post_residual < 10 && next_item_size > post_residual as u32 {
            score -= 10.0;
        }
    } else {
        // Existing bin whose leftover accommodates the lookahead item is valuable.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 14.0;
        }
        // Penalize bins far above mean residual (hoarding space).
        if post_residual as f64 > mean_residual + 25.0 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of post_residual with next item is ideal
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post_residual as f64 - nx).abs();
        // Exact match: strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize mismatch scaled by how far off we are
            score += diff * 0.8;
            // If next item cannot fit in post_residual, this is dead space for lookahead
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 1.5;
            }
        }
    }

    // Very small post_residual means bin is nearly closed: good if it was tight
    if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize so it's only chosen when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 70.0 + item_size as f64 * 0.5;
        // If no open bin fits, allow the new bin (mitigate the penalty)
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
    }

    // Slight preference for larger items filling larger residuals early in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post-residual already does this),
    // but amplify the reward quadratically for very tight placements.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize creating small unusable dead space (post residual in 1..=10
    // is nearly worthless unless it's exactly 0).
    if post_residual > 0 && post_residual <= 10 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a perfect chain — strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to how well
            // it fills the remainder.
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 6.0 * fill;
        } else {
            // next item won't fit here: penalize slightly more when the
            // dead space left behind is small (wasted sliver).
            if post_residual < next_item_size && post_residual <= 15 {
                score += 4.0;
            }
        }
    }

    // Last-chance dynamics: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when existing fits are loose
    // (large post_residual) or fragmentation is high. Make the empty-bin
    // baseline moderately high so tight fits in existing bins win, but
    // allow it to win over terrible fits.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin, softened when many bins are open
        // (spreading load can help) and late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 14.0 - 6.0 * progress - (open_bins_count as f64).min(10.0) * 0.4;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    } else {
        // Prefer bins whose residual deviates below the mean (fill the
        // most fragmented bins first), keeping mean residual high overall.
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= 1.5 * dev.min(30.0);
        }
    }

    // Mild global pressure: when many bins are open, encourage closing
    // them out (prefer bins with smaller residual).
    score += 0.05 * (open_bins_count as f64).min(20.0) * (bin_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; late, squeeze hard.
    let progress_coupling = norm_pr * (1.0 + 2.5 * progress * progress);
    score += progress_coupling * cap * 0.15;

    // Penalize large dead space quadratically, scaled by progress.
    score += 4.0 * norm_pr * norm_pr * cap * (0.3 + 0.7 * progress);

    // Reward near-perfect fits with a smooth Gaussian-like bump.
    let fit_quality = 1.0 - norm_item; // 1 - item/cap
    score -= 12.0 * (-(norm_pr * norm_pr) / (0.02 + 0.05 * fit_quality)).exp();

    // Lookahead: reward bins whose post-residual can fit the next item smoothly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 6.0 * (-(slack * slack) / 0.08).exp();
    } else if next_item_size > 0 {
        // Next item can't fit here: mild smooth penalty.
        score += 3.0 * norm_next * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, favor it strongly.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Mean-residual coupling: bins far from the mean residual get a smooth nudge.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (0.5 + progress);

    // New-bin candidate handling: penalize opening a new bin smoothly,
    // more so when good fitting bins exist and progress is late.
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += cap * (0.25 + 0.6 * progress) * (1.0 + openness);
        // But allow new bin if current item is huge and would leave tiny dead space elsewhere.
        score -= 5.0 * norm_item * norm_item * cap;
    }

    // Mild penalty for spreading across many bins early.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes) are preferred.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward bins whose post_residual is divisible into common size classes
    // (harmonic alignment: leftover matches typical item granularities).
    if post_residual > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                harmony += 6.0;
            }
        }
        if post_residual % 5 == 0 {
            harmony += 2.0;
        }
        score -= harmony;
    } else {
        // Perfect fill: strongly reward closing the bin exactly.
        score -= 40.0;
    }

    // Penalize tiny dead space (waste) more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual,
    // penalize if next item would leave this bin useless anyway.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect pair
        } else if next_item_size < post_residual {
            score -= 8.0;
            if post_residual % next_item_size == 0 {
                score -= 6.0; // harmonic chain possible
            }
        } else {
            // next item cannot use this bin's leftover; leftover value drops
            // unless it still fits other common sizes.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current leftovers
    // are badly fragmented (mean residual high but unusable).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post).abs();
        score = cap * 0.75 + open_bins_count as f64 * 2.0 + fragmentation * 0.5 - progress * 10.0;
        // If only a few bins are open and stream is early, new bins are cheap.
        if open_bins_count < 3 {
            score -= 20.0;
        }
        // Strongly discourage new bin when a last-chance fit exists.
        if fitting_bins_count == 1 {
            score += 50.0;
        }
    }

    // Mild preference for tighter bins overall (smaller residual before placement).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 25.0;
    }
    // Medium dead space (11..=25) also risky if next item can't use it.
    else if post_residual > 10 && post_residual < 30 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        // bonus for exact reuse of the leftover space
        if post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover becomes dead space w.r.t. lookahead
        score += (post_residual as f64).min(10.0) * 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of bins when residuals are healthy.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Prefer bins with residual above the mean (keeps a spread of usable bins).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, offset if stream is early / many bins already open
        score += 35.0 - 0.15 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 80.0; // forced new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap_f = bin_capacity as f64;

    // Relative fit: being tighter than the average open bin is rewarded.
    score -= (mean_residual - post_residual as f64).clamp(0.0, 40.0) * 0.25;

    // Aggressive 2-step lookahead against the next item.
    if next_item_size > 0 {
        let pr = post_residual;
        if pr == next_item_size {
            // Perfect 2-item chain: this bin will be exactly filled by the next item.
            score -= 12.0;
        } else if pr >= next_item_size {
            // The next item can also be chained into this bin.
            score -= 0.35 * next_item_size as f64;
            // Extra reward when the leftover after two items is tiny (near-perfect double fit).
            let two_left = (pr - next_item_size) as f64;
            score -= (1.0 - two_left / cap_f) * 2.0;
        } else {
            // Dead space relative to the known next item: penalize the gap.
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.20;
        }
    } else {
        // Last item of the stream: strongly prefer consolidating into open bins.
        if !is_new_bin {
            score -= 5.0;
        }
    }

    // Tight fits of large items are especially valuable (hard to place later).
    if post_residual <= 10 {
        score -= 0.05 * item_size as f64;
    }

    // Last chance: this is the only open bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 6.0 + 6.0 * progress;
    }

    if is_new_bin {
        // Cost of opening a new bin grows with stream progress and bin count,
        // so a new bin is only chosen when all open fits are poor.
        score += 8.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        if open_bins_count == 0 {
            // No alternative exists: must open a bin.
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize small unusable dead space (residuals too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            // Post residual cannot host next item: mild penalty scaled by how close it was.
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.15 * miss;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: later in the stream, consolidation matters more; earlier, keep options open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = 0.5 + progress; // in [0.5, 1.5]
    score *= consolidation;

    // Many open bins with high mean residual: encourage filling existing bins rather than opening new ones.
    if open_bins_count > 2 {
        score -= 0.3 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate (empty bin): make it attractive only when it is genuinely better.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0;
        // Worth opening when existing bins would leave bad dead space or mean residual is low.
        let dead = if post_residual > 0 && post_residual < 15 { 20.0 } else { 0.0 };
        let poor_spread = if mean_residual < item_size as f64 { 15.0 } else { 0.0 };
        score -= dead + poor_spread;
        // Early in the stream, opening bins is cheaper (builds flexibility).
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on leftover space (dead space hurts).
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling of leftover with stream progress:
    // late in the stream, tight fills matter more.
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward snug fits (small post_residual relative to item) with smooth sigmoid-like term.
    let snug = norm_item / (norm_item + norm_pr + 1e-6);
    score -= 25.0 * snug * snug;

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = norm_pr - norm_next;
        score += 15.0 * gap * gap.abs() / (1.0 + norm_pr);
        // small bonus if next item fits exactly-ish
        score -= 8.0 * (-((gap * 4.0) * (gap * 4.0))).exp();
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress) + 10.0;
    }

    // Prefer bins below mean residual early (balance load), smoothly fading later.
    score += (1.0 - progress) * (bin_residual as f64 - mean_residual) * 0.3;

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.05 * (0.5 + progress);

    // New-bin candidate: prefer it only when item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let pressure = norm_item * (1.0 + progress);
        score += 40.0 - 60.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" residue class (multiples of 10 / small residues) are favored.
    let pr = post_residual;
    let class = pr % 10;
    if class == 0 {
        score -= 6.0; // perfectly reusable leftover
    } else if class <= 2 {
        score -= 2.0;
    } else if class >= 7 {
        score += 4.0; // awkward dead space
    }

    // Integer-division threshold: leftover of 0 is perfect.
    if pr == 0 {
        score -= 25.0;
    }

    // Capacity fraction coupling: prefer filling bins past half capacity.
    let frac = bin_residual as f64 / bin_capacity as f64;
    if frac >= 0.5 {
        score -= 5.0 * frac;
    } else {
        score += 3.0 * (0.5 - frac);
    }

    // Lookahead harmony: if the next item fits exactly into post_residual,
    // strongly reward; if it cannot fit, penalize lightly (dead bin).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 18.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) % 10;
            score -= 6.0 - slack as f64;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: only fitting bin -> strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.15;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Tight fit reward: item occupies most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    if tightness > 0.8 {
        score -= 7.0 * tightness;
    }

    // Stream progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit the smallest item (1) is pure waste; gaps
    // below a "usable threshold" are quadratic-penalized dead space.
    let pr = post_residual as f64;
    if pr == 0.0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 60.0;
    } else if pr < 10.0 {
        // Tiny sliver: almost unusable dead space.
        score += (10.0 - pr) * (10.0 - pr) * 1.5;
    } else if pr < 25.0 {
        // Marginal gap: moderately penalized.
        score += (25.0 - pr) * 0.8;
    } else {
        // Large residual stays usable; mild reward for keeping flexibility.
        score -= 5.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 20.0;

    // Lookahead: if the next item fits into post_residual, reward this placement
    // because it preserves a chain of useful packing.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here afterwards: slight penalty for wasted lookahead.
        score += 4.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, be less picky.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin
    // would leave a bad gap or the item fits poorly.
    if bin_residual == bin_capacity {
        // Brand-new bin: baseline cost plus penalty scaled by how poorly
        // the item would use fresh capacity, offset by bin-count pressure relief.
        let waste = (bin_capacity - item_size) as f64;
        score = 30.0 + waste * 0.6 - pressure * 3.0;
        if fitting_bins_count == 1 {
            // Existing bin is the last chance: make new bin unattractive.
            score += 50.0;
        }
    }

    // Mean-residual coupling: if the average residual across open bins is low,
    // bins are nearly full, so prefer bins whose post_residual deviates
    // favorably (keeps at least one flexible bin).
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual) / mean_residual;
        score += dev * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // this is a chained perfect fit -> heavily favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 900.0;
    }
    // Next item fits in the leftover space -> mild reward proportional to closeness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + 0.5 * (post_residual as f64 - next_item_size as f64);
    }
    // Next item does NOT fit in leftover -> penalize dead space creation,
    // worse when leftover is small (unusable).
    else if next_item_size > 0 {
        score += 30.0;
    }

    // Penalize tiny unusable leftovers (below typical small item size).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer bins tighter than the mean residual (best-fit style coupling).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream, be slightly more willing to open bins (score new bins better),
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless it's early or nothing fits well.
        score += 80.0 - 60.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for wasted residual (dead space), quadratic beyond a threshold
    let waste = post_residual as f64;
    if waste > 0.0 && waste < 10.0 {
        score -= 15.0; // near-perfect fit reward
    } else if waste >= 10.0 {
        score += (waste - 10.0) * (waste - 10.0) * 0.05;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 30.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; penalize proportionally to leftover gap
            score += 3.0 + 0.1 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Prefer tighter bins: relative fill tightness
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 10.0;

    // Global state coupling: many open bins with high mean residual -> discourage opening new bins
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let new_bin_penalty = 20.0 + 30.0 * progress + 0.3 * open_bins_count as f64 + 0.2 * mean_residual;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // but allow new bin if item is large and no good fit exists
        if item_size > bin_capacity / 2 && fitting_bins_count <= 2 {
            score -= 25.0;
        }
    }

    // Mild time-horizon shaping: early on be conservative with small residuals
    score += 5.0 * (1.0 - progress) * (waste / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Quadratic penalty on wasted residual, growing with stream progress
    let waste = pr / cap;
    score += 40.0 * waste * waste * (0.5 + progress);

    // Cubic coupling: residual^3 normalized, smooth
    score += 10.0 * (pr / cap).powi(3);

    // Interaction: post residual vs mean residual (avoid outliers vs fleet)
    score -= 0.3 * (pr - mean_residual);
    score += 0.05 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Lookahead: bonus if next item fits snugly in post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 15.0 * snug * snug;
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap) * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.5 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (fine-grained dead-space classes) ---
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Class post_residual into harmonic buckets: perfect fit, tiny, small, medium, large
    if post_residual == 0 {
        // Perfect fit: heavily reward
        score -= 60.0;
    } else if post_residual <= 5 {
        // Near-perfect fit: leftover is essentially dead but small
        score -= 25.0 + 3.0 * post_f;
    } else if post_residual <= 15 {
        // Small leftover: mostly unusable dead space
        score -= 10.0 + post_f;
    } else if post_residual <= 30 {
        // Medium leftover: can host small future items (1..30 range)
        score += 5.0;
    } else {
        // Large leftover: very reusable
        score -= 8.0;
    }

    // --- Harmonic coupling with next item (lookahead k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly in this bin's leftover: strong reward
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 {
                score -= 45.0; // perfect chain
            } else if gap <= 10.0 {
                score -= 30.0; // near-perfect chain
            } else {
                score -= 15.0; // usable chain
            }
        } else {
            // Next item cannot use this leftover: penalize creating stranded space
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.4 * stranded.min(50.0);
        }
    } else {
        // Last item: any nonzero leftover is pure waste
        score += 2.0 * post_f;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only bin that fits; strongly prefer it over opening a new bin
        score -= 35.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists.
        // Base penalty so existing bins usually win:
        score += 40.0;
        // But if the item is large and would leave a bad leftover everywhere,
        // opening fresh is fine: relax penalty for large items.
        if item_size >= 60 {
            score -= 25.0;
        }
        if item_size >= 80 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // --- Modulo arithmetic on residual: harmonic residue classes of capacity ---
    // Items of size dividing capacity (10,20,25,50) leave class-aligned leftovers
    if bin_residual % 10 == 0 && item_size % 10 == 0 {
        score -= 6.0; // aligned boundaries keep future modulo classes clean
    }
    if item_size % 10 != 0 && post_residual % 10 != 0 {
        score += 3.0; // misaligned class creates fragmentation
    }

    // --- Mean residual coupling: avoid dumping into bins far from the mean ---
    let dev = (post_f - mean_residual).abs();
    score += 0.15 * dev;

    // --- Prefer tighter bins overall (best-fit bias) ---
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    // --- Many open bins: encourage closing them out ---
    if open_bins_count > 8 {
        score += 0.3 * (open_bins_count as f64 - 8.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host a future
    // item (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Small-but-usable residuals are mildly penalized relative to large ones
    // to encourage tight packing now, keeping flexibility for later.
    if post_residual >= 10 && post_residual < 30 {
        score += 6.0 * (1.0 - (post_residual as f64 - 10.0) / 20.0);
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading items;
    // with few open bins, mildly favor reusing existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * 0.4 * (0.5 + progress);
    if bin_residual != bin_capacity {
        score -= pressure.min(10.0);
    } else {
        // New-bin candidate: penalize slightly unless open bins are very full.
        score += 5.0 + pressure.min(12.0);
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    }

    // Mean-residual coupling: penalize bins far above the mean residual
    // (they hoard space); reward bins close to the mean for uniform packing.
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 800.0; // chain fit: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // penalty grows with leftover slack beyond the next item's size
            let slack = post_residual as f64 - nxt;
            score -= 300.0 - slack * 2.0;
        } else {
            // next item cannot follow into this bin; penalize proportionally
            score += 150.0 * (nxt - post_residual as f64) / nxt.max(1.0);
        }
    }

    // Prefer tight fits relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize large dead space (unusable residuals) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // tiny unusable slivers are wasted capacity
    }

    // New-bin candidate handling: an empty bin is attractive early or when
    // current fit is poor; mildly discourage hoarding too many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 80.0 * (1.0 - progress) - 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 12.0;

    // Penalize leaving awkward small dead space (hard to reuse).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when plenty of open bins exist with slack.
    if bin_residual == bin_capacity {
        let slack = mean_residual - (item_size as f64);
        if slack > 0.0 {
            score += slack * 0.8;
        }
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += (1.0 - progress) * -8.0 + progress * 6.0;
    }

    // Prefer bins below mean residual (balancing waste across bins).
    let diff = mean_residual - (post_residual as f64);
    score += diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit) but not too small (dead space)
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, larger residuals are more acceptable; later, tightness matters more.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 + progress) * 30.0;
    score += coupling;

    // Smooth polynomial term penalizing mid-range residual waste more strongly late in stream
    let mid_waste = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += mid_waste * 20.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Reward bins that can also host the next item after placement (smooth lookahead)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = ((pr - ni) / cap).min(1.0);
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 3.0;
        }
    }

    // Penalize bins far above/below mean residual (prefer balanced usage), smooth term
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // New-bin candidate handling: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = if pr > 0.0 && pr < 10.0 { 1.0 } else { 0.0 };
        score = 60.0 - 40.0 * desperation - 15.0 * poor_fit * progress
            - 10.0 * (1.0 - progress) * (open_bins_count as f64 / 8.0).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into a
    // "useful" residue class (multiples of 10 / small remainders) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction of leftover

    // Modulo-10 harmonic class of post_residual: class 0 = perfectly harmonic.
    let class = post_residual % 10;
    score += match class {
        0 => -3.0,
        1 | 9 => 1.5,
        2 | 8 => 0.8,
        _ => 0.0,
    };

    // Integer-division threshold: leftover that can still host a small item
    // (>= 10 in classic streams, >= 1 generally) is worth keeping.
    if post_residual >= 10 {
        score -= 2.0 * frac;
    } else if post_residual > 0 {
        score += 4.0; // dead space penalty
    } else {
        score -= 6.0; // perfect closure
    }

    // Coupling with lookahead: if next item fits the post-residual exactly or
    // nearly, strongly reward this bin (chained harmonic placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            let nr_frac = next_item_size as f64 / cap;
            score -= 4.0 * nr_frac;
            // reward when next item's residue class matches post-residual class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // next item won't fit here: mildly penalize hoarding space
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 3.0 * (1.0 - frac);
    }

    // New-bin candidate handling: an empty bin is attractive early in the
    // stream or when open bins are crowded, but penalized when an existing
    // bin can absorb the item with small waste.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (mean_residual / cap).max(0.1);
        score += 6.0 - 4.0 * progress - 1.5 * congestion.min(4.0);
        // opening a bin is bad if the item would leave a harmonic leftover elsewhere
        if item_size % 10 == 0 {
            score += 3.0;
        }
    }

    // Spread-awareness: prefer filling bins below the mean residual (tighter bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild item-size scaling: large items should prefer tight bins.
    score += 0.02 * item_size as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any future item
    // (min item size 1..100 unknown, so treat < ~15 as likely dead) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 20.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is excellent
    } else {
        // larger residuals are more reusable: mild reward relative to baseline
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fits
    // and penalize placements leaving large slack.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.05;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item won't fit here; dead space risk rises with small post_residual
            score += (post_residual as f64).min(40.0) * 0.3;
        }
    }

    // Prefer bins below mean residual when mean residual is high (balance loads).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // New-bin candidate: only attractive when current bin fits are all poor
    // (large post_residual waste). Make fresh bin mildly costly otherwise.
    if bin_residual == bin_capacity {
        score += 8.0 + pressure * 3.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin keeps full flexibility
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    score += 0.35 * (bin_residual as f64 - item_size as f64).abs() * (1.0 / (1.0 + item_size as f64));

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 25.0; // perfect chain
        } else if (post_residual as u32) >= next_item_size {
            // next item fits: penalize proportional leftover after chain
            let after = post_residual as f64 - next_item_size as f64;
            score += 0.4 * after;
            score -= 5.0;
        } else {
            // next item does NOT fit: dead space risk
            score += 0.6 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Compare post_residual against mean residual: avoid creating outlier small residuals.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent existing fits exist, unless residual is very small.
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if best existing fit would waste a lot
        let waste = (bin_residual as f64 - item_size as f64) - post_residual as f64; // = 0 here
        let _ = waste;
        // Make new bin score moderately high; lookahead chain can still win it.
        score += 12.0;
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 10.0; // fresh bin supports the chain
        }
    }

    // Early in stream: be more open to new bins to build structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small to hold typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score += 4.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 3.0 {
            score -= 20.0;
        } else {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use this residual: penalize leaving stranded space
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Empty new-bin candidate: penalize opening new bins unless item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 10.0 * (1.0 - progress);
        if item_size >= 70 {
            score -= 14.0; // large items justify fresh bins
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing
    if mean_residual > 40.0 && open_bins_count > 2 {
        score -= 3.0;
    }
    if bin_residual as f64 > mean_residual + 20.0 {
        score += 5.0; // avoid dumping into unusually empty bins
    }

    // Time horizon: early stream, be picky; late stream, pack greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: quadratic in post_residual, weighted by stream progress
    let mut score = pr * (1.0 + progress * norm_pr * 2.0);

    // Dead-space penalty: small post_residual that can't fit typical items
    let tiny = ((20.0 - pr).max(0.0) / 20.0).powi(2);
    score += 25.0 * tiny * (1.0 - progress * 0.5);

    // Perfect fit reward (smooth gaussian-like bump at post_residual = 0)
    score -= 30.0 * (-norm_pr * norm_pr * 12.0).exp();

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxs = next_item_size as f64;
        if nxs <= pr {
            score -= 15.0 * (1.0 - (nxs / cap)) * (0.5 + 0.5 * progress);
        } else {
            score += 8.0 * ((nxs - pr) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more early on
    if bin_residual == bin_capacity {
        score += 35.0 + 25.0 * progress;
        // but allow it if mean residual across open bins is small (poor fits everywhere)
        score -= (mean_residual / cap).min(1.0) * 20.0;
    }

    // Mild preference for fuller bins via interaction with open bin count
    score -= (fit * fit) * 10.0 / (1.0 + open_bins_count as f64 * 0.05);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 5 bands (0,20,40,60,80)
    let band = post_residual / 20; // 0..5
    // Reward small residuals in fine-grained harmonic way: residual near 0 or exactly fillable classes
    match band {
        0 => score -= 12.0,          // nearly perfect fit
        1 => score -= 6.0,           // small dead space
        2 => score -= 2.0,           // moderate
        3 => { /* neutral */ }
        4 => score += 3.0,           // large residual left
        _ => { /* full/new bin */ }
    }

    // Exact harmonic fill: post_residual divisible by common item sizes (10,20,25,50)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 25 == 0 {
        score -= 2.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves odd remainder -> penalize by leftover oddness
            let rem = post_residual - next_item_size;
            score -= 8.0 - (rem as f64) * 0.15;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but allow it when current residual
    // is large (bad fit) late in the stream
    if bin_residual == bin_capacity {
        score = 40.0 + (post_residual as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 > mean_residual + 15.0 {
            score -= 20.0 * progress; // open new bin when residuals are bloated
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item benefits from fresh bin
        }
    }

    // Mild penalty when bin residual deviates from mean residual (keep homogeneity)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // Late stream: prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if no plausible future item (>=1..=100) fits well;
    // treat tiny gaps (< 10) as near-wasted, and gaps just below common item sizes.
    if post_residual > 0 {
        let mut dead_penalty = 0.0;
        // Gaps below the minimum item size are pure waste.
        if post_residual < 10 {
            dead_penalty += 30.0;
        }
        // Gaps that can only fit very small items are mostly wasted.
        if post_residual < 25 {
            dead_penalty += 15.0;
        }
        // Gaps in the awkward 26..49 band often strand medium items.
        if post_residual >= 26 && post_residual <= 49 {
            dead_penalty += 8.0;
        }
        // Perfect fit reward: zero waste is ideal.
        if post_residual == 0 {
            dead_penalty -= 50.0;
        }
        score += dead_penalty;
    }

    // Reward tight fits: the smaller post_residual relative to item_size, the better.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when open_bins_count is high.
    let open_pressure = (open_bins_count as f64).sqrt() * 2.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin
    // would leave a large dead gap or the bin is genuinely too full.
    if bin_residual == bin_capacity {
        // Prefer a new bin only if the alternative fit is terrible;
        // base handicap keeps it slightly unattractive.
        score += 12.0;
        // Lookahead: if the next item is large, a fresh bin is more attractive.
        if next_item_size > 0 {
            let lookahead_bonus = (next_item_size as f64 / 100.0) * 15.0;
            score -= lookahead_bonus;
        }
    } else if next_item_size > 0 && (next_item_size as u64) > (post_residual as u64) {
        // If next item won't fit this bin's post-residual, slight penalty
        // unless post_residual is dead space anyway.
        if post_residual >= 10 {
            score += 5.0;
        }
    }

    // Mean-residual coupling: if open bins are generally full (low mean residual),
    // prefer conserving space in this bin; if mean residual is high, spreading is fine.
    let mean_coupling = (mean_residual / bin_capacity as f64) * 6.0;
    score += mean_coupling * (post_residual as f64 / bin_capacity as f64);

    // Stream progression: late in the stream, minimize bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post residual with a tight margin (good lookahead).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot follow into this bin: penalize proportionally to waste.
        score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr);
    } else {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating very small dead space (unusable slivers).
    if pr > 0 && pr < 10.0 {
        score += 15.0;
    }

    // Mildly discourage opening new bins late in the stream when alternatives exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 15.0 * progress;
    }

    // Slight preference for filling fuller bins.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual is good, but dead space
    // that can't hold the next item is worse than one that can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin remains useful for the lookahead item: reward.
            let slack_after_next = post_residual - next_item_size;
            score -= 6.0 * (slack_after_next as f64 / bin_capacity as f64).tanh();
        } else {
            // Post-residual becomes dead space w.r.t. next item: penalize.
            let dead = post_residual as f64;
            score += 4.0 + 10.0 * (dead / bin_capacity as f64);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    } else if post_residual < 10 {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.05 * post_residual as f64;
    }

    // Compare against mean residual: bins below the mean residual are "tight"
    // and should be filled first; bins above the mean are roomy.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.6 * dev;

    // Time horizon: early in the stream, be more liberal about opening bins
    // (more future items to benefit from good packing); late in the stream,
    // prefer filling existing bins to avoid waste.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 20.0 * (0.4 + 0.6 * t);
    if bin_residual == bin_capacity {
        // New-bin candidate: score = residual + penalty structure.
        score += new_bin_penalty;
        // Opening a new bin is attractive when the item is large relative to
        // what open bins can absorb, or when open bins are crowded.
        if open_bins_count > 0 {
            score -= 6.0 * (item_size as f64 / bin_capacity as f64);
        } else {
            score -= 30.0; // must open first bin
        }
    } else {
        // Existing bin: mild reward scaled by how full the fleet is.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);
    }

    // Slight preference to keep residual granularity aligned with small items
    // (common sizes), reducing fragmentation.
    let frag = (post_residual as f64 / 10.0).fract();
    score += 1.5 * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap; // normalized post residual in [0,1]

    // Smooth polynomial base: penalize leftover space, with stronger penalty
    // for mid-range waste (dead space that is hard to reuse) than for
    // near-zero or near-full residuals.
    let x = norm_post;
    let mut score = 12.0 * x - 8.0 * x * x + 16.0 * x * x * x;

    // Tight fit reward: smooth coupling of item size with post residual.
    // Large items leaving small residuals get extra reward.
    let tightness = 1.0 - norm_post;
    let size_factor = item / cap;
    score -= 6.0 * tightness * tightness * (0.5 + size_factor);

    // Dead-space hazard: residuals too small for typical future items.
    // Smooth sigmoid-like gate around half capacity.
    let gate = 1.0 / (1.0 + (norm_post - 0.45) * 14.0).exp();
    score += 5.0 * gate * (1.0 - progress) * norm_post;

    // Stream-progress coupling: late in the stream, waste is costlier.
    let late = progress * progress;
    score += 8.0 * late * norm_post;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post residual, reward heavily;
    // smooth reward decaying with mismatch.
    if next_item_size > 0 {
        let mismatch = (post_residual as f64 - next_item_size as f64).abs() / cap;
        score -= 7.0 * (1.0 - 2.0 * mismatch).max(0.0) * (1.0 - mismatch);
    }

    // Crowd-out penalty: many open bins with high mean residual suggests
    // fragmentation; discourage adding to it mildly, encourage consolidation.
    let frag = mean_residual / cap - norm_post;
    score += 2.0 * frag.max(0.0);

    // New-bin candidate handling: an empty bin has norm_post == 1.0.
    // Its polynomial base is high; only open a new bin when no existing bin
    // offers a reasonable fit (item large relative to best residual is
    // captured by the other bins' scores already). Add a mild adaptive
    // discount so a fresh bin beats very poor fits late in the stream.
    if bin_residual == bin_capacity {
        score -= 4.0 + 3.0 * late + size_factor * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into capacity-fraction bands (dead-space classes).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class: f64 = if post_residual == 0 {
        -30.0 // perfect closure: strongly reward
    } else if post_residual < eighth {
        -8.0 // tiny dead space, nearly full bin
    } else if post_residual < quarter {
        0.0 // small-but-usable
    } else if post_residual < quarter * 2 {
        6.0 // half-class leftover: mediocre
    } else if post_residual < quarter * 3 {
        14.0 // large leftover: wasteful unless big item
    } else {
        22.0 // nearly-empty-class leftover: bad placement
    };
    score += class;

    // Modulo arithmetic on post_residual: leftovers that are multiples of
    // common item-size harmonics (e.g. multiples of 10/20/25) are more
    // likely to be exactly filled by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 2.5; }
        if post_residual % 50 == 0 { score -= 3.0; }
        // Odd, prime-hostile residues are poor targets.
        if post_residual % 2 == 1 { score += 2.0; }
        if post_residual % 5 != 0 && post_residual % 7 == 0 { score += 1.5; }
    }

    // Lookahead harmony: does the next item fit harmonically into the residue?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // exact future match: excellent
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap < eighth {
                score -= 10.0; // next item nearly closes this bin
            } else if gap % 10 == 0 {
                score -= 5.0; // harmonic gap remains
            } else {
                score -= 2.0;
            }
        } else {
            // Next item cannot use this residue; penalize by blocking degree.
            let block = (next_item_size - post_residual) as f64;
            score += 0.15 * block;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Mild competition bonus proportional to scarcity.
        score -= 1.5 / fitting_bins_count as f64;
    }

    // New-bin candidate handling: neutral-ish, but open a fresh bin when
    // existing fits would create large dead space.
    if bin_residual == bin_capacity {
        // Fresh bin: score equals its post_residual minus a modest opening
        // cost; attractive when all open bins score badly.
        score = post_residual as f64 + 6.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Progress pressure: late in the stream, tighten bins more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (mean_residual / cap);

    // Prefer bins below mean residual (tighter bins) slightly.
    score += 0.5 * ((bin_residual as f64) - mean_residual) / cap;

    // Fragmentation guard: avoid leaving residues in the awkward 1..eighth
    // band that nothing in [1,100] harmonically fills well.
    if post_residual > 0 && post_residual < eighth && post_residual % 10 != 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it's too small for the smallest plausible item (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Medium dead space (11..25) is risky too: quadratic penalty.
    if post_residual >= 10 && post_residual < 25 {
        let g = post_residual as f64;
        score += 0.35 * (25.0 - g) * (25.0 - g) * 0.25;
    }

    // Reward tight fits (small post_residual is good, so subtract for near-perfect fits).
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Exact match with lookahead: strongly encourage saving room for next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If next item fits exactly in the post residual, mild bonus.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 10.0;
    }
    // If the next item would NOT fit in the post residual but fits nowhere else,
    // this placement strands it: penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: penalize creating more open bins; encourage consolidation
    // when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // Prefer bins below mean residual (packing into emptier bins spreads load evenly,
    // but for dead-space avoidance prefer bins whose residual is close to item_size).
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * residual_gap;

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    // Base penalty so a new bin is chosen only if open bins have bad residuals.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening a new bin is more acceptable (can't consolidate forever).
        score -= 40.0 * progress;
        // If many bins are open, prefer consolidating instead of new bin.
        score += open_bins_count as f64 * 2.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: next item exactly fills this bin afterwards
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: partial reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.3;
        } else {
            // Next item will NOT fit: dead space penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + gap * 0.5;
        }
    } else {
        // Last item: minimize leftover directly
        score += post_residual as f64 * 0.2;
    }

    // --- Tight fit reward relative to mean residual ---
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    if tightness < 0.10 {
        score -= 30.0; // very tight fit, prefer consuming small residual
    } else {
        score += (post_residual as f64 - mean_r) * 0.15; // prefer bins below-average residual
    }

    // --- Last-chance bonus: only bin that fits, avoid opening new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate: only attractive when no open bin fits well ---
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual < next_item_size;
        if poor_fit && post_residual < 10 {
            score -= 15.0; // open a fresh bin when this would strand tiny residual
        } else {
            score += 60.0; // discourage wasteful new bins by default
        }
    }

    // --- Mild stream-phase modulation ---
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty for wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space below smallest plausible item (1..=10) is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't chain here; penalize proportionally to how much space is stranded.
        score += 8.0 + 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits, else a new bin opens.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer bins that would be "closed out" well.
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when open bins
    // are crowded (low mean residual) or the item is large.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = 0.5 * crowded + 0.004 * open_bins_count as f64;
        // Penalize new bin when existing bins are roomy; reward when scarce.
        score += 70.0 - 60.0 * pressure - 20.0 * (item_size as f64 / bin_capacity as f64) + 10.0 * progress;
    }

    // Prefer filling bins that are already more depleted than average.
    score -= (bin_residual as f64 - mean_residual) * 0.25;

    // Mild time-horizon modulation: early on, be conservative about stranding space;
    // late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (larger leftover = better fit)
    let mut score = pr;

    // Smooth polynomial coupling of normalized post-residual with stream progress.
    // Early on: tolerate medium leftovers; late: strongly prefer tight fits.
    let phase = progress * std::f64::consts::PI;
    let w_early = (1.0 - progress) * (1.0 - progress);
    let w_late = progress * progress;
    score += 20.0 * w_early * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score -= 30.0 * w_late * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space relative to next item's need (smooth quadratic mismatch).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        score += 15.0 * gap * gap * cap;
        // Reward exact-ish preparation for next item, weighted by progress
        score -= 10.0 * progress * (-gap * gap);
    }

    // Last-chance bonus: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * 0.5);
    }

    // Slight penalty when bin residual far from mean residual (keeps bin pool balanced).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: penalize mildly unless current residuals are all tight.
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (divisible by common item sizes) are rewarded.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit is always best
    } else if pr % 10 == 0 {
        -25.0
    } else if pr % 5 == 0 {
        -12.0
    } else if pr >= 10 {
        -6.0
    } else {
        15.0 // dead space < 10 is nearly unusable
    };
    score += harmonic_bonus;

    // Integer-division threshold: classify leftover into capacity fractions.
    let frac = pr as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 20.0; // bin still half-full: good candidate
    } else if frac > 0.25 {
        score -= 5.0;
    } else {
        score += 8.0 * (0.25 - frac); // penalize near-empty leftovers
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly prefer this bin (chained harmonic match).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 10.0 * (1.0 - (pr - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bin: if only this bin fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 0.2 * post_residual as f64;
    }

    // New-bin candidate: prefer it only when all open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 30.0 - 40.0 * crowding;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-phase adaptation: early on, keep bins flexible.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - phase) * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits (high fill ratio).
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.5;
    }

    // Lookahead: if the next item can use this bin's post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Slight preference for bins below mean residual (balancing).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward post_residual that can host next item exactly or well
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 30.0 - (gap as f64).min(30.0);
        if gap == 0 {
            score -= 200.0; // chains a perfect follow-up
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space below next item size: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize large post_residual creating unusable slivers (< min plausible size 10)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Early in stream: encourage keeping some large-residual bins open for future big items
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 50 {
        score += (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward exact/near-exact fills.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < item_size {
        // residual too small for typical items -> dead space risk
        score += 15.0;
    }

    // Lookahead: if next item fits in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // next item won't fit here; penalize more if residual is small (wasted)
            score += 5.0 + tightness * 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when many open bins could fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, but less late in the stream or when
        // open bins are all nearly full (high mean residual usage).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let mut new_bin_score = 60.0;
        new_bin_score -= 30.0 * progress;          // late stream: consolidation matters less
        new_bin_score -= 40.0 * avg_fill;          // bins nearly full -> new bin is fine
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;                // nothing fits: must open
        }
        // Avoid hoarding bins early when open bins are still roomy.
        if open_bins_count > 3 && avg_fill < 0.4 {
            new_bin_score += 25.0;
        }
        score = new_bin_score;
    } else {
        // Mildly prefer using emptier bins to balance residuals,
        // but prefer fuller bins when stream is nearly done.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bin_fill = (bin_residual as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        score += 10.0 * bin_fill * (1.0 - progress); // early: spread load
        score -= 8.0 * bin_fill * progress;          // late: fill fullest bins
    }

    // Global pressure: many open bins -> discourage spreading, encourage filling.
    if open_bins_count > 5 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more, so reward low post_residual extra.
    let progress_coupling = progress * (1.0 - x) * (1.0 - x);
    score -= 18.0 * progress_coupling;

    // Non-linear penalty for residual that is awkwardly small but nonzero (dead space)
    // penalize via a smooth bump around small x: x*(1-x) shaped, scaled by item size.
    let dead = x * (1.0 - x);
    score += 10.0 * dead * (item_size as f64 / cap);

    // Reward using bins when few fitting bins exist (last chance)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Reward bins whose residual deviates favorably from the mean residual
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Lookahead: if the next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - progress);
    }

    // Mild penalty for opening a new bin when many bins are open late in stream
    let is_new = (bin_residual as u32 == bin_capacity) && post_residual == bin_residual - item_size;
    if is_new {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more likely to be closed out usefully.
    let residue_class = post_residual % 10;
    let class_bonus = match residue_class {
        0 => 6.0,               // perfectly divisible leftover
        1 | 9 => 2.0,
        2 | 8 => 1.0,
        3 | 7 => -1.5,          // awkward residues: penalize slightly
        _ => -3.0,              // 4,5,6: mid dead space
    };
    score += class_bonus;

    // Integer-division threshold: how many size-10 units remain
    let units = post_residual / 10;
    score -= (units as f64) * 0.8;

    // Tight fits are golden: post_residual very small relative to item
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 7.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 4.0;
        } else if next_item_size - post_residual <= 10 {
            score += 6.0; // next item just misses: this leftover may be dead
        }
        // harmonic class match between next item and leftover
        if next_item_size % 10 == post_residual % 10 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when this bin's fit is bad.
    if bin_residual == bin_capacity {
        // Opening fresh is penalized mildly, but more when many bins are open
        // and mean residual is high (existing space should be used).
        score = 55.0 + 2.5 * (open_bins_count as f64).ln().max(0.0)
              + 0.4 * mean_residual.max(0.0);
        if post_residual == bin_capacity && item_size <= bin_capacity / 2 {
            // small item into a fresh bin: wasteful unless nothing fits elsewhere
            score += 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits: must open a bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.15;

    // Prefer bins below mean residual (concentrate fill in emptier bins).
    score += ((post_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are pure waste — penalize them quadratically.
    let dead_threshold: u32 = 10;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
        score += 25.0; // flat penalty for creating unusable sliver
    }

    // Penalize near-full-but-not-full residuals (awkward gaps 11..=20)
    if post_residual >= dead_threshold && post_residual <= 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // creates a gap the next item cannot use
        score += 8.0;
    }

    // Open-bin pressure: when many bins are open, tighten tolerance for waste
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.5;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 40.0; // perfect chain: next item exactly fills this bin
        } else if (post_residual as i64 - next_item_size as i64) > 0 {
            // next item still fits after this placement: mild bonus scaled by tightness
            score -= 8.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leaving dead space
            score += 0.15 * diff as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: only one bin fits the item, keep it alive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin unless it enables a perfect next-step fill.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let perfect_chain = next_item_size > 0
            && item_size + next_item_size == bin_capacity;
        if perfect_chain {
            score -= 60.0; // open bin for an exact 2-item fill
        } else {
            score += 25.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Late-stream tightening: waste matters more as stream nears completion.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress) - 30.0 * norm_post * norm_post * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses (smooth quadratic term)
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth cubic coupling)
    let dead = norm_post - (mean_residual / cap).clamp(0.0, 1.0);
    score += 15.0 * dead * dead * dead.abs();

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: favor bins whose post-residual can host the next item (smooth exponential decay)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0);
        score -= 18.0 * (-gap / 20.0) * (0.5 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress;

    // Slight bias toward opening a new bin early when residual is large
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let cls = post_residual % (bin_capacity / 4); // harmonic sub-class (0..25)
    let cls_f = cls as f64;

    // Reward residuals that are "harmonic" multiples (clean splits of capacity)
    let harmonic_bonus = if post_residual == 0 {
        -30.0 // perfect fit
    } else if post_residual % (bin_capacity / 2) == 0 {
        -18.0
    } else if post_residual % (bin_capacity / 4) == 0 {
        -10.0
    } else if post_residual % 5 == 0 {
        -4.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize dead space in awkward classes (small, unusable leftovers)
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 8.0 + (bin_capacity as f64 / pr) * 2.0;
    }

    // Integer-division threshold: how many items of average size still fit
    let avg_item = 50.0f64.min(cap / 2.0);
    let fits_count = (pr / avg_item).floor();
    score -= fits_count * 2.5;

    // Lookahead coupling: does post_residual admit the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + 12.0 * (1.0 - slack / cap); // tight follow-up fit is great
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            let miss = (next_item_size - post_residual) as f64;
            score += 3.0 + 6.0 * (miss / cap);
        }
    } else {
        // last item: just minimize leftover
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit_everywhere = if fitting_bins_count >= 1 && post_residual as f64 > cap - item_size as f64 - 5.0 { 0.0 } else { 0.0 };
        // base penalty so new bins open only under pressure
        score += 20.0 - 25.0 * pressure;
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        let _ = poor_fit_everywhere;
    }

    // Mean-residual coupling: if open bins are mostly full, opening fresh is cheaper
    let mean_gap = (mean_residual - pr).abs();
    score += 0.05 * mean_gap;

    // Modulo interplay between item class and post class (harmonic affinity)
    let item_cls = item_size % (bin_capacity / 4);
    if item_cls == cls {
        score -= 3.0;
    }

    // Mild preference for tighter bins when many bins are open
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space that cannot fit even the smallest plausible item is terrible.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 30 {
            score += 8.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 100.0;
    }

    // If the lookahead item fits exactly into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage proliferating bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure,
        // but relax if the current item is large relative to capacity.
        score += pressure * 2.0 - (item_size as f64 / bin_capacity as f64) * 30.0;
    } else {
        // Existing bins get a mild discount so they are preferred over new bins.
        score -= 5.0;
    }

    // Slight preference for bins with residuals below the mean (tighter bins first).
    if bin_residual != bin_capacity {
        score += 0.3 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but reward exact/very tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item: chain two items into one bin.
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // Next item could still fit here afterwards: reward proportional closeness.
            score -= (30.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
        } else {
            // Post residual too small for next item: penalize dead space more when
            // the wasted gap is just below the next item (near-miss frustration).
            let near_miss = (next_item_size as f64 - post_residual as f64) <= 15.0;
            if near_miss {
                score += 25.0;
            }
        }
    } else {
        // Last item: any fit is fine, prefer smallest post residual (already base).
        score -= 20.0;
    }

    // Compare against mean residual: bins below mean residual are already tight,
    // prefer them; bins far above mean are loose and waste capacity.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = fitting_bins_count == 0
            || (post_residual as f64 > mean_residual + 20.0 && next_item_size > post_residual && post_residual > 0);
        if poor_fit_everywhere {
            // Fresh bin keeps full flexibility for the lookahead item.
            score -= 40.0 + next_item_size as f64 * 0.2;
        } else {
            // Discourage wasting a fresh bin when existing bins fit acceptably.
            score += 150.0;
        }
    }

    // Early in the stream: slightly favor opening bins to build diversity of residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid tiny useless slivers.
    if post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.10 {
            score += 6.0; // dead-space penalty for unusable slivers
        } else {
            score -= 4.0 * (1.0 - frac); // reward proportionally tight packing
        }
    } else {
        score -= 12.0; // perfect fill: strongly favored
    }

    // Lookahead: if next item fits into post_residual, this bin gains synergy.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }
    // If next item would only fit here and not elsewhere after placement, mild penalty
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual
        && post_residual - next_item_size < 10 {
        score += 3.0; // avoid leaving room that only next item barely uses, creating sliver
    }

    // Last-chance bonus: only one bin can fit the item -> use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + 10.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        // If many bins already fit the item, opening a new one is clearly worse.
        if fitting_bins_count > 0 {
            score += 20.0 * fitting_bins_count as f64;
        }
        // If only this (new) bin can take the item, opening is forced/necessary.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Lookahead synergy: big next item pairs well with a fresh bin.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Global state: prefer using bins whose residual is below the mean (consolidate fullness).
    if bin_residual < mean_residual {
        score -= 2.0;
    } else {
        score += 1.5;
    }

    // Late in the stream, be more conservative: avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth stream-progress coupling: late in the stream, dead space matters more.
    let prog_coupling = 0.5 * progress * (1.0 - norm_post);
    score -= prog_coupling * 20.0;

    // Penalize waste relative to mean residual of open bins (smooth quadratic).
    let waste_gap = post - mean_residual;
    score += 0.15 * waste_gap * waste_gap / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving space compatible with the next item (smooth kernel).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (post - ns) / cap;
        let kernel = (-diff * diff * 40.0).exp();
        score -= 12.0 * kernel;
    }

    // Mild penalty for many open bins to discourage excessive fragmentation.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the resulting dead space (modulo arithmetic) ---
    // Residuals divisible by common item granularities are "reusable" classes.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit: ideal
    } else if pr % 10 == 0 {
        -25.0 // lands on a decade class -> highly reusable
    } else if pr % 5 == 0 {
        -12.0 // half-decade class
    } else if pr >= 10 {
        -4.0 // still usable by smallest items
    } else {
        18.0 // sub-10 dead space: essentially unusable
    };
    score += class_bonus;

    // --- Integer-division thresholds on post_residual ---
    let pr_class = pr / 20; // coarse harmonic band 0..5
    score -= pr_class as f64 * 6.0;

    // --- Lookahead coupling: does the next item fit the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item slots perfectly into leftover: strong reward,
            // scaled by how tight the lookahead fit is
            let tightness = 1.0 - (pr as f64 - next_item_size as f64) / cap;
            score -= 20.0 + 15.0 * tightness;
            // harmonic bonus if (pr - next) also lands in a good class
            if (pr - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize wasted potential
            score += 10.0;
            // extra penalty if the leftover is in an odd (non-reusable) class
            if pr % 10 != 0 && pr < 10 {
                score += 8.0;
            }
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, avoid opening new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are fragmented
        // and the current item is large (harmonic fraction of capacity).
        let frac = item_size as f64 / cap;
        let fragmentation = (mean_residual - post_residual as f64).max(0.0) / cap;
        // large items (>= half capacity) pair well with a fresh bin
        if frac >= 0.5 {
            score -= 10.0 * frac;
        }
        // if open bins are already quite full on average, fresh bin is fine
        if mean_residual < 0.2 * cap {
            score -= 12.0;
        }
        // penalize new-bin spam early/late via stream progression
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * (1.0 - progress);
        // discourage new bin when many bins could fit
        score += 5.0 * (fitting_bins_count as f64).min(5.0);
        let _ = fragmentation;
    }

    // --- Mean-residual coupling: prefer bins near the mean (balanced packing) ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // --- Slight preference for fuller bins as stream progresses ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / cap);

    // --- Tie-break by bin count pressure: fewer open bins is better ---
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: u32 = 10; // items are >= 1..100; gaps below this are rarely usable
    if post_residual > 0 && post_residual < dead_zone {
        score += (dead_zone - post_residual) as f64 * 6.0; // up to ~54 penalty
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to bin capacity (waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 40.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer packing into existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // New-bin candidate: make it less attractive unless current bin fits are bad.
    if bin_residual == bin_capacity {
        // Neutralize base score (post_residual == capacity) and add a fixed premium.
        score = bin_capacity as f64 + 15.0;
        // But if no open bin fits tightly, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream with few open bins, prefer consolidation instead.
        if progress > 0.7 && open_bins_count <= 3 {
            score += 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < dead_zone {
            score -= 20.0 - gap as f64 * 2.0;
        }
    }

    // Slight preference for bins below mean residual (denser bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (minimal dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fits the
    // post-residual, this placement is ideal (chain of two perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits in the leftover space: good chaining.
            let chain_waste = post_residual - next_item_size;
            score -= 100.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to how
            // far off the post-residual is from the next item size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize creating small unusable fragments relative to the
    // smallest possible item (assume ~1 given unknown distribution),
    // scaled by how full the bin already is.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += 0.3 * post_residual as f64 * (1.0 - fill_ratio);

    // Last-chance bonus: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when
    // the item is large and open bins have scattered residuals.
    if bin_residual == bin_capacity {
        // Baseline competitiveness for a fresh bin.
        score = 60.0;
        if fitting_bins_count == 0 {
            // No open bin fits: new bin is mandatory.
            score -= 2000.0;
        } else if item_size >= 50 {
            // Large item: a fresh bin keeps large-item pairing options.
            score -= 40.0;
        }
        // If open bins are already tight on average, avoid opening new.
        if mean_residual < 20.0 {
            score += 80.0;
        }
    }

    // Mild preference for bins tighter than the mean (compact packing).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Late-stream consolidation: as the stream progresses, prefer
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement
    let fill = item_size as f64 / cap;
    score -= 0.6 * fill * (post_residual as f64 / cap);

    // Penalize small dead space that becomes unusable (post_residual below min item size)
    if post_residual < 10 {
        score += 8.0;
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly, but relax when it fits poorly elsewhere
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 6.0 + 6.0 * (1.0 - progress);
        // If next item could combine with a full fresh residual, opening is attractive
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= cap {
            new_bin_penalty -= 4.0;
        }
        // If this bin would leave large awkward space elsewhere, opening is fine
        if post_residual > 0 && (post_residual as f64) < 0.25 * cap {
            new_bin_penalty -= 2.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead: penalize if the next item no longer fits in post residual
    if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 2.0;
    } else if next_item_size > 0 {
        // Reward chains where next item fits snugly after this placement
        let chain = post_residual as f64 - next_item_size as f64;
        if chain < 10.0 {
            score -= 3.0;
        }
    }

    // Global pressure: many open bins with low mean residual -> prefer consolidation
    if open_bins_count > 2 && mean_residual < 30.0 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    // Slight time decay: later in stream, waste matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; later, penalize waste more.
    let progress_weight = 0.5 + 3.0 * progress * progress;
    score += progress_weight * r * r * (bin_capacity as f64);

    // Reward near-perfect fits with a smooth quadratic bonus around r = 0.
    score -= 12.0 * (1.0 - r) * (1.0 - r);

    // Last-chance bin: smooth exponential urgency reward scaled by progress.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Dead-space penalty if post_residual is too small for the smallest plausible item,
    // expressed smoothly via sigmoid-like term instead of a hard cutoff.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += 6.0 * dead * (0.5 + progress);

    // Lookahead: reward bins whose post_residual can still host the next item,
    // with smooth coupling to how much slack remains.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 5.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            score += 4.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Mild preference for fuller bins relative to the mean residual across open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight penalty for spreading across many bins early in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: dead space thresholds.
    // Residuals <= 10 are "perfect" (unusable by min item) -> heavily reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 150.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 20.0;
    } else if post_residual <= 33 {
        score -= 5.0;
    } else {
        // large leftover: penalize mildly, scaled by fraction of capacity
        score += (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Modulo-10 harmonic class: exact decimal fits are best.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // reward when the gap left after next item would be small
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 60.0;
            } else {
                score -= 30.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // next item cannot use this residual: penalize proportional to wasted opportunity
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer tighter bins when many bins are open (keep spread contained).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0 * (open_bins_count.min(20) as f64 / 20.0);

    // Early in stream: be more willing to fill existing bins (avoid bin proliferation).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score -= 10.0;
    }

    // Compare against mean residual: bins below mean residual are more "committed".
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when residual is full capacity AND
    // current item is large relative to capacity (better to start fresh than
    // fragment an open bin). Otherwise penalize new bins.
    if bin_residual == bin_capacity {
        if item_size > 60 && fitting_bins_count <= 1 {
            score -= 30.0;
        } else {
            score += 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be useful
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Coupling with lookahead: if next item fits into post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        // extra reward if next item nearly fills the remaining gap
        let gap_after_next = post_residual as f64 - next_item_size as f64;
        if gap_after_next < dead_threshold {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // post residual becomes dead space for the known next item
        score += (post_residual as f64) * 0.4;
    }

    // Open bins pressure: discourage spreading across many bins unless fit is tight
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += pressure * 10.0;

    // Last-chance bin: strongly favor using the only bin that can fit
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins already tighter than average (best-fit flavor)
    score += (bin_residual as f64 - mean_residual).max(-30.0).min(30.0) * 0.3;

    // Mild stream progression: later in stream, be greedier about filling bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chaining
        } else if post_residual >= next_item_size {
            // next item fits; reward closeness of the chain fit
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving residual that strands the lookahead
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste.min(40.0);
        }
    } else {
        // last item: just minimize residual
        score += 0.0;
    }

    // Penalize dead space relative to mean residual across open bins
    if (post_residual as f64) > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless stream is early or item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let mut open_penalty = 25.0 * (1.0 - progress);
        if large_item { open_penalty -= 20.0; }
        if next_item_size > 0 && next_item_size >= item_size { open_penalty -= 5.0; }
        score += open_penalty.max(0.0);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect or near-perfect fit gets strong reward
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fills the bin completely after this one
        if post_residual == next_item_size {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size <= item_size {
        // Next item won't fit here; mild penalty if we strand a large residual
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // the item fits poorly everywhere else
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        // Penalize new bins mildly by default
        score += 5.0;
        // But if item is large, a fresh bin wastes little; encourage it
        if item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
        // If many open bins exist with high mean residual, prefer reusing them
        if mean_residual as u32 >= item_size * 2 && open_bins_count > 0 {
            score += 8.0;
        }
        // Late in the stream, avoid leaving many half-empty bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && waste > 40 {
            score += 10.0;
        }
    }

    // Prefer filling bins with smaller residuals (compact packing)
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += (1.0 - residual_frac) * 6.0;

    // Coupling with global mean residual: bins below mean residual are
    // "tighter" and should be prioritized to consolidate fullness
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Time-dependent pressure: as stream progresses, discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, shaped by a smooth polynomial in progress
    let mut score = pr * (0.5 + 0.5 * progress * progress);

    // Non-linear coupling: penalize small-but-nonzero residuals quadratically (dead space)
    let dead = if pr > 0.0 { 1.0 / (pr_norm + 0.05) } else { 0.0 };
    score += 0.8 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits: subtract when post_residual is small relative to capacity
    score -= 12.0 * (1.0 - pr_norm).powi(3);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: penalize leaving residual that can't help the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.15 * gap;
        if nx <= pr {
            score -= 6.0 * (1.0 - nx / cap);
        }
    }

    // Interaction with mean residual: prefer bins near the mean (keeps balance)
    score += 0.3 * (mean_residual - pr).abs();

    // Mild penalty for proliferating bins late in stream
    score += 0.5 * (open_bins_count as f64) * progress;

    // New-bin candidate: make it attractive only when it enables good future packing
    if bin_residual == bin_capacity {
        score = 60.0 - 30.0 * progress + 0.4 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by small
    // "harmonic" denominators (10/20/25/50) are reusable by typical items.
    let pr = post_residual;
    let harmonic = if pr == 0 { 0.0 }
        else if pr % 10 == 0 { -3.0 }
        else if pr % 25 == 0 { -2.0 }
        else if pr % 20 == 0 { -1.5 }
        else if pr % 5 == 0 { -0.8 }
        else { 1.5 }; // odd residue -> dead space penalty

    score += harmonic;

    // Perfect fit is best.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead: does the leftover fit the next item well?
    if next_item_size > 0 && pr > 0 {
        if next_item_size <= pr {
            score -= 6.0;
            // Harmonic class of the double leftover
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 4.0; }
            else if pr2 % 5 == 0 { score -= 2.0; }
            else { score += 1.0; }
        } else {
            // leftover too small for next item: penalize small dead zones
            if pr < 10 { score += 8.0; }
        }
    }

    // Integer-division threshold classes on post_residual.
    let cls = pr / 25; // 0..4 harmonic quarter classes
    score += match cls {
        0 => 5.0,   // tiny leftover < 25: mostly dead space
        1 => 0.0,
        2 => -1.0,
        3 => -2.0,
        _ => -3.0,  // roomy bin
    };

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer fuller bins when many bins are open (tight packing).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill;

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * fill;

    // Slight bias against opening new bins when mean residual is large.
    score += 0.05 * mean_residual * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any
    // plausible item (min size 1..100 unknown, assume >= 10-ish region)
    // are "dead space". Penalize gaps in the unusable band heavily.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward when post_residual can still host the lookahead item
    // (chaining placements into the same bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // residual too small for next item: dead-ish space
        score += (post_residual as f64) * 0.5;
    }

    // Open-bin pressure: discourage spreading when many bins are open,
    // encourage consolidation; but last-chance bins are precious.
    score += open_bins_count as f64 * 0.6;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that fits: strongly prefer using it
        // over opening a new bin unless the fit is terrible.
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // moderately attractive only when no good fit exists. Base penalty so
    // it is chosen only when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheap; later, avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If next item is large, a fresh bin is more useful.
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    // Mild alignment with mean residual: bins below mean residual are
    // already tight; prefer filling them further.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item leaves a small residual again.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 25.0 - gap as f64;
        }
    }
    // Penalize dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        if waste < 10.0 {
            score += 15.0; // tiny unusable sliver
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: only one bin fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild encouragement to use fuller bins early (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fit_frac * fit_frac;

    // Penalize dead space that no plausible future item can use:
    // residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 {
            // next item won't fit here; mild penalty proportional to waste
            score += 2.0 * (next_item_size as f64 - post_residual as f64).min(10.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer filling bins that are already relatively full (low residual),
    // keeping large-residual bins flexible for future large items.
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // When many bins are open, discourage opening new ones implicitly by
    // rewarding use of existing bins more aggressively.
    let crowding = open_bins_count as f64 / (1.0 + step_index as f64);
    if bin_residual != bin_capacity {
        score -= 2.0 * crowding.min(3.0);
    } else {
        // New-bin candidate: penalize when decent fits exist, reward when
        // the item is large relative to typical residual space.
        let large_item = item_size as f64 > mean_residual;
        if large_item { score -= 4.0; } else { score += 6.0 + 2.0 * crowding.min(3.0); }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * progress;
    }

    // Small global regularization: prefer bins whose residual is close to
    // the mean (keeps bin population homogeneous and predictable).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Normalize post residual
    let post_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, prefer larger residuals (waste tolerated); later, penalize heavily.
    let early_weight = (1.0 - progress) * (1.0 - progress);
    let late_weight = progress * progress;

    score += post_norm * post_norm * 40.0 * (0.5 + late_weight);
    score -= post_norm * 25.0 * early_weight;

    // Smooth cubic interaction between item size and progress
    let item_norm = item_size as f64 / cap;
    score -= item_norm * item_norm * item_norm * 30.0 * (0.3 + 0.7 * progress);

    // Reward tight fits via smooth sigmoid-like term of post_residual
    let tightness = (-post_norm * 8.0).exp();
    score -= tightness * 20.0;

    // Last-chance bin bonus (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post_norm);
    }

    // Lookahead: reward bins whose post residual can still fit the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let next_norm = next_item_size as f64 / cap;
        score -= 12.0 * (1.0 - next_norm) * (0.4 + 0.6 * progress);
    }

    // Penalize bins far from mean residual (fragmentation signal), smooth quadratic
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Mild penalty for opening new bins when many open bins exist
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 / 20
    let r20 = post_residual % 20;
    let r10 = post_residual % 10;
    // Perfect closure classes (0 mod 20 best, then 10, then odd residues)
    let class_bonus: f64 = match (r20, r10) {
        (0, _) => -18.0,
        (10, _) => -10.0,
        _ => {
            // penalize odd / awkward residues more as they grow away from 10
            let dev = (r10 as f64 - 5.0).abs();
            2.0 + dev * 1.5
        }
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: tiny slivers are dead space
    let sliver = post_residual / 10; // 0 => post_residual < 10 (dead space)
    score += match sliver {
        0 => 25.0,
        1 => 6.0,
        2 => -2.0,
        _ => -4.0,
    };

    // Coupling with next item: reward residuals that can host next item exactly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0;
            score += gap * 0.15;
            if gap == 0.0 {
                score -= 12.0; // perfect two-item closure
            }
        } else {
            score += 5.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: many open bins -> prefer compacting into existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score -= crowd * 1.2 * (0.5 + progress);

    // Mean residual alignment: bins below mean residual are "loose", deprioritize
    let res_frac = post_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    score += (res_frac - mean_frac) * 10.0;

    // New-bin candidate: only attractive when current item leaves a bad class
    // and the next item is large (fresh bin gives full flexibility)
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual == 0 { 0.0 } else { 1.0 };
        let next_pressure = if next_item_size > 60 { 1.0 } else { 0.0 };
        let discount = 8.0 + 30.0 * progress * next_pressure
            - 20.0 * (1.0 - bad_fit);
        score += discount;
        if fitting_bins_count > 0 {
            score += 6.0; // discourage opening new bin when alternatives exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small gaps (< 10) are unusable since items >= 1,
    // but gaps that cannot fit the typical next item are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Penalize residuals that are too small to fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward using the last bin that can fit the item (avoid opening new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Mild penalty for opening a new bin when open bins could fit.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.3;
        // But new bin is attractive if it yields a tight fit relative to item.
        if post_residual < item_size / 4 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 400.0; // perfect chain fill
        } else if next_item_size <= post_residual {
            // reward tight lookahead fit (small leftover after next item)
            let after_next = post_residual as f64 - next_item_size as f64;
            score -= (300.0 * (1.0 - after_next / bin_capacity as f64)).max(0.0);
        } else {
            // penalize if next item cannot fit into post residual when the gap is small
            let gap = next_item_size as f64 - post_residual as f64;
            if gap <= 20.0 {
                score += 40.0 * (1.0 - gap / 20.0);
            }
        }
    }

    // Penalize dead space relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Slight penalty for opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if item is large relative to residual spread, new bin is fine
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
    }

    // Mild pressure over stream progression to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: early vs late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: prefer bins where the item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize tiny dead space that nothing (min size 1, typical >= 10) can use later,
    // but only mildly; a perfect fit (post_residual == 0) is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score += 6.0; // dead space below minimum item size
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses the leftover
            let next_tight = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_tight;
        } else if next_item_size > post_residual && post_residual < 10 {
            // leftover unusable for the known next item: penalize
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // (avoids opening a new bin when a viable one exists).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global state: when many bins are open with large mean residual,
    // discourage spreading; prefer consolidating into bins below mean residual.
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff; // prefer bins with less residual than average (fuller bins)
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        // Early stream: opening bins is cheap-ish; late stream: strongly discourage.
        score += 20.0 + 45.0 * progress;
        // If an existing bin gives a perfect fit, the empty bin must lose badly.
        if post_residual == 0 {
            score += 30.0;
        }
        // If nothing fits except possibly this new bin (fitting_bins_count small),
        // opening a new bin is reasonable: reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild time-horizon coupling: as the stream progresses, prioritize exact packing
    // (low post_residual) more aggressively.
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping.
    let mut score = pr + 12.0 * norm_pr * norm_pr * (1.0 + progress);

    // Smooth coupling: post_residual vs mean residual (avoid outlier residuals).
    let dev = norm_pr - mean_residual / cap;
    score += 20.0 * dev * dev;

    // Lookahead interaction: penalize leaving residual that barely fails next item,
    // reward residual that leaves a good slot.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - (gap / cap).min(1.0)) * (1.0 - progress);
        } else {
            score += 0.35 * gap.abs() * (1.0 - gap.abs() / cap.max(1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty scaled by crowding: many open bins -> prefer filling existing ones.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: penalize opening a fresh bin unless residual structure is bad.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but harmonic class logic refines this.

    // Harmonic class of post_residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Dead-space penalty is non-linear: residuals in "unusable" harmonic classes
    // (small leftovers that few future items can fill) are heavily penalized.
    // Items are 1..100; leftover < 10 is nearly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        // leftover in [10,25): only small items fit — moderately penalize
        score += 12.0 * (25.0 - pr) / 15.0;
    }

    // Integer division thresholds: which harmonic "slot" does the leftover fall in?
    let slot = post_residual / 25; // 0,1,2,3 quarters
    match slot {
        0 => score += 0.0,                 // very tight — good
        1 => score += 4.0,                 // quarter-ish leftover
        2 => score -= 2.0,                 // half-ish leftover — future-friendly
        _ => score -= 4.0,                 // mostly empty — new-bin-like
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item
    // sizes (10/20/25/50) are "harmonically reusable".
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
    if reusable && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 - (slack.min(20) as f64) * 0.3;
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - post_residual).min(30) as f64 * 0.25;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin should win only when remaining
    // open bins are fragmented or the fit here is poor.
    if bin_residual == bin_capacity {
        // Neutral-ish base for a fresh bin; encourage it when many bins are open
        // and mean residual is low (fragmentation).
        score = 50.0 + pr;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= open_bins_count as f64 * 0.5 + (mean_residual < 30.0) as i32 as f64 * 10.0;
        score += progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0; // fresh bin can host the next item too
        }
    } else {
        // Slight preference for filling already-open bins as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 3.0;
    }

    // Mean-residual coupling: placing into a bin far from the mean residual
    // helps balance the pool; reward moving residual toward mean.
    let new_mean_shift = (pr - mean_residual).abs();
    score += new_mean_shift * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A gap is "dead" if it's too small for even the smallest plausible item.
    if post_residual > 0 {
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tightness reward: favor bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: with many bins open, avoid spreading; prefer compacting.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score += pressure * 20.0;

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are bad fits.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin if mean residual across open bins is very low (all nearly full).
        if mean_residual < 15.0 {
            score -= 60.0;
        }
    }

    // Progress-based mild compaction: early on, keep bins open; later, be stricter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: does the NEXT item fit exactly into the leftover? ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step chain: place here strongly rewarded
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits, reward proportionally to how tightly it nests
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 12.0 + 18.0 * tightness;
        } else {
            // Next item won't fit here: leftover is dead space for the lookahead
            // Penalize more when leftover is small-but-unusable (awkward gap)
            let gap = post_residual as f64;
            if gap > 0.0 {
                score += 10.0 * (1.0 - gap / (next_item_size as f64)).max(0.0);
            }
        }
    } else {
        // Last item in stream: just minimize leftover
        score -= 5.0;
    }

    // ---- Relative-to-mean-residual coupling ----
    // Prefer bins whose post-residual lands near the mean residual
    // (keeps open bins homogeneous and reusable), penalize outliers.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * diff;

    // ---- Last-chance bonus: only this bin can fit the item ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Brand-new bin: neutral-ish baseline; make it attractive only when
        // the item is large (would leave tiny unusable gaps elsewhere) or
        // many bins are open and stream is early (diversification).
        score = (bin_capacity - item_size) as f64;
        if item_size >= 50 {
            score -= 15.0;
        }
        if open_bins_count > 3 && progress < 0.5 {
            score -= 8.0;
        }
        // Late in the stream, discourage opening new bins (waste)
        if progress > 0.8 {
            score += 20.0;
        }
    }

    // ---- Dead-space penalty: tiny unusable leftovers ----
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for fuller bins overall
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize post_residual, but penalize tiny dead space
    // (wasted slivers below the minimum item size are unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Extra reward when the next item exactly consumes the remainder.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else if post_residual > 0 {
            // This placement strands space the next item can't use.
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good host.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild penalty so open bins with decent fits win by default.
        score += 30.0;
        // Late in the stream or with many open bins, opening fresh bins is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        score += open_bins_count as f64 * 0.5;
    } else {
        // Prefer bins below the mean residual (fill fuller bins first) but
        // avoid extreme fragmentation.
        let dev = mean_residual - bin_residual as f64;
        score -= 0.6 * dev;
        if (bin_residual as f64 - mean_residual).abs() > 40.0 {
            score += 6.0;
        }
    }

    // Early-stream exploration: keep residuals balanced so future items have options.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let balance = (bin_residual as f64 - mean_residual).abs();
    score += balance * (1.0 - progress) * 0.4;

    // Slight preference for tighter fits overall.
    score += 0.3 * (item_size as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap; // 0..1
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual); later, slightly
    // tolerate slack but still reward small residuals super-linearly.
    let mut score = post * (1.0 + 0.8 * progress * norm_post);

    // Smooth cubic term: dead space (very small post_residual unusable by
    // typical items) is penalized via a smooth bump around mid residuals.
    let bump = norm_post * (1.0 - norm_post);
    score += 12.0 * bump * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: if the next item fits in post_residual, reward.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let fit_quality = 1.0 - (post - next_item_size as f64) / cap;
        score -= 8.0 * fit_quality * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to slack.
        score += 4.0 * norm_post;
    }

    // New-bin candidate: empty bin gets a smooth adaptive penalty that
    // decays with progress and shrinks when the current fit is poor
    // (large post_residual) so opening fresh bins becomes attractive.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        let poor_fit = norm_post; // large slack => poor fit in existing bins
        score += 30.0 * (1.0 - progress) * (1.0 - 0.6 * poor_fit) + 10.0;
    }

    // Mild diversity pressure: many open bins with high mean residual
    // should discourage adding slack to already-loose bins.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - norm_post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Residuals that form "usable" harmonic
    // fractions of capacity (>= 1/4) are less penalized; tiny slivers
    // (< 10) are dead space and heavily penalized.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fill
    } else if pr < 10 {
        score += 25.0; // unusable sliver
    } else if pr < quarter {
        score += 10.0; // awkward leftover
    } else if pr < half {
        score -= 3.0; // still useful
    } else {
        score -= 6.0; // half-full or more remains usable
    }

    // Modulo-class coupling: if next item lands exactly in the post
    // residual (perfect chaining), reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // reward proportional closeness of next item to post residual
            let gap = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot fit here; mild penalty scaled by overshoot
            let over = (next_item_size - pr) as f64;
            score += 4.0 * (over / bin_capacity as f64).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when the current
    // item is large relative to capacity or open-bin pool is fragmented.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (bin_capacity as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // penalize new bins by default; discount when pressure high
        score += 40.0 - 25.0 * pressure - 10.0 * fragmentation;
    }

    // Harmonic integer-division threshold on item size: big items
    // (> 2/3 capacity) prefer the emptiest bin; small items prefer
    // tight fits, so scale by item class.
    let item_class = item_size / (bin_capacity / 3); // 0,1,2,3 harmonic tier
    match item_class {
        0 => score += (post_residual as f64) * 0.15, // tiny items: punish loose fits
        1 => score += (post_residual as f64) * 0.05,
        2 => score -= 2.0,
        _ => score -= 4.0, // huge items: reward any fit
    }

    // Stream progression: late in the stream, be more conservative with
    // new bins and more eager to close out bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 10.0 * progress;
        } else {
            score -= 5.0 * progress;
        }
    }

    // Slight preference for bins below mean residual (keeps balance and
    // preserves large-capacity bins for large items).
    score += 0.1 * ((bin_residual as f64) - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized dead space.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Minimum plausible future item size (small items exist, but tiny gaps
        // under ~10 are almost always dead).
        if post_residual < 10 {
            score += 60.0; // pure dead space: unusable gap
        } else if post_residual < 20 {
            score += 18.0; // nearly dead: only tiny items could use it
        } else if post_residual < 35 {
            score += 6.0;  // marginal gap
        }
        // Non-linear coupling: penalize gaps that don't match the next item well.
        if next_item_size > 0 {
            let n = next_item_size as f64;
            if n > pr {
                // gap cannot host next item: proportional dead-space penalty
                score += (1.0 - pr / n) * 15.0;
            } else {
                // gap can host next item: reward proportional to how snugly
                // the next item would fit into this residual.
                score -= (1.0 - pr / n) * 20.0;
            }
        }
    } else {
        // Perfect fit: zero waste, strongly favored.
        score -= 50.0;
    }

    // Reward filling a bin deeply (large item_size in this bin is good).
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, spreading is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive when all open
    // bins would leave ugly dead space or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: slightly worse than a decent fit, but beats
        // heavily penalized dead-space placements.
        score += 8.0 + mean_residual * 0.05;
    }

    // Stream progression: late in the stream, waste matters more (no time to
    // recover small gaps), so tighten dead-space aversion.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * (post_residual as f64 * 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (perfect two-item packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)) * (diff / 10.0).min(1.0).recip().min(5.0);
        if post_residual == next_item_size {
            score -= 50.0; // exact 2-item fill: ideal
        }
        // Penalize residuals too small for the next item (dead space risk)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize small unusable dead space relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (low post residual overall).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: only one bin fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mildly penalized so existing bins are preferred
    // unless they create large dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin good for pairing with lookahead
        }
    }

    // Late in the stream, consolidate: favor bins with below-average residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual), non-linearly amplified.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space: post residuals that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 80 {
        // usable window: mildly good, but reward even more if next item fits exactly
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 18.0;
            let leftover_after_next = post_residual as f64 - next_item_size as f64;
            score -= 6.0 * (1.0 - leftover_after_next / (bin_capacity as f64));
        }
    } else if post_residual > 80 {
        score += 8.0; // nearly empty bin after placement = wasteful split
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Many fitting bins: mild penalty to prefer consolidation.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate handling: discourage opening a new bin unless the item
    // fits poorly everywhere or the stream is early (future items need space).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_elsewhere = fitting_bins_count == 1 && (bin_capacity as f64 - item_size as f64) < 10.0;
        let base_penalty = 40.0 + 0.15 * open_bins_count as f64;
        let early_discount = 20.0 * (1.0 - progress);
        score += base_penalty - if poor_fit_elsewhere { 35.0 } else { 0.0 } - early_discount;
        // If the next item would fit nicely in the fresh bin's residual, soften penalty.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Global state coupling: prefer filling bins with above-average residual
    // (drain the fullest bins first) when many bins are open.
    if bin_residual != bin_capacity {
        let residual_f = bin_residual as f64;
        if residual_f > mean_residual {
            score -= 4.0 * ((residual_f - mean_residual) / bin_capacity as f64);
        } else {
            score += 4.0 * ((mean_residual - residual_f) / bin_capacity as f64);
        }
    }

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = 1.0 + progress;
    let poly = fit_ratio * (1.0 + 0.6 * p * fit_ratio + 0.35 * p * p * fit_ratio * fit_ratio);

    let mut score = poly;

    // Reward tight fits (low post residual) more strongly as stream progresses
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * (2.0 + 3.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) / cap * (1.5 + 2.5 * progress);
        } else {
            // Reward leaving room exactly usable by next item
            score -= 0.8 * (pr - nx) / cap * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 1.2 + 1.5 * progress;
    } else if fitting_bins_count > 2 {
        score += 0.15 * (fitting_bins_count as f64 - 2.0);
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.1 * ((bin_residual as f64 - mean_residual) / cap) * (1.0 - progress);

    // New-bin candidate: prefer it only when item leaves very poor fit everywhere else
    if bin_residual == bin_capacity {
        score += 0.5 - 0.4 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "nice" small classes (0, 1, 2) are perfect; penalize mid-range dead zones.
    let pr = post_residual;
    let class = pr % 10;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr <= 5 {
        score -= 20.0;
    } else if pr <= 15 {
        score -= 8.0;
    } else if class >= 6 && class <= 9 {
        // dead-zone harmonic: leftover in [6,9] mod 10 is hard to reuse
        score += 6.0;
    }

    // Integer-division threshold: does the leftover admit the lookahead item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0;
            // harmonic match: leftover/next ratio near 1 is excellent
            let ratio = pr as f64 / (next_item_size as f64).max(1.0);
            if ratio < 1.5 {
                score -= 8.0;
            }
        } else {
            score += 5.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 15.0;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only open a new bin when current residuals are
    // fragmented (high mean residual spread) or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let fragmentation = mean_residual - (mean_residual % 10.0);
        let penalty = 25.0 + 30.0 * progress + (item_size as f64) * 0.2;
        if (mean_residual as u32) >= item_size + 20 && fitting_bins_count > 1 {
            score += penalty - 10.0; // keep using open bins
        } else {
            score += penalty * 0.15 + fragmentation * 0.1;
        }
    }

    // Mild tightness reward relative to capacity fractions.
    let frac = (bin_residual as f64) / (bin_capacity as f64);
    score += frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // If the next item could fit into this bin's post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // next item won't fit here: dead space risk
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Slight pull toward bins below mean residual (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no good option exists.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * -0.5;
    }

    // Progression-aware mild scaling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect chain: post_residual == next_item_size
        if diff < 0.5 {
            score -= 60.0 + 0.5 * nxt;
        } else if post_residual as u32 >= next_item_size {
            // Next item still fits here: mild reward proportional to closeness
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64)) - 10.0;
        } else {
            // Dead space for the next item: penalize proportionally to wasted gap
            score += 12.0 + 0.6 * diff;
        }
    } else {
        // Last item: prefer tightest fill
        score += 0.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving residuals that are too small to ever be useful
    // (anything below the minimum item size of 1 is dead; below ~10 nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0 - (post_residual as f64);
    }

    // Relative-to-mean coupling: bins with residual far above mean are
    // attractive targets; near-empty bins slightly deprioritized vs mean.
    let resid_f = bin_residual as f64;
    if resid_f < bin_capacity as f64 {
        score -= 0.3 * (resid_f - mean_residual);
    } else {
        // New-bin candidate: baseline that loses only when an open bin is a great fit.
        score = 40.0 + 0.1 * (post_residual as f64);
        if next_item_size > 0 {
            // A fresh bin can chain the next item too if item+next fits exactly-ish
            if (item_size as f64 + next_item_size as f64 - bin_capacity as f64).abs() < 0.5 {
                score -= 30.0;
            }
        }
        // Late in the stream, avoid spawning bins unnecessarily.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && (post_residual as i64) < (next_item_size as i64) {
            score += 6.0 * (1.0 - dead / (next_item_size as f64));
        } else if next_item_size == 0 {
            score += 2.0;
        }
    }

    // Last-chance bin bonus: only fitting bin, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 3.0;
    }

    // Perfect fit extreme reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded/tight
    if bin_residual == bin_capacity {
        score += 25.0;
        // If many open bins with slack, discourage new bin further
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // Late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty when bin residual is far above mean (fragmentation spread)
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: reward tight fits (small post_residual), non-linearly.
    let mut score = norm_post * norm_post * (1.0 + 2.0 * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly.
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score *= progress_weight;

    // Penalize residuals that cannot hold a typical next item,
    // smoothly via a quadratic gap term against the lookahead.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        let gap_norm = gap / cap;
        // Positive gap (wasted space beyond next item) mildly penalized;
        // negative gap (can't fit next item) penalized more strongly.
        score += if gap < 0.0 { -gap_norm * gap_norm * 2.0 } else { gap_norm * gap_norm * 0.5 };
    }

    // Interaction: tight fits are more valuable when few bins fit the item.
    if fitting_bins_count <= 1 {
        score -= 0.35 * (1.0 - norm_post);
    }

    // Last-chance bonus scaled by how much space this placement saves
    // relative to the mean residual across open bins.
    let save = (mean_residual - post) / cap;
    score -= 0.15 * save.max(0.0);

    // New-bin candidate: empty residual == capacity. Discourage opening a
    // new bin when a decent fit exists, but allow it late in the stream
    // or when the fit would leave large dead space.
    if bin_residual == bin_capacity {
        let dead = norm_post; // = 1.0 for empty bin baseline comparison
        let _ = dead;
        let fit_quality = norm_item; // larger items justify a fresh bin
        score += 0.9 - 0.8 * fit_quality * (0.5 + 0.5 * progress);
        // If the item is large and late, opening a bin is fine.
        score -= 0.4 * progress * fit_quality;
    }

    // Mild penalty for proliferating bins early on.
    score += 0.02 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on "friendly"
    // classes (multiples of 10, or tiny dead space) are preferred.
    let post_class = if post_residual == 0 {
        -60.0 // perfect fit: strongly reward
    } else if post_residual <= 5 {
        -25.0 // near-perfect: tiny dead space is fine
    } else if post_residual % 10 == 0 {
        -12.0 // round residual: future items likely to fit
    } else {
        let q = post_residual / 10; // integer division class
        (post_residual % 10) as f64 * 2.0 + q as f64 * 0.5
    };
    score += post_class;

    // Modulo-3 / modulo-7 harmonic coupling between post_residual and next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits after this placement: reward, scaled by leftover
            // harmony of the doubly-post residual.
            let double_post = post_residual - next_item_size;
            score -= 20.0 + (double_post % 5) as f64;
        } else {
            // Next item won't fit here: penalize proportionally to the mismatch.
            score += (next_item_size - post_residual) as f64 * 0.4;
            // If the mismatch is harmonically close (within one class), soften it.
            if next_item_size - post_residual <= 10 {
                score -= 4.0;
            }
        }
    } else {
        // Last item: any residual is pure waste; reward tight fits extra.
        score += post_residual as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + (post_residual <= 10) as i32 as f64 * 10.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current residual
    // is harmonically bad (small awkward leftover) or stream is early.
    if bin_residual == bin_capacity {
        let awkward = post_residual % 10 != 0 && post_residual > 5 && post_residual < 20;
        let early = (step_index as f64) / (total_items.max(1) as f64) < 0.2;
        score += 30.0;
        if awkward { score -= 35.0; }
        if early { score -= 10.0; }
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Slight preference for filling bins tighter than the mean residual.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Mild aging pressure: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavy penalty for unusable small gaps.
    // A post_residual below the minimum plausible item size (1..100 stream,
    // but small gaps < ~15 are rarely reusable) is dead space.
    if post_residual > 0 {
        if post_residual < 15 {
            score += 60.0; // nearly unusable gap
        } else if post_residual < 30 {
            score += 25.0; // poor gap
        } else if post_residual < 50 {
            score += 8.0; // marginal gap
        } else {
            // large residual is reusable; reward it
            score -= 10.0;
        }
    } else {
        // perfect fill
        score -= 80.0;
    }

    // Tight-fit reward: item fills a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins,
    // but never so strongly that we force bad fits (dead-space term dominates).
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin starts from the base
    // post_residual (capacity - item) and gets a moderate opening cost so it
    // is only chosen when all existing bins would create dead space.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If nothing else fits, allow the new bin comfortably.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Lookahead: if the next item would fit in the post residual, reward it.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }

    // Slight drift with stream progression: later in the stream, consolidation
    // matters more, so tighten the dead-space penalty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness * tightness;

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits exactly or tightly after this placement.
        let next_gap = post_residual - next_item_size;
        score -= 15.0 * (1.0 - next_gap as f64 / (bin_capacity as f64));
        if next_gap == 0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: penalize creating dead space,
        // unless this placement itself was tight.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (consolidate fullness), penalize dipping into unusually empty bins.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 10.0 * dev;
    }

    // Penalize opening a new bin when open bins exist that fit and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_fits_bonus = if fitting_bins_count > 0 { 0.0 } else { -10.0 };
        score += 12.0 * (1.0 - progress) + open_fits_bonus;
        // A new bin is attractive only if the item is large and no tight option exists.
        if item_size >= 60 && post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) - 12.0 * pr_norm * (1.0 - pr_norm) * (1.0 - progress);

    // Penalize small dead space that becomes unusable
    if pr > 0.0 && pr < item_size as f64 {
        score += 8.0 * (1.0 - pr / cap);
    }

    // Reward tight fits, stronger late in stream
    let tightness = 1.0 - (pr / cap);
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward leaving room for next item, penalize near-misses
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx && pr - nx <= 10.0 {
            score -= 5.0;
        } else if pr < nx && pr > 0.0 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: avoid opening new bins when this is the only fit
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mild penalty for spreading across many bins early
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate: discourage unless residual would be well-used
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress - (item_size as f64 / cap) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity fractions (full, half, third, quarter, tiny).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0.0 .. 1.0

    // Penalize leftovers in "dead zones": too small for typical items
    // (1..100) but nonzero => unusable sliver.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward residuals that are harmonic fractions of capacity: they are
    // reusable by common item sizes (e.g. residual 50, 33, 25, 20, 10).
    let harmonics: [u32; 8] = [100, 50, 34, 33, 25, 20, 12, 10];
    let mut harmonic_bonus = 0.0;
    for (k, &h) in harmonics.iter().enumerate() {
        let d = (post_residual as i64 - h as i64).abs();
        if d <= 2 {
            harmonic_bonus += 12.0 - k as f64 * 1.2;
        }
    }
    score -= harmonic_bonus;

    // Modulo-class logic: residual divisible by small integers is more
    // likely to be exactly filled later.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    if post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves another residue: mild bonus scaled
        // by resulting class quality.
        let nn = post_residual - next_item_size;
        if nn % 10 == 0 { score -= 5.0; }
        if nn < 10 { score += 8.0; } // would create a sliver
    } else if next_item_size > post_residual {
        // bin becomes dead after this placement unless residual ~0
        if post_residual > 0 {
            score += 10.0 + frac * 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Brand-new bin candidate: neutral-ish but slightly penalized so we
    // prefer existing bins unless they are poor fits; the emptier the
    // stream (early steps), the more acceptable a fresh bin is.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * (1.0 - progress);
        // opening a new bin is attractive when open bins are already full-ish
        if mean_residual < 20.0 {
            score -= 12.0;
        }
    } else {
        // Prefer tighter existing bins: compare residual to mean residual.
        score += (bin_residual as f64 - mean_residual).max(0.0) * 0.15;
    }

    // Mild pressure against bin explosion late in the stream.
    if open_bins_count > 10 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in "unusable" small gaps is heavily penalized.
    // A residual is unusable if it is smaller than the smallest plausible item (assume ~10)
    // or smaller than the lookahead item that could exploit it.
    let min_item = 10.0f64;
    if (post_residual as f64) < min_item {
        // Perfect or near-perfect fill: reward strongly.
        score -= 40.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Gap too small for the next item: dead space penalty.
        score += 25.0;
    } else if post_residual < item_size / 2 {
        // Very tight fit: reward (good packing).
        score -= 15.0;
    }

    // Non-linear dead-space shaping: penalize mid-size wasted gaps quadratically.
    let pr = post_residual as f64;
    let usable = if next_item_size > 0 { next_item_size as f64 } else { min_item };
    if pr >= usable {
        let waste = pr - usable;
        score += 0.08 * waste * waste / bin_capacity as f64;
    }

    // Lookahead synergy: reward when post_residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.15 * pressure;

    // New-bin candidate handling: opening a new bin should only win when the item
    // cannot fit well anywhere (few fitting bins) or current bins are nearly full.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            // No alternative: must open a bin.
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // Last-chance bin: strongly prefer using it over opening a new one.
            score += 10.0;
        }
        if next_item_size > 0 && bin_capacity as f64 - item_size as f64 >= next_item_size as f64 {
            // New bin can host both current and next item: mild discount.
            score -= 8.0;
        }
    }

    // Mean residual coupling: if the fleet of bins is loose, tolerate imperfect fits;
    // if bins are tight, be picky (penalize large post_residual more).
    if mean_residual < 25.0 {
        score += 0.3 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect / near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == nxt {
            score -= 500.0;
        } else if nxt <= pr {
            let diff = pr - nxt;
            score -= 150.0 * (1.0 - diff / 100.0);
            // extra bonus if next item leaves near-zero residual after step 2
            if diff <= 5.0 {
                score -= 150.0;
            }
        } else {
            // next item cannot fit here: penalize leaving a gap that next item wastes
            let gap = nxt - pr;
            score += 0.5 * gap.min(50.0) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin before opening a new bin: strong bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize opening new bins when open bins can fit, more so early in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 40.0 * (1.0 - progress);
        // but if no open bin fits, new bin is the only option
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference to fill fuller bins
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, amplify non-linearity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no typical item can use: residual below ~10
    // (min item size) is pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 - 4.0 * post_residual as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
            // next item cannot use this bin's leftover: slight penalty scaled by waste
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more willing to keep bins open
    // (more future items to fill gaps); late, prefer consolidating.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * tightness;

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins to avoid bin proliferation.
    score -= 0.05 * mean_residual;
    score -= 1.5 * open_bins_count as f64 * tightness;

    // New-bin candidate handling: an empty bin has zero tightness; make it
    // attractive only when existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream.
        score = 55.0 - 30.0 * (1.0 - progress);
        // If next item is large and current item is small, a fresh bin is fine.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) sharpening.
    let mut score = norm_pr + 1.5 * norm_pr * norm_pr;

    // Smooth coupling with stream progress: early on, keep bins flexible;
    // later, tolerate tight fits more aggressively (cubic interaction).
    let flex = 0.6 * (1.0 - progress).powi(2);
    score += flex * norm_pr * (1.0 - norm_item);

    // Reward near-perfect fits smoothly (cubic decay of residual).
    score -= 0.8 * (1.0 - norm_pr).powi(3) * (0.5 + 0.5 * progress);

    // Lookahead: reward if next item fits into post_residual (smooth affinity).
    if next_item_size > 0 {
        let fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = ((pr - next_item_size as f64).abs()) / cap;
        score -= 0.7 * fit_next * (1.0 - gap) * (1.0 - progress);
        score += 0.3 * (1.0 - fit_next) * norm_next * norm_next;
    }

    // Penalize dead space relative to mean residual (non-linear saturation).
    let dead = (pr - mean_residual).max(0.0) / cap;
    score += 0.4 * dead * dead;

    // Last-chance bonus: only one fitting bin -> smooth reward for using it.
    if fitting_bins_count == 1 {
        score -= 0.5 * (1.0 - norm_item) * (0.3 + 0.7 * progress);
    }

    // Mild penalty for spreading across many open bins when residual is large.
    score += 0.02 * open_bins_count as f64 * norm_pr * norm_item;

    // New-bin candidate: make empty bin attractive only when fits are poor.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        score += 2.5 * (1.0 - norm_item) * (1.0 - progress) - 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: make empty bin attractive only when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline: slightly worse than a perfect fit, better than large dead space.
        score = bin_capacity as f64 * 0.5;
        // If item fills a fresh bin exactly, strongly favor it.
        if item_size == bin_capacity {
            score = -1000.0;
        }
        // If next item is large, a fresh bin is valuable (pairing potential).
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 40.0;
        }
        // If many bins can fit, opening new bin is less urgent.
        score += 8.0 * fitting_bins_count as f64;
        // Penalize opening new bins early in the stream (keep bins consolidated).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If mean residual is high, prefer using existing space.
        score += 0.3 * mean_residual;
        return score;
    }

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score = -1000.0;
        return score;
    }

    // Harmonic class logic: classify post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let post_frac = pr / cap; // fraction of capacity remaining

    // Dead-space thresholds via integer division on post_residual.
    // post_residual < 10 is nearly dead (items >= 1 though, so mild).
    if post_residual < 5 {
        score -= 50.0; // tiny residual is fine, nearly perfect
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        // awkward zone: too small for typical items but wasteful
        score += 15.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    } else if post_residual <= 50 {
        score += 5.0;
    }

    // Modulo arithmetic: residuals in multiples of 10 pair well with typical sizes.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 4.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
            // Harmonic: does next item leave a multiple-of-10 residual too?
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot fit here; residual becomes dead space if small.
            if post_residual < 10 {
                score -= 20.0;
            } else if post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Tightness reward: fraction-based coupling.
    score -= 20.0 * (1.0 - post_frac); // tighter fits slightly favored beyond raw residual

    // Late-stream consolidation: prefer existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    // Spread control: if this bin's residual is far from mean, mild penalty.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // Gaps below the minimum item size (1..~10) can never be filled again.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 10.0;
    }

    // Reward tight fits: small post_residual relative to the item.
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use the leftover -> dead space likely.
            score += 6.0;
        }
    }

    // Open-bins pressure: penalize spreading across many bins slightly,
    // but reward using an existing bin when few alternatives exist.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has full residual; make it
    // moderately attractive when open bins are crowded but not when a good
    // fit exists. Base cost of a fresh bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If many bins are open with small residuals, opening fresh is fine.
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Slight stream-progression term: later in the stream, be more conservative
    // about leaving dead space (waste matters more when fewer items remain).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= 40.0 * fill_ratio * fill_ratio;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward when post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left for next item; mild reward proportional to how well it matches.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * next_fit * next_fit;
        } else {
            // Dead space for the next item: penalize leftover below next item size.
            let gap = next_item_size - post_residual;
            score += 0.8 * gap as f64;
        }
    }

    // Penalize creating small unusable fragments relative to mean residual.
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.4 {
        score += 10.0 + 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive for large items or when
    // no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 30.0 + 0.5 * open_bins_count as f64;
        let large_item_bonus = if item_size >= 50 { -20.0 } else { 0.0 };
        let no_alternative = if fitting_bins_count == 0 { -45.0 } else { 0.0 };
        score += base + large_item_bonus + no_alternative;
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small post residual is good
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0;
    }
    // If next item nearly fits, mild penalty for wasting the space
    if next_item_size > post_residual && next_item_size > 0 && next_item_size - post_residual <= 15 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when the item is large relative to capacity or fits poorly elsewhere
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = item_size as f64 / bin_capacity as f64;
        // Default: new bin is slightly discouraged
        score += 40.0;
        // Large items late in the stream: opening fresh bins is fine
        if tightness > 0.6 {
            score -= 30.0 * tightness;
        }
        // Early stream: keep options open, prefer new bins for big items
        if progress < 0.3 && tightness > 0.5 {
            score -= 20.0;
        }
        // Many open bins with high mean residual: prefer filling them
        if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
            score += 50.0;
        }
    }

    // Prefer bins with below-average residual (tighter bins first)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Mild pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = 1.0 + 0.6 * progress - 0.4 * progress * progress;
    score *= poly;

    // Penalize wasted residual more strongly as the stream progresses
    score += norm_pr * norm_pr * (20.0 + 40.0 * progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    score -= (1.0 - norm_pr).powi(3) * 15.0;

    // Last-chance bin bonus (only one fitting bin)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 + 10.0 * progress;
    }

    // Dead-space penalty: residual too small to fit typical future items
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead: reward if next item fits post_residual
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0 * (1.0 - (pr - (next_item_size as f64 - pr).abs()) / cap);
        }
    }

    // Mild preference for bins below mean residual early, above later
    score += 0.3 * (mean_residual - pr) * (1.0 - 2.0 * progress);

    // New-bin candidate: penalize opening new bins when many bins exist
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * open_bins_count as f64 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic class of post_residual: classify leftover space into residue
    // classes modulo small integers to detect "usable" vs "dead" space.
    let r = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual).
    let mut score = r;

    // Harmonic residue classes: leftover space that is a multiple of common
    // item sizes (mod 10 classes) is more likely to be filled later.
    let r_u = post_residual;
    let class_bonus: f64 = if r_u == 0 {
        -30.0 // perfect fit, best possible
    } else if r_u % 10 == 0 {
        -12.0
    } else if r_u % 5 == 0 {
        -6.0
    } else if r_u >= 10 && r_u <= 20 {
        -8.0 // leftover fits smallest item class
    } else if r_u < 10 {
        10.0 // dead space below minimum item size
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold on post_residual: which harmonic band is it in?
    let band = r_u / 25; // 0..=4 quartile bands
    score += match band {
        0 => -4.0,          // 0..24: very tight
        1 => -1.0,          // 25..49
        2 => 0.0,
        3 => 2.0,
        _ => 4.0,           // 75..100: nearly empty, wasteful
    };

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r_u {
            score -= 25.0;
        } else if next_item_size <= r_u {
            score -= (r_u - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: slight penalty proportional
            // to how much space would be stranded
            score += (next_item_size - r_u).min(20) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is justified when all open
    // bins would leave bad harmonic classes (dead space < 10).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin unless current fit is terrible.
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // opening fresh bin may serve the next item better
            score -= 5.0;
        }
        // early in stream, more bins are fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already "committed" — prefer filling it.
    let dev = mean_residual - r;
    score -= dev * 0.15;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3 * (r / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest future item (1..=100, min plausible ~10) are dead space.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 500.0; // unusable sliver -> strong penalty
    } else if (post_residual as f64) < 20.0 {
        score += 120.0; // nearly dead gap
    }

    // Non-linear coupling: quadratic waste on mid-size gaps that few items fit.
    if post_residual > 0 && post_residual < item_size {
        score += 0.5 * (item_size - post_residual) as f64;
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only open a new bin when the current bin
    // would leave a poor fit or the next item won't fit here.
    if bin_residual == bin_capacity {
        // Brand-new empty bin: perfect post_residual, but discourage unless needed.
        let next_fits_here = next_item_size > 0 && next_item_size <= bin_residual - item_size;
        if next_fits_here {
            score += 200.0; // existing bin keeps lookahead feasible
        }
        let pressure = open_bins_count as f64 / (step_index.max(1) as f64 + 1.0);
        score += 50.0 * pressure;
        // If item is large, a fresh bin is fine (it will pair with next item).
        if item_size >= 60 {
            score -= 80.0;
        }
    } else {
        // Reward tight fits (low post residual) with lookahead compatibility.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 40.0;
        } else if next_item_size > 0 {
            score += 0.3 * next_item_size as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Open-bin pressure: mildly discourage scattering across many bins.
    score += 0.5 * open_bins_count as f64;

    // Slight reward for being tighter than the mean residual.
    score -= 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, with mild normalization by capacity.
    score += (bin_capacity as f64 - post_residual as f64) * 0.01;

    // Aggressive 2-step lookahead: reward perfect match where next item fits exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect two-item packing
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward small slack after hypothetical next placement
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let miss = (next_item_size - post_residual) as f64;
            score += 6.0 * (miss / 100.0).min(1.0);
        }
    } else {
        // last item: just minimize post residual
        score -= 8.0;
    }

    // Compare post_residual relative to mean residual across open bins:
    // bins with residual below mean are scarcer; placing there is fine if fit is tight.
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        if pr < mean_residual {
            score -= 3.0 * (1.0 - pr / mean_residual);
        } else {
            score += 3.0 * ((pr - mean_residual) / mean_residual).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize tiny dead space (< 10 unusable for smallest items).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // neutral baseline: slightly above well-fitting open bins
        score += 10.0;
        // but if many open bins and this is early in stream, opening new bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Slight preference for consolidating into fewer bins when few are open.
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 1.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward bins whose leftover can host the next item,
    // penalize leftovers that are too small for the next item (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) >= next_item_size && next_item_size >= 1 {
            score -= 0.6 * nxt * (1.0 - post / (2.0 * cap));
        } else if post_residual > 0 {
            // dead space relative to next item
            score += 0.4 * post * (1.0 + nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.35 * item_size as f64;
    }

    // Prefer packing into already-crowded bins: deviation from mean residual.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
        // mild reward for using bins below mean residual (fuller bins)
        if (bin_residual as f64) < mean_residual {
            score -= 0.1 * mean_residual;
        }
    } else {
        // New-bin candidate: penalize opening a bin unless the item is large
        // relative to capacity or existing bins are nearly saturated.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        score += 8.0 - 4.0 * item_frac - 2.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early in the stream, be slightly conservative about fragmenting space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.25 {
        score += 0.05 * post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) coupling
    let mut score = pr + 12.0 * pr_norm * pr_norm * cap;

    // Tight fit reward: smooth bump when post_residual is small relative to item
    let tight = (1.0 - pr_norm).powi(2);
    score -= 8.0 * tight * (0.5 + fit_ratio);

    // Penalize dead space that cannot fit the average next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = ((nxt - pr) / cap).max(0.0);
        score += 15.0 * unusable * (0.5 + progress);
        // Reward leaving space exactly for the next item
        let exact = (1.0 - ((pr - nxt).abs() / cap)).max(0.0);
        score -= 6.0 * exact * exact;
    } else {
        // Last item: strongly prefer filling bins as fully as possible
        score -= 10.0 * (1.0 - pr_norm);
    }

    // Last-chance bin bonus (avoid opening a new bin when only one fits)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 - pr_norm);
    }

    // New-bin candidate handling: penalize opening a new bin early, more later
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 20.0 + 30.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // But allow new bin if all open bins would leave very bad fits
        if fitting_bins_count > 0 {
            let avg_bad = ((mean_residual - item_size as f64) / cap).max(0.0);
            score -= 10.0 * avg_bad * avg_bad * progress;
        }
    }

    // Mild preference for bins below mean residual (balance residuals smoothly)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Stream progress coupling: later in stream, prefer tighter packing more strongly
    score *= 1.0 + 0.5 * progress * (1.0 - pr_norm);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead zones" (residual < 10 or in awkward bands) are penalized.
    if post_residual == 0 {
        score -= 50.0; // perfect fit is best
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect: residual too small for any item
    } else {
        // harmonic class: post_residual bucketed by capacity/8 divisions
        let class = (cap / 8.0).floor();
        let k = (post_residual as f64 / class).floor();
        score += k * 3.0; // larger coarse class => worse
        // awkward residuals that no typical item (>=10) can use
        if post_residual < 20 {
            score += 12.0;
        }
    }

    // Reward tight fits: small post_residual relative to item size
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize leaving mid-range residual
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when mean residual across open bins is large (open bins are full-ish)
    if bin_residual == bin_capacity {
        if mean_residual > 25.0 {
            score -= 20.0;
        } else {
            score += 30.0; // prefer reusing open bins with usable space
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    // many open bins => pressure to fill existing ones
    score += open_bins_count as f64 * 0.5;

    // mean residual context: if this bin is below mean residual (fuller),
    // prefer it slightly
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space is worse if no future item can use it (lookahead check).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward using a bin whose residual matches the item well (tight packing).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mild preference for bins below mean residual (consolidating fuller bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream, prefer tighter fits even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit: heavily reward leaving almost nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // Dead space penalty: residual too small to plausibly hold future items
    // (items are >= 1, but typical useful chunks matter; penalize tiny pockets).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item fits exactly into the
    // post-residual, this is a perfect chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly it matches,
            // measured against the mean residual as a reference scale.
            let leftover_after_next = (post_residual - next_item_size) as f64;
            let scale = mean_residual.max(1.0);
            score -= 250.0 * (1.0 - leftover_after_next / scale).clamp(0.0, 1.0);
            score -= 50.0;
        } else {
            // Next item does NOT fit here: penalize more if the gap is small
            // (we stranded the next item just outside), less if gap is huge.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap * 2.0).min(150.0);
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // open bins are nearly full (small mean residual) or crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        // Penalize new bin by how much capacity would be "wasted" relative to
        // mean residual of open bins; small mean residual => open bins nearly
        // full => new bin is fine.
        let waste = (bin_capacity as f64 - mean_residual.max(0.0)) / bin_capacity as f64;
        score += 400.0 * (1.0 - waste).clamp(0.0, 1.0);
        score += open_pressure * 10.0;
        score -= 60.0 * progress; // late in stream, reusing bins is cheaper
    }

    // Mild preference for filling already-open bins rather than spreading load.
    score += open_bins_count as f64 * 0.5;

    // Slight tie-break toward bins whose residual is close to the mean
    // (keeps a balanced pool of medium gaps for future items).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.15;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr as f64 * (1.0 + 0.8 * x * x);

    // Smooth coupling with stream progress: tighten packing late in the stream
    score *= 1.0 + 0.5 * progress * (1.0 - x);

    // Reward nearly-full placements (small dead space) super-linearly
    score -= 40.0 * (1.0 - x).powi(6);

    // Last chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize when this bin is much emptier than the mean (wasteful use of a roomy bin)
    let mean_x = mean_residual / cap;
    score += 10.0 * (x - mean_x).abs();

    // Lookahead: if next item fits exactly into post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let fit_quality = 1.0 - ((pr as f64 - nxt) / cap).abs();
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            // next item cannot fit here; slight penalty proportional to wasted potential
            score += 4.0 * (1.0 - x);
        }
    }

    // Mild penalty for spreading across many open bins early
    score += 0.5 * open_bins_count as f64 * x * progress;

    // New-bin candidate handling: empty bin has large post residual; make it
    // attractive only when no tight fit exists elsewhere (implicit via base score),
    // but add a smooth discount early in the stream where fresh bins are cheap.
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress) * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // (divisible by common small item sizes 10..20), penalize awkward ones.
    let pr = post_residual;
    if pr > 0 {
        let mut friendliness = 0.0;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                friendliness += 6.0;
            }
        }
        if pr % 5 == 0 {
            friendliness += 2.0;
        }
        score -= friendliness;
        // Dead space penalty: residuals below 10 are pure waste
        if pr < 10 {
            score += 40.0;
        } else if pr <= 15 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Capacity fraction classes: bins near half or full use are valuable targets
    let used = bin_capacity - bin_residual;
    let half = bin_capacity / 2;
    if used >= half && used < bin_capacity {
        score -= 5.0;
    }

    // Lookahead: check whether next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            // next item fits: mildly good, better if leftover stays friendly
            let nxt_left = pr - next_item_size;
            if nxt_left % 10 == 0 {
                score -= 10.0;
            }
            score -= 3.0;
        } else {
            // next item won't fit here: penalize less if residual still useful
            if pr >= 10 {
                score += 4.0;
            } else {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; cheaper early, pricier as stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 30.0 + 40.0 * progress + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // attractive if next item also leaves friendly residual
            let left = bin_capacity - next_item_size;
            if left % 10 == 0 {
                score -= 8.0;
            }
        }
    }

    // Mean residual coupling: prefer bins deviating favorably from the mean
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items (1..100)
    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: discourage proliferation of open bins
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins below mean residual (filling emptier bins less aggressively)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: make it moderately unattractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Late-stream caution: reduce waste as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_slack = (post_residual - next_item_size) as f64;
        // Perfect two-item fill is ideal; tighter match => bigger reward.
        score -= 30.0 * (1.0 - fit_slack / bin_capacity as f64);
        // Bonus when the pair fills the bin almost exactly.
        if fit_slack <= 5.0 {
            score -= 25.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot follow into this bin; penalize leftover dead space
        // more strongly when the leftover is small (unusable).
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 20.0 + (10.0 - dead) * 2.0;
        } else {
            score += 5.0;
        }
    }

    // Compare post_residual relative to mean residual: leaving less than average
    // is good (tight packing), leaving much more is wasteful.
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize creating tiny unusable residuals outright.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Penalize small dead space that nothing (min size 1..100) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: only this bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0 + 0.5 * next_item_size as f64;
        } else {
            score += 0.3 * (next_item_size as f64 - post_residual as f64).min(80.0);
        }
    }

    // Tightness: prefer bins that are already partially filled (small residual waste).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Global state coupling: many open bins -> prefer compacting into existing bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin is drier than average, favor it (drain small bins).
    score -= 1.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no open bin fits or residual is huge.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else {
            score += 200.0 + 80.0 * (1.0 - progress);
        }
    }

    // Late-stream pressure: consolidate harder as stream ends.
    score -= 50.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, penalize wasted space more
    let progress_coupling = 20.0 * progress * norm_pr * norm_pr;
    score += progress_coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Mean-residual interaction: if this bin's residual deviates from mean, mild penalty
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * dev.abs();

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: penalize if post_residual can't fit next item but almost could (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 12.0 * gap * (1.0 + progress);
        } else {
            // reward leaving room for the next item
            score -= 6.0 * (pr - nxt).min(cap) / cap;
        }
    }

    // Mild penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    // New-bin candidate adjustment: empty bin gets moderate baseline, worse late
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual modulo 10: small dead space classes
    // (1..=9 mod 10) are more reusable than large gaps; mod-10 buckets
    // approximate common item sizes (integers 1..100).
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        // Penalize dead space that no plausible item can fill.
        if pr < 10 {
            // Tiny gap: nearly unusable unless future item is tiny.
            score += 8.0 - (pr as f64);
        } else {
            // Reward residuals that are themselves likely item sizes.
            if (10..=80).contains(&pr) {
                score -= 10.0;
            }
            // Harmonic bonus: residuals divisible by 10 align with
            // capacity fractions (100 = 10 * 10).
            if class == 0 {
                score -= 5.0;
            }
            // Half-capacity residual is highly reusable.
            if pr == 50 {
                score -= 6.0;
            }
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement sets up a chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr && pr > 0 {
            score -= 25.0;
        } else if next_item_size <= pr && pr > 0 {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // are crowded (high mean fill) — encourages consolidation.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 25.0 * fill_ratio;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, allow fresh bins more freely (better long-run packing).
        score -= 10.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 12.0; // no open bin can meaningfully host items
        }
    }

    // Prefer placing into bins whose residual is close to item size
    // (tight fit) relative to the average residual spread.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * tightness;

    // Mild penalty for fragmenting many open bins state.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 15.0;
    }
    // Reward leaving space usable for the next item (lookahead)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }
    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    // Pressure from number of open bins: prefer consolidation
    score += 0.6 * open_bins_count as f64;
    // Prefer bins with below-average residual (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.15;
    // Slight preference to open new bins early vs late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 800.0; // chain of perfect fits
        } else {
            score -= 400.0 * (1.0 - next_fit_gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving large unusable residue
        let dead = post_residual as f64;
        if dead < next_item_size as f64 {
            score += 150.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Reward tight fits relative to current residual (small waste fraction)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 300.0 * tightness;

    // Compare post_residual against mean residual: prefer bins that end below average
    // (leaves larger bins for harder items)
    if post_residual as f64 > mean_residual {
        score += 0.8 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.4 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    } else if fitting_bins_count > 2 {
        score += 20.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: penalize opening a new bin unless nothing else fits well.
    // An empty bin has residual == capacity, so post_residual is large; add a fixed
    // opening cost that tight-fit rewards on existing bins can overcome.
    if bin_residual == bin_capacity {
        score += 350.0;
        // But if the next item also fits the fresh bin with near-zero waste, soften cost
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 300.0;
            }
        }
    }

    // Slight pressure to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / total_items as f64;
    score += 50.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: subtract the used space (fill fraction of the bin).
    score -= 0.45 * (bin_capacity - post_residual) as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling (k=2): reward if the next item fits into the post-residual,
    // penalize dead space that blocks the next item.
    if next_item_size > 0 {
        let pr = post_residual as u32;
        if pr >= next_item_size {
            score -= 10.0 * (1.0 - t * 0.5);
        } else {
            let waste = next_item_size - pr;
            score += 0.6 * waste.min(30) as f64;
        }
    }

    // Global state: prefer bins with residual below the mean (consolidate emptier space usage),
    // mildly scaled by stream progress.
    score += (0.15 + 0.25 * t) * (bin_residual as f64 - mean_residual);

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * 0.1;
    }

    // New-bin candidate: penalize moderately early, more as the stream progresses,
    // so a new bin is chosen only when existing fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * t + 2.0 * (fitting_bins_count as f64);
    }

    // Small late-stream pressure to fill bins tightly.
    score += 4.0 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // non-linear coupling of post residual with stream progress
    let poly = norm_pr * (1.0 + progress * norm_pr * 3.0) - progress * progress * norm_pr * norm_pr;
    score += poly * cap * 0.5;
    // penalize tight fits late in stream mildly, reward early
    score -= (1.0 - norm_pr) * (1.0 - progress) * 5.0;
    // last chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }
    // lookahead: if next item fits post residual, reward
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0 * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        score += 2.0 * norm_pr;
    }
    // avoid wasting nearly full bins
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residues that are "reusable" (common small
    // item sizes 1..100) should be penalized less than awkward dead space.
    let r = post_residual;
    let class: f64 = match r {
        0 => -6.0,                                   // perfect fit: best outcome
        x if x % 10 == 0 => -3.0,                    // decadal residual is highly reusable
        x if x % 5 == 0 => -1.5,
        x if x % 3 == 0 => -0.5,
        _ => 0.0,
    };
    score += class;

    // Integer-division thresholds: small leftovers are dead space.
    if r > 0 && r < 10 {
        score += 12.0;                               // tiny unusable sliver
    } else if r < 20 {
        score += 4.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly
    // or with a good harmonic class.
    if next_item_size > 0 {
        if next_item_size <= r {
            let nr = r - next_item_size;
            if nr == 0 {
                score -= 8.0;                        // sets up a perfect fit next step
            } else if nr % 10 == 0 || nr % 5 == 0 {
                score -= 3.0;
            }
            // penalize leaving a residual that only barely fits next item
            let slack = r - next_item_size;
            if slack > 0 && slack < 5 {
                score += 3.0;
            }
        } else {
            // this bin cannot host next item: mildly penalize big residuals
            // that will strand space anyway
            score += (r as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when current bins are
    // either full-ish or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // fresh bin baseline: slightly worse than a perfect fit, better than junk
        score = 25.0 - 0.1 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // fresh bin can always host next item too
            score -= 2.0;
        }
        if fitting_bins_count == 0 {
            score -= 15.0; // no open bin fits: definitely open new bin
        }
    } else {
        // crowding pressure: with many open bins, favor tightening existing ones
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 0.5 * progress * (mean_residual - post_residual as f64);
    }

    // Mild preference for tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // (item sizes >= 1, but small gaps < 12 rarely match future demand).
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 6.0; // up to ~+106
    } else if post_residual >= 12 && post_residual < 30 {
        // moderately awkward zone: mild penalty that decays with size
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (post_residual near zero but still usable-ish).
    if post_residual == 0 {
        score -= 30.0; // perfect packing
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; new empty bin gets hit hardest
    // since its residual is large.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid forcing
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item can use the leftover space, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot use the leftover, penalize creating that gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Slight time pressure: early in the stream, tolerate opening bins;
    // later, tighten up.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // New-bin candidate guard: empty bin has residual == capacity; make it
    // less attractive unless its post_residual is genuinely small relative
    // to capacity (i.e., huge item nearly filling a fresh bin).
    if bin_residual == bin_capacity {
        score += 8.0;
        if (post_residual as f64) < 0.25 * bin_capacity as f64 {
            score -= 25.0; // big item that fills a fresh bin well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chain
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * next_fit;
        } else {
            // next item won't fit here: penalize dead space proportionally
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when a reasonable fit exists
    if bin_residual == bin_capacity {
        score += 60.0 + 0.5 * open_bins_count as f64;
        // allow new bin if item is huge and nothing fits well
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
    }

    // Late-stream consolidation: prefer filling bins tighter as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            // Reward leaving room exactly usable by the next item.
            score -= 0.6 * next_item_size as f64;
        } else {
            // Dead space penalty scaled by how much of the next item is wasted.
            score += 0.4 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Reward tight fits (small post residual) more strongly early on,
    // when preserving bins matters over the long horizon.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= (6.0 + 6.0 * (1.0 - progress)) * tightness;

    // Last-chance bin before opening a new one: strong bonus to use it.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 10.0;
    } else if !is_new_bin && fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: baseline penalty so it only wins when open bins fit poorly.
    if is_new_bin {
        score += 8.0 + 4.0 * progress;
        // Opening a new bin is more attractive when many open bins are already full-ish.
        score -= 3.0 * (mean_residual / bin_capacity as f64);
    } else {
        // Mild penalty for spreading across many open bins.
        score += 0.3 * open_bins_count as f64;
    }

    // Prefer filling bins whose residual is close to the item (perfect match).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 0.8 * progress * progress);

    // Penalize small but nonzero dead space quadratically
    if x > 0.0 {
        score += 6.0 * x * (1.0 - x) * (1.0 - x);
    }

    // Reward tight fits
    score -= (1.0 - x) * (1.0 - x) * (1.0 - x) * 4.0;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: if next item fits post residual, reward; else penalize
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 3.0 * (ni / cap);
        } else {
            score += 2.0 * ((ni - pr) / cap);
        }
    }

    // Mild pressure from open bins and mean residual
    score += 0.05 * open_bins_count as f64;
    score += 0.3 * (mean_residual / cap - x).abs();

    // New-bin candidate penalty unless residual is large
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: divide capacity into 5 classes.
    let class = post_residual * 5 / bin_capacity; // 0..=4
    let class_bonus = match class {
        0 => 12.0, // nearly full: excellent fit
        1 => 6.0,
        2 => 0.0,
        3 => -4.0,
        _ => -9.0, // large dead space left
    };
    score -= class_bonus;

    // Exact-fill reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty scaled by how small the gap is relative to typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable gap is worse than a mid gap
    }

    // Lookahead: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0; // chainable bin
        } else {
            // penalize leaving a gap the next item cannot use
            let waste = post_residual as f64 / (next_item_size as f64);
            score += 3.0 * waste.min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive when item is large and few bins fit it.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0; // base cost of opening a new bin
        score -= 35.0 * pressure;
        score -= 10.0 * large_item;
        // late in the stream, prefer consolidating rather than opening bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild tie-break: prefer bins tighter than the mean residual.
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Small preference for low bin index pressure (fewer open bins is better).
    score += 0.1 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 15.0; // gaps that still fit typical items are fine
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: penalize bins when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // creates dead space for the known next item
    }

    // New-bin candidate: make it attractive only when open bins would waste space.
    if bin_residual == bin_capacity {
        score = 25.0 + 0.1 * open_bins_count as f64;
        if post_residual >= 10 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual large enough to fit next item: keep this bin viable
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual as f64 - next_item_size as f64) * 0.35;
    }

    // Near-miss penalty: dead space just below next item size is unusable
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.9;
    }

    // Tight fit reward relative to capacity
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= tightness * 12.0;

    // Compare against mean residual: prefer filling below-average-residual bins
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Late in stream: prefer compacting into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // New-bin candidate: prefer it only when item barely fits anywhere / very large item
    if bin_residual == bin_capacity {
        let slack = bin_residual - item_size;
        if fitting_bins_count == 0 || slack == 0 {
            score -= 40.0;
        } else if slack < 10 {
            score -= 10.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    score -= 2.5 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2) * 20.0;

    // Penalize dead space that likely becomes unusable (post_residual < typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // With many options, favor the bin whose residual best matches the item.
        score -= 8.0 * (1.0 - (item_size as f64 / bin_residual.max(1) as f64)).abs();
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // This placement blocks the next item; penalize mildly.
            score += 6.0;
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // New-bin candidate logic: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowdedness = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // If open bins have plenty of slack, discourage opening a new bin.
        score += 30.0 * crowdedness;
        // Early in the stream, keep bin count low.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If no bin can fit at all (fitting_bins_count==0 handled elsewhere), allow new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global pressure: many open bins with small mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual < 20.0 {
        score -= 10.0;
    }

    // Mild penalty proportional to item size fraction of bin (prefer filling big holes with big items).
    score += 3.0 * (1.0 - item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress.
    let mut score = pr * (1.0 + 0.9 * progress) + 60.0 * norm_pr * norm_pr;

    // Smooth interaction: residual^3 coupling with progress (dead space worse late).
    score += 900.0 * norm_pr * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits: subtract a smooth bump peaked at post_residual ~ 0..10.
    let tightness = (-pr / 12.0).exp();
    score -= 35.0 * tightness * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits the post residual, reward smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let gap = (pr - nxt) / cap;
            score -= 25.0 * (-gap * 6.0).exp() * (1.0 - 0.3 * progress);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, penalize opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling: mildly penalize fresh bins early, allow late.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins close to mean (balanced packing).
    let dev = (pr - mean_residual).abs() / cap;
    score += 12.0 * dev * dev;

    // Slight preference for fuller bins when many bins open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * fit;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual divisible by small moduli is more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        else if pr % 2 == 0 { score -= 2.0; }
        else { score += 4.0; } // odd residual is awkward
    }

    // Quotient classes on capacity fractions: prefer residuals that are
    // "harmonic" fractions of capacity (20, 25, 50 are natural anchors).
    let frac = pr as f64 / bin_capacity as f64;
    if (frac - 0.5).abs() < 1e-9 { score -= 15.0; }
    else if (frac - 0.25).abs() < 1e-9 { score -= 10.0; }
    else if (frac - 0.2).abs() < 1e-9 { score -= 8.0; }

    // Penalize tiny dead space (< 10) that nothing can use.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Next item fits but leaves a residual; reward if new residual is harmonic.
        let npr = pr - next_item_size;
        if npr % 10 == 0 { score -= 20.0; }
        if npr == 0 { score -= 100.0; }
    } else if next_item_size > pr {
        // This bin becomes dead after placement; penalize mildly.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Open new bin if existing residuals are small (poor fits) or few bins open.
        score += 40.0 - 30.0 * crowding - 10.0 * progress;
        if open_bins_count == 0 { score -= 100.0; }
        // If item is small and residual space plentiful elsewhere, discourage new bin.
        if item_size <= 20 && mean_residual > 30.0 { score += 30.0; }
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    // Prefer tighter fits among similar residuals: reward large item consumption.
    score -= 0.3 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
