    // Prefer filling bins with larger residuals early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress);

    // Slight preference for using fewer bins (denser packing among open bins)
    score += 0.1 * open_bins_count as f64;

    score
}

