        score -= 40.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 25.0; // dead space class: worst outcome
    } else if slots % 5 == 0 {
        // post_residual in {50, 100}: large harmonics, still flexible
        score -= 8.0;
    } else if slots % 2 == 0 {
        // even multiples of 10: {20,40,60,80}: reasonably reusable
        score -= 4.0;
    } else {
        // odd slots {10,30,70,90}: moderately reusable
        score -= 1.0;
    }

    // Nonlinear coupling: reward tight fits more strongly as bins get full.
    score -= 30.0 * (1.0 - frac) * (1.0 - frac);

    // If this is the last fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit. Penalize the empty-bin candidate,
    // unless the current item is huge and residuals are all small.
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        let lookahead_relief = if next_item_size > 0 {
            // if next item is large, a fresh bin is more valuable
            (next_item_size as f64 / cap) * 25.0
        } else {
            0.0
        };
        let residual_relief = (mean_residual / cap) * 30.0;
        score += base_penalty + residual_relief - lookahead_relief;
    }

    // Lookahead: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits here: mildly reward leaving usable space
        score -= (next_item_size as f64) * 0.15;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: penalize proportionally to waste
        score += (pr / cap) * 20.0;
    }

    // Stream progression: early in the stream, be more willing to spread items
    // across bins (keep flexibility); late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (open_bins_count as f64) * 2.0;

    // Prefer bins whose residual is already below the mean (consolidation).
    score += ((bin_residual as f64) - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space hard (post_residual in [1, 15])
    if post_residual > 0 && post_residual < 16 {
        score += 40.0 * (16.0 - post_residual as f64) / 15.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // next item would not fit after this placement but fits elsewhere — mild penalty
        score += 5.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, discourage spreading (favor filling existing)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 / (10.0 + 20.0 * progress)) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Mean residual coupling: penalize placing into bins far below mean residual (fragmenting)
    if (bin_residual as f64 - mean_residual).abs() > 30.0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 25.0 - (fitting_bins_count as f64) * 6.0;
        if post_residual == bin_capacity as u32 - item_size && item_size <= 40 {
            score -= 5.0; // large item in fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not zero-dead-space obsession.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect 2-chain match: strong bonus, stronger late in the stream.
            let chain_bonus = 40.0 * (1.0 + progress) * (1.0 - gap / bin_capacity as f64).max(0.0);
            score -= chain_bonus;
        } else {
            // Next item cannot follow: penalize proportional to wasted opportunity,
            // scaled by how much dead space we leave behind.
            let dead = post_residual as f64;
            score += 0.35 * dead * (1.0 + progress);
        }
    } else {
        // Last item: just minimize residual.
        score += 0.0;
    }

    // Compare post_residual against mean residual of open bins:
    // leaving a residual far below the mean creates an outlier dead bin.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        if ratio < 0.25 && pr > 0.0 {
            // Creates an unusably small residual relative to the fleet.
            score += 12.0 * (0.25 - ratio);
        } else if ratio > 1.5 {
            // Keeps a large residual: fine, mild reward.
            score -= 3.0 * (ratio - 1.5).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless post_residual is tiny (dead space).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if pr > 0.0 && pr < 5.0 {
            score += 20.0; // but not if it leaves nearly nothing usable
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize opening a new bin mildly, so it's chosen only when open bins
    // would leave very small residuals (their scores inflated above).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 10.0 + 8.0 * progress;
        score += new_bin_penalty;
        // But if next item is large and would fit a fresh bin perfectly, ease penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            let perfect = (post_residual - next_item_size) == 0;
            if perfect { score -= 25.0; }
        }
    }

    // Slight preference for consolidating into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted opportunity
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more willing later in the stream or when open bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        score += 12.0 + 20.0 * (1.0 - progress) + fragmentation * 0.05;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Mild preference to consolidate among many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * post_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let it = item_size as f64;
    let nitem = next_item_size as f64;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, waste matters more (quadratic ramp)
    let urgency = progress * progress;
    score += urgency * pr * 1.5;

    // Dead-space penalty: post-residual too small for any plausible future item
    let dead = (1.0 - norm_pr).powi(3);
    score += 30.0 * dead * urgency;

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 && nitem <= pr {
        let fit_gap = (pr - nitem) / cap;
        score -= 12.0 * (1.0 - fit_gap).powi(2);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportional to leftover
        score += 6.0 * norm_pr;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * urgency;
    }

    // Mean residual coupling: placing into bins below mean residual tightens spread
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev - 3.0 * dev;

    // Prefer filling fuller bins (implicit in pr), plus mild penalty for opening new bins
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * (1.0 - urgency);
        // opening a new bin is fine if item is large and nothing fits well
        if it >= 0.5 * cap && fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 create dead-space classes.
    let post_class = post_residual % 10;
    // Residues that are hard to fill (small leftovers that nothing fits) get penalized.
    score += match post_class {
        1 | 2 | 3 => 6.0,
        4 | 5 | 6 => 3.0,
        0 => -2.0, // perfectly aligned residual is reusable
        _ => 0.0,
    };

    // Integer-division thresholds: how many "size-10 slots" remain after placement.
    let slots = post_residual / 10;
    if slots == 0 {
        // Dead space: residual < 10 is unusable for any item.
        score += 25.0;
    } else if slots <= 2 {
        score += 4.0;
    } else {
        score -= 3.0;
    }

    // Lookahead coupling: does next_item_size land in the same harmonic class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Bonus scaled by how well the next item harmonizes with post_residual.
            let harmony = (post_residual - next_item_size) % 10;
            let harmony_bonus = if harmony == 0 {
                14.0
            } else if harmony <= 3 {
                9.0
            } else {
                5.0
            };
            score -= harmony_bonus;
        } else {
            // This bin cannot host the next item: mild penalty scaled by leftover size.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // open bins are heavily fragmented or the item is huge.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Penalize new bins by default, more early in the stream.
        score += 35.0 + 20.0 * (1.0 - progress);
        // But if open bins are fragmented (high mean residual spread vs this fit),
        // relax the penalty slightly.
        if (mean_residual - post_residual as f64).abs() > 40.0 {
            score -= 8.0;
        }
    }

    // Prefer tighter bins when several can fit: tie-break by fullness fraction.
    let fill_fraction = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_fraction;

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    // Treat gaps below the minimum plausible item size as unusable.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        // Penalize dead space heavily, scaled by how close to zero the gap is.
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else {
        // Reward leaving a gap that can still host a meaningful item,
        // especially if the lookahead item fits into the post-residual.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 4.0 + 0.05 * post_residual as f64;
        }
        // Mild penalty for very large leftover gaps (wasteful fit on a big residual)
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score += 2.0;
        }
    }

    // Perfect fit bonus: zero residual is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        // Slight preference to fill existing bins when many are open.
        score -= 0.02 * open_bins_count as f64 * (bin_residual - post_residual) as f64;
    }

    // Early in the stream, be more willing to spread items across bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size means the
    // next item fills this bin exactly -> strongly reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0;
        } else if diff <= 10 {
            score -= 25.0 - diff as f64;
        } else {
            // Penalize wasted space relative to what the next item would need.
            score += (diff as f64).powf(1.35) * 0.12;
        }
        // Bonus if next item fits at all after placement (keeps bins tight).
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here: dead space penalty scaled by waste.
            score += (post_residual as f64) * 0.05;
        }
    } else {
        // Last item: minimize residual as usual.
        score -= 5.0;
    }

    // Compare against mean residual: placing in a tighter-than-average bin is good.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(40.0) * 0.35;
    } else {
        score += (res - mean_residual).min(40.0) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize very small post residuals only mildly (fragmentation risk),
    // but near-perfect fills (<=5) are excellent.
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    // Early in the stream, allow more freedom to open bins; late in the stream,
    // consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Mild penalty for spreading across too many open bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post residual).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize leaving large dead space, especially if nothing small can use it later.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 40.0;

    // Lookahead: reward if the next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.4; // tighter chains rewarded more
        } else {
            // next item won't fit here: slight penalty for consuming a flexible bin
            score += 5.0;
        }
    }

    // Last-chance bonus: only one open bin fits; using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: only attractive when the item is large relative to
    // capacity or open bins are congested (few fitting bins, high mean residual spread).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let congestion = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        // Penalize new bins for small items; large items justify fresh bins.
        score += 25.0 - fill_ratio * 30.0 + 2.0 / congestion;
        // Late in the stream, prefer closing out existing bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Global state coupling: if mean residual across open bins is high, prefer
    // packing into existing bins to consolidate slack.
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Mild preference for bins with more remaining room when many bins are open
    // (keeps small residuals concentrated).
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let t = progress;
    score += (norm_pr * norm_pr) * (1.0 - t) * 40.0;
    score -= (norm_pr * norm_pr * norm_pr) * t * 60.0;
    // penalize small post-residual dead space, stronger late in stream
    let dead = if pr > 0.0 { (1.0 - norm_pr).powi(3) } else { 0.0 };
    score -= dead * (20.0 + 40.0 * t);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * t;
    }
    // lookahead: reward residual that could fit next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 10.0 * (1.0 - ((pr - ns) / cap).powi(2));
        } else {
            score += 8.0 * (ns - pr) / cap;
        }
    }
    // mean residual dispersion term
    score += (mean_residual - pr) * 0.15 * (0.5 + t);
    // slight preference to keep bin count low early
    score += open_bins_count as f64 * 0.05 * (1.0 - t);
    // new-bin candidate penalty unless residual is tiny
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * t;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic classes: partition post_residual into residue classes via integer division.
    // Class 0: post_residual == 0 -> perfect fit, reward strongly.
    // Class 1: small dead space (1..=10) -> hard to reuse, penalize.
    // Class 2: medium (11..=30) -> moderate value.
    // Class 3: large (>=31) -> can still host typical items.
    let dead_class = if post_residual == 0 { 0 } else if post_residual <= 10 { 1 } else if post_residual <= 30 { 2 } else { 3 };

    match dead_class {
        0 => { score -= 60.0; }
        1 => { score += 25.0; }
        2 => { score += 5.0; }
        _ => { score -= 8.0; }
    }

    // Harmonic compatibility: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chainable perfect fit
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 10 { score += 12.0; } else { score -= 10.0; }
        } else {
            // next item cannot use this bin's residue; residue is stranded until later
            score += 10.0;
        }
    }

    // Last-chance bonus: only fitting bin -> avoid opening new bin for small items.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate handling: fresh empty bin gets baseline cost so it's
    // chosen only when all open bins produce poor fits.
    if bin_residual == bin_capacity {
        score += 35.0 + 25.0 * progress;
    }

    // Prefer fuller bins relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for consolidating when many bins are open.
    score -= (open_bins_count as f64).ln() * 1.5;

    // Modulo-based tie-breaking on post_residual: residues divisible by common
    // item sizes (10, 20, 25, 50) are more reusable.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 4.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 15.0 + pressure;
    } else {
        score -= 5.0 + 0.3 * pressure;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Prefer bins below mean residual when residuals are tight.
    score += 0.15 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly or closely.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match is ideal: next item fills bin perfectly.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if (post_residual as i64) >= (next_item_size as i64) {
            // Next item can also fit here: reward closeness of match.
            score -= 30.0 - 0.5 * gap;
        } else {
            // Next item won't fit after placement: penalize leftover dead space,
            // scaled by how small the leftover is (small leftovers are waste).
            score += 0.3 * gap;
        }
    }

    // Compare post_residual relative to mean residual across open bins:
    // leaving less than average residual indicates good consolidation.
    let mean_post = mean_residual - item_size as f64;
    if post_residual as f64 > mean_post {
        score += 0.25 * (post_residual as f64 - mean_post);
    } else {
        score -= 0.15 * (mean_post - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize creating very small unusable leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect closure bonus: bin exactly filled.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Early in the stream, be slightly more willing to open new bins
    // (keep flexibility); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly when many bins are open or late,
        // reward slightly early on when open bins are scarce.
        score += 20.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize strongly by default, but relax when
    // the item is large, few bins fit it, or the item would leave
    // unusable dead space in any existing bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut new_penalty = 60.0;
        // large items justify fresh bins
        new_penalty -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // last-chance pressure: only one fitting bin -> opening new bin less bad
        if fitting_bins_count <= 1 {
            new_penalty -= 25.0;
        }
        // late in stream, avoid proliferation of barely-used bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_penalty += progress * 15.0;
        // many open bins already -> discourage opening more
        new_penalty += open_bins_count as f64 * 1.5;
        score += new_penalty;
    } else {
        // Reward tight fits: small post_residual is already the base score.
        // Penalize creating dead space that likely cannot fit the next item.
        if next_item_size > 0 {
            if post_residual < next_item_size && post_residual > 0 {
                // dead space smaller than the next item: penalize proportionally
                score += (next_item_size - post_residual) as f64 * 0.8;
            } else if post_residual >= next_item_size {
                // room for the lookahead item: reward
                score -= 6.0 + (post_residual - next_item_size) as f64 * 0.1;
            }
        }

        // Last-chance bonus: if this is the only bin that fits, strongly favor it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Prefer bins with residual below the mean (consolidate fuller bins)
        score += (mean_residual - bin_residual as f64) * 0.3;

        // Slight preference for fuller bins overall
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep
    score -= poly * 12.0 * (1.0 - norm_pr * norm_pr);

    // Penalize large dead space non-linearly
    score += norm_pr * norm_pr * norm_pr * 40.0;

    // Reward tight fits, scaled by stream maturity
    score -= (1.0 - norm_pr) * norm_item * (1.0 + 3.0 * t) * 10.0;

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 8.0 * t;
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr).max(0.0) / cap * 10.0;
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * t);
    }

    // Slight preference toward consolidating among many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Mean residual deviation coupling
    score += (mean_residual - pr).abs() * 0.05 * (1.0 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let post_frac = pr / cap; // fraction of capacity left after placement

    // Integer-division thresholds on post_residual: reward "harmonic" leftovers
    // that future items (multiples of 10, or arbitrary 1..100) can still use.
    let pr_u = post_residual;
    let harmonic = (pr_u / 25) as f64;          // coarse class: 0,1,2,3,4
    let fine = (pr_u % 25) as f64;              // fine remainder within class
    score -= 6.0 * harmonic;                    // bigger usable classes preferred
    score += 0.35 * fine;                       // but prefer clean class boundaries

    // Reward exact harmonic residuals (post_residual divisible by 10 / 20 / 25)
    if pr_u % 10 == 0 { score -= 4.0; }
    if pr_u % 20 == 0 { score -= 2.0; }
    if pr_u % 25 == 0 { score -= 2.0; }

    // Penalize dead zones: residuals too small for typical items (harmonic class 0)
    if pr_u < 10 {
        score += 30.0 * (10.0 - pr as f64);
    } else if pr_u < 25 {
        score += 8.0; // small awkward class
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly fills leftover
            if next_item_size == post_residual {
                score -= 25.0;
            } else {
                // reward by how "classy" the double leftover is
                let dbl = post_residual - next_item_size;
                score -= 10.0;
                if dbl % 10 == 0 { score -= 3.0; }
                score += 0.2 * (dbl % 10) as f64;
            }
        } else {
            // next item won't fit here; penalize less if residual still large
            score += 5.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowd control: many open bins -> prefer filling existing ones, discourage new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * (0.5 + 0.5 * progress);

    // New-bin candidate: judge by wasted capacity if item goes to a fresh bin
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64
            + 0.5 * open_f
            - 8.0 * harmonic;
        // prefer opening new bins early, prefer reusing bins late
        score += 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0; // new bin can also host the next item
        }
    }

    // Mean-residual coupling: if this bin is far above the mean residual, it is
    // a "loose" bin; slightly prefer bins near the mean (harmonic balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.35 * open_pressure;

    // New-bin candidate handling: only attractive when the fit is poor or nothing fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin by default.
        score += 30.0;
        // But if current item is large relative to residual, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
        // If existing bins are very full on average, a new bin is reasonable.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        // Early in stream, new bins are cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // Penalize placements that leave a gap just barely too small for the next item.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size + 10 {
        score += 6.0;
    }

    // Mild preference for tighter residual bins (best-fit flavor).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can still fit the next item: moderate reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0); // tightest fit gets the biggest bonus
    }
    // Dead space: post_residual > 0 but too small for the next item -> penalize.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Last chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins (reserve tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    } else {
        // Prefer fuller bins overall.
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead synergy: if the next item fits exactly/within post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item: penalize proportionally to how close it came.
        let miss = (next_item_size - post_residual) as f64;
        if miss <= 20.0 {
            score += 0.4 * miss;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when existing bins fit badly
    // (large post_residual relative to typical residuals) or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if fitting_bins_count > 0 {
            (post_residual as f64) // equals capacity - item_size for a fresh bin
        } else {
            0.0
        };
        // Penalize new bins mildly, less so late in the stream or when open bins are crowded.
        let crowding = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 25.0 - 10.0 * progress - 2.0 * crowding.max(0.0) + 0.05 * poor_fit;
    }

    // Prefer bins whose residual is below the mean (consolidate emptiness).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Slight preference for already-open bins as the stream matures.
    score += 0.5 * (step_index as f64 / (total_items.max(1) as f64)) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post_residual). Late: post_residual matters less,
    // and larger leftover space becomes more acceptable.
    let coupling = norm_post * (1.0 + 2.0 * progress) - 1.5 * norm_post * norm_post * (1.0 - progress);
    score += 40.0 * coupling;

    // Reward bins that leave room for the lookahead item (smooth quadratic fit term).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_quality = 1.0 - (gap / cap).powi(2);
        score -= 15.0 * fit_quality.max(0.0) * (1.0 - 0.5 * progress);
    }

    // Penalize dead space relative to mean residual (non-linear saturation).
    let excess = (post - mean_residual).max(0.0) / cap;
    score += 20.0 * excess * excess;

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "large" classes (still reusable) are favored; tiny dead-space classes penalized.
    let cap = bin_capacity as f64;

    // Dead-space penalty: residuals that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Modulo-class logic: residual divisible into common item sizes (10..80)
    // is more likely reusable.
    let r = post_residual;
    if r % 10 == 0 && r > 0 {
        score -= 12.0;
    }
    if r % 20 == 0 && r > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == r {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= r {
        // fraction of residual consumed by next item
        let frac = next_item_size as f64 / r.max(1) as f64;
        score -= 30.0 * frac;
        if r - next_item_size < 10 {
            score += 10.0; // creates new dead space
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when current bins
    // are already fragmented (high mean residual spread) or many bins are open.
    if bin_residual == bin_capacity {
        score += 40.0;
        if open_bins_count > 3 {
            score -= 15.0 * ((open_bins_count as f64 - 3.0).min(5.0));
        }
        if mean_residual > 30.0 {
            score -= 10.0;
        }
    }

    // Progress: later in the stream, prefer tighter packing (larger residuals
    // become less acceptable).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins whose residual deviates from mean residual toward smaller
    // (fill the emptiest-fitting bins first keeps many mid-size bins open).
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that can no longer fit
    // typical items (<= 10) are worthless; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // If the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual likely becomes dead space for the lookahead item.
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: with many open bins, prefer packing into existing bins;
    // with few open bins, opening a new one is cheap so don't force bad fits.
    let pressure = (open_bins_count as f64).ln().max(0.5);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins are open or current fit is bad.
        score -= 15.0 / pressure;
        if post_residual >= 10 {
            score -= 5.0;
        }
    } else {
        score += 3.0 / pressure;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps residual distribution balanced, reducing fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late in the stream, be more conservative: avoid creating unusable gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear urgency.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64).sqrt();

    // 2-step lookahead: reward post_residual that exactly matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // penalize gap between post_residual and next item size
            let gap = pr - nxt;
            score += gap * 0.5;
            // bonus if next item fits reasonably well (gap small)
            if gap <= 10.0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use the leftover: dead-space penalty
            score += (nxt - pr) * 0.8;
        }
    } else {
        // last item: minimize post_residual aggressively
        score -= 20.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (filling fuller bins first).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when current open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // early stream: opening fresh bins is cheap; late stream: prefer packing into existing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + 60.0 * (1.0 - progress) * fragmentation + fragmentation * 40.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item: fresh bin may serve it well
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Slight preference to keep number of open bins low when many are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly be filled by the next item.
    if next_item_size > 0 {
        if post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
            score += 12.0 + 0.35 * (post_residual as f64);
        } else if (post_residual as u64) >= (next_item_size as u64) {
            // Reward leaving room exactly compatible with the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + slack);
        }
    } else {
        // Last item: maximize fill, minimize leftover.
        score += 0.6 * (post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins below mean residual (consolidate emptiness elsewhere).
    score += 0.25 * ((bin_residual as f64) - mean_residual);

    // Time horizon: early in stream, tolerate opening new bins less;
    // late in stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    // Many open bins: discourage spreading; few open bins: allow new bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual);
    score += 0.15 * pressure * (post_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress + 0.4 * progress * norm_pr);

    // Penalize large dead space more than linearly
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (small post residual)
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty proportional to open bins to encourage consolidation
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Deviation from mean residual: prefer bins near mean to keep flexibility
    score += 0.05 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "awkward" classes get penalized (dead space), while classes that
    // commonly admit future items are rewarded.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;

    // Class boundaries via integer division on post_residual
    let class = post_residual / quarter; // 0..=4
    match class {
        0 => score -= 6.0,             // near-perfect fit, excellent
        1 => score -= 1.0,             // usable small gap
        2 => score += 2.0,             // awkward mid gap
        3 => score += 5.0,             // large dead space risk
        _ => {}                        // nearly empty bin
    }

    // Modulo coupling: does post_residual align with typical item sizes?
    // Sizes 10..80 cluster mod 10; residual divisible by 10 is easier to fill.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else {
        score += (post_residual % 10) as f64 * 0.15;
    }

    // Lookahead: check if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 4.0 * (1.0 - chain_waste as f64 / c);
        } else {
            // next item cannot use this bin's remainder: penalize proportionally
            score += 2.0 * (next_item_size as f64 / c);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // prefer tighter competition: the bin with least post residual wins anyway
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive early or when mean residual
    // is small (existing bins are fragmented)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = 1.0 - (mean_residual / c).clamp(0.0, 1.0);
        score = c * (0.6 + 0.4 * progress) - 10.0 * fragmentation;
        if fitting_bins_count <= 1 {
            score -= 5.0; // no good alternative: opening a new bin is fine
        }
    }

    // Mild preference for consolidating into few bins as stream progresses
    score += 0.05 * (open_bins_count as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        // Perfect fit reward.
        score -= 30.0;
    }

    // Penalize leaving gaps smaller than the minimum item size (1..100 unknown,
    // so use a soft threshold around small residuals).
    let gap_penalty = if post_residual < 20 { (20.0 - post_residual as f64) * 2.5 } else { 0.0 };
    score += gap_penalty;

    // Open-bin pressure: prefer compacting into fewer bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great fit
    // for the lookahead item.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && next_item_size <= item_size && item_size >= next_item_size {
            score -= 20.0;
        }
        // Late in stream, opening new bins is more costly.
        score += 30.0 * progress;
    }

    // Lookahead coupling: reward leaving just enough space for the next item.
    if next_item_size > 0 {
        let diff = post_residual as f64 - next_item_size as f64;
        if diff >= 0.0 && diff < 10.0 {
            score -= 12.0;
        }
    }

    // Mean residual alignment: prefer bins whose post residual tracks the mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for unusable dead space relative to mean residual.
    if (post_residual as f64) > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.4 * (mean_residual - post_residual as f64);
    }

    // 2-step lookahead: reward a post_residual that exactly (or nearly) matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can also fit here: reward tight two-item chaining
            score -= 2.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // dead space for the lookahead item: penalize proportionally
            score += 0.8 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty when many bins are already open (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    // Slight early-stream preference for keeping bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use:
    // residual below the minimum item size is pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.15 * (item_size as f64);
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when the fit into existing bins is poor or the item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we usually reuse open bins...
        score += 15.0;
        // ...but large items or very fragmented state justify opening a bin.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * frac * frac;
        if (mean_residual - item_size as f64) < 5.0 && open_bins_count > 0 {
            score -= 18.0;
        }
        // Early in the stream, opening bins is cheaper (future items can fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here; slight penalty proportional to leftover waste risk.
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer filling bins whose residual is far below the mean (consolidate fragmentation)
    // and penalize placing into bins that are already roomier than average.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 8.0 * dev;
    }

    // Mild pressure to use open bins as their count grows (limit bin sprawl).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress_poly);

    // Penalize dead space relative to next item (smooth interaction)
    let gap = norm_pr - norm_next;
    score += 8.0 * gap * gap * (1.0 - progress_poly);

    // Reward near-perfect fits with smooth falloff
    let fit_quality = 1.0 - norm_pr;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress_poly);
    }

    // Mild penalty for many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - norm_pr).abs();

    // Lookahead: favor bins whose post residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }

    // New-bin candidate: slight penalty so it's only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress_poly;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Penalize dead space by class: residuals in (0,10] are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= quarter / 2 {
        score += 25.0;
    } else if post_residual <= quarter {
        score += 8.0;
    } else if post_residual <= half {
        score -= 4.0;
    } else if post_residual <= three_quarter {
        score -= 10.0;
    } else {
        score -= 14.0;
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic coupling with lookahead: does post_residual mod next_item_size
    // leave a useful remainder class?
    if next_item_size > 0 && next_item_size <= post_residual {
        let rem = post_residual % next_item_size;
        let quot = post_residual / next_item_size;
        if rem == 0 {
            score -= 18.0; // next item tiles the residual perfectly
        } else if quot >= 1 && rem <= 10 {
            score += 12.0; // tiling leaves a dead sliver
        } else {
            score -= 6.0; // partial useful fit remains
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin; residual becomes stranded until later
        score += 10.0;
        // stranded residual in a bad harmonic class is worse
        if post_residual < quarter {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            0.0
        } else {
            1.0
        };
        // Base penalty for opening a new bin; relax late in the stream or
        // when many bins are open (fragmented state).
        let mut nb = 55.0 * pressure;
        nb -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
        nb += (open_bins_count as f64).min(20.0) * 1.5;
        // If mean residual is large, open bins are fragmented -> new bin ok.
        if mean_residual > half as f64 {
            nb -= 15.0;
        }
        // Small item into a fresh bin wastes capacity potential.
        if item_size <= quarter {
            nb += 20.0;
        } else if item_size >= three_quarter {
            nb -= 10.0;
        }
        score += nb;
    }

    // Mild preference for tighter existing bins (best-fit flavor).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // dead space relative to lookahead
    }

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 8.0 + open_bins_count as f64 * 0.5;
        if item_size > 60 {
            score -= 10.0; // big items prefer fresh bins
        }
    }

    // Mild progression-based tightening: prefer tight fits later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins tighter than the mean residual (good packing).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that exactly matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward proportional to how well the leftover matches the next item.
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64));
        // Exact match bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving more space than the next item needs beyond a slack margin.
        if post_residual > next_item_size {
            score += 0.35 * (post_residual - next_item_size) as f64;
        }
    } else {
        // Last item: pure waste minimization.
        score += 0.5 * post_residual as f64;
    }

    // Penalize dead space (tiny unusable leftovers).
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Mild pressure to close out bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New empty bin: penalize opening it unless it looks like the best long-term option.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted space quadratically, normalized by capacity.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Lookahead synergy: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward for tight packing with lookahead item.
        let tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * (1.0 - tight);
    } else if next_item_size > 0 {
        // Penalize creating dead space that the next item cannot use.
        score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer fuller bins relative to the mean residual across open bins.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        let mut new_bin_score = 100.0 + 8.0 * open_bins_count as f64;
        // Late in the stream, opening new bins is more costly.
        new_bin_score += 60.0 * progress;
        // But if the item is large, a fresh bin is attractive.
        new_bin_score -= 0.4 * item_size as f64;
        // If few bins fit the item, opening a new one is reasonable early on.
        if fitting_bins_count <= 1 {
            new_bin_score -= 30.0 * (1.0 - progress);
        }
        score = new_bin_score;
    } else {
        // Mild bonus for using existing bins as stream progresses.
        score -= 10.0 * progress;
    }

    // Discourage fragmenting bins into very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling: as the stream progresses, penalize large
    // residuals super-linearly (dead space becomes costlier later).
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap * 0.35;
    score += coupling;

    // Early stream: mildly favor spreading into open bins (sub-linear reward).
    score -= (1.0 - progress) * norm_pr * cap * 0.15;

    // Last-chance bin: strong bonus if this is the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = ((pr - nxt) / cap).powi(2);
            score -= 10.0 * (1.0 - slack) * (0.5 + 0.5 * progress);
        } else {
            // Residual too small for next item: penalize wasted space.
            score += 6.0 * (nxt - pr) / cap * (0.5 + 0.5 * progress);
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // with a smooth quadratic divergence term.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // Slight penalty for the brand-new empty bin candidate unless open bins
    // are nearly unusable (residuals far below item size).
    if bin_residual == bin_capacity {
        let usable = (mean_residual - item_size as f64).max(0.0) / cap;
        score += 14.0 - 30.0 * usable.min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction classes of the post residual (harmonic bins of dead space)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Reward near-perfect fits heavily
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    } else if post_residual <= 5 {
        score -= 150.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Harmonic class penalty: dead space in [1..cap/4] is valuable, beyond cap/2 is waste
    if frac > 0.5 {
        score += 80.0 * (frac - 0.5);
    } else if frac > 0.25 {
        score += 20.0 * (frac - 0.25);
    }

    // Modulo arithmetic on post_residual: multiples of small harmonics fit future items well
    let post_i = post_residual;
    if post_i > 0 {
        if post_i % 10 == 0 { score -= 25.0; }        // round decade residual
        else if post_i % 5 == 0 { score -= 10.0; }
        if post_i % 3 == 0 { score -= 5.0; }
        if post_i % 7 == 0 { score -= 4.0; }
        // Odd small residuals are hard to fill
        if post_i % 2 == 1 && post_i < 15 { score += 12.0; }
    }

    // Integer division thresholds: can next item land in the leftover?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt <= post_i {
            // next item fits here: reward, more if snug
            let slack = (post_i - nxt) as f64;
            score -= 40.0;
            if slack == 0 { score -= 300.0; }
            else if slack <= 5 { score -= 80.0; }
            else if slack <= 15 { score -= 20.0; }
            // penalize if residual class is odd/awkward for the item after next
            if (post_i - nxt) % 2 == 1 { score += 8.0; }
        } else {
            // next item cannot follow here: penalize proportional to overshoot class
            let over = (nxt - post_i) as f64;
            let over_class = if over <= 10.0 { 1.0 } else if over <= 25.0 { 2.0 } else if over <= 50.0 { 3.0 } else { 4.0 };
            score += 10.0 * over_class;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when open bins are congested or residuals are bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let congestion = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        score += 60.0; // base cost of opening a bin
        score -= 30.0 * (congestion / (1.0 + congestion));
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // large incoming items favor a fresh bin
        if next_item_size >= bin_capacity / 2 { score -= 25.0; }
    } else {
        // slight preference for tighter existing bins
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Prefer bins among many fitting candidates that leave harmonic residuals
    if fitting_bins_count > 1 && post_i % 10 == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if post_residual < 10 {
            score += 60.0 * (1.0 - dead); // tiny slivers are wasted space
        } else {
            score += 8.0 * dead * dead; // mild convex penalty on large leftovers
        }
    } else {
        // Perfect fit: huge reward.
        score -= 100.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * 0.4;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    // or the fit would create large dead space.
    if bin_residual == bin_capacity {
        score += 45.0;
        score += open_bins_count as f64 * 2.0;
        // Allow new bin if placing would leave a big awkward gap in existing bins.
        if post_residual == bin_capacity {
            score -= 10.0;
        }
    }

    // Open-bin pressure: when many bins are open, favor consolidation.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits the post residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 30.0;
        } else if slack_after_next < 10 {
            score += 15.0; // next item leaves a sliver — bad
        } else {
            score -= 5.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post residuals are fine, large ones are wasted.
    if post_residual as f64 > mean_residual * 0.5 {
        score += (post_residual as f64 - mean_residual * 0.5) * 0.6;
    }

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match for next item => strong reward.
        if gap == 0.0 {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: reward proportional to tightness.
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize by wasted potential.
            score += 0.35 * gap;
        }
        // Bonus if next item exactly fills this bin after this placement.
        if next_item_size == post_residual {
            score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
        }
    } else {
        // Last item: prefer filling bins as tightly as possible.
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // (high mean residual spread / few fitting options).
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 5.0; // opening a new bin is reasonable
        } else {
            score += 30.0; // prefer using existing bins
        }
    }

    // Mild preference for bins already tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - next_waste / (bin_capacity as f64));
        } else {
            // Next item cannot follow here; slight penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (gap / 100.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0 + 0.05 * (bin_residual as f64);
    }

    // Prefer fuller bins: compare bin residual to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in stream, be picky (penalize mediocre fits) to keep
    // flexibility; late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * tightness;
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // When many bins are open, encourage consolidation into existing bins;
    // when few bins are open, opening a new one is cheaper.
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 40.0; // item small relative to bin
        if bad_fit {
            score -= 8.0;
        } else {
            score += 15.0;
        }
    }

    // Perfect fit override.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space matters more (quadratic growth)
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 + 3.0 * progress);
    score += 20.0 * coupling;

    // Cubic interaction: penalize mid-range waste more sharply as stream advances
    score += 8.0 * pr_norm * pr_norm * pr_norm * (0.5 + progress);

    // Reward filling a bin nearly perfectly
    let fill = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill * fill;

    // Last-chance bin: strongly favor using it rather than opening a new one
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item can fit into the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - progress);
    }

    // Mild dispersion penalty: avoid stranding bins far below the mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * open_bins_count as f64;

    // New-bin candidate: make empty bins moderately attractive only when
    // current item is large relative to capacity or late in stream
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * (item_size as f64 / cap) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which eighth of the capacity it occupies
    let item_class = item_size / 13; // harmonic bucket 0..=7
    let post_class = post_residual / 13;

    // Reward tight fits: post_residual in low harmonic classes gets a discount
    let tight_bonus = match post_residual {
        0 => 60.0,
        1..=5 => 40.0,
        6..=12 => 22.0,
        13..=24 => 8.0,
        _ => 0.0,
    };
    score -= tight_bonus;

    // Penalize dead space that is too small for the smallest possible item (1)
    // but large enough to be wasteful: residual in "unusable" band
    if post_residual > 0 && post_residual < item_size {
        // dead space below the current item size is harder to fill
        score += (post_residual as f64) * 0.35;
    }

    // Modulo coupling: residual divisible nicely by common small sizes is valuable
    let r = post_residual;
    if r >= 2 {
        let divisibility = ((r % 10 == 0) as u32) as f64 * 6.0
            + ((r % 20 == 0) as u32) as f64 * 5.0
            + ((r % 25 == 0) as u32) as f64 * 4.0
            + ((r % 50 == 0) as u32) as f64 * 4.0;
        score -= divisibility;
    }

    // Lookahead: penalize if the next item cannot fit in post_residual
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.25;
        } else {
            // reward leaving room exactly sized for the next item
            let slack = post_residual - next_item_size;
            score -= 10.0 - (slack as f64).min(20.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // multiple options: prefer the bin whose residual class matches item class
        if post_class == item_class {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64).max(1.0) * 0.12;
        score += 55.0 + waste;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
        // but if no open bin fits at all, opening new bin is fine
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
    }

    // Mild preference for bins below mean residual (keeps balance)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals that are too small to hold a typical item
    // (items >= 1, but small gaps < ~10 are effectively unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10.0 - post) * 8.0;
    }

    // Reward tight fits (small positive post_residual) superlinearly.
    if post_residual >= 10 {
        score -= 40.0 * (1.0 - post / cap).powf(2.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement destroys room for the next item in this bin.
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow new bins more readily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * 6.0;
    score += pressure * (0.5 + 0.5 * (1.0 - progress));

    // New-bin candidate: neutral baseline; open only if no decent fit exists.
    if bin_residual == bin_capacity {
        score = 45.0 + mean_residual * 0.2 - pressure;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 20.0; // reserve fresh space for big items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize leaving
    // residuals that are too small to ever be useful.
    if post_residual > 0 {
        // Dead space penalty: residuals below the minimum item size (1) are
        // hopeless; residuals barely above common small sizes are risky.
        if post_residual < 10 {
            score += 25.0; // nearly unusable sliver
        } else if post_residual < 20 {
            score += 8.0;
        }
    } else {
        // Perfect fill is excellent.
        score -= 30.0;
    }

    // 2-step lookahead: reward if next_item_size fits exactly into the
    // post_residual (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect two-step chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
            if slack < 10.0 {
                score += 10.0; // leaves a sliver after the next item too
            }
        } else {
            // Next item cannot use this bin's leftover: leftover is dead
            // unless some other future use exists.
            score += 6.0;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 10.0;
    }

    // Relative to mean residual: bins with residual well above mean are
    // "roomy"; placing a small item there wastes potential. Prefer bins
    // whose residual is close to the item (tight packing) relative to fleet.
    let mean_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin fits well. Penalize opening a new
    // bin mildly, more so early in the stream when open bins are plentiful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        score += 12.0 + 0.1 * open_pressure * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Mild preference to keep many bins' residuals balanced (avoid many
    // half-empty bins): penalize bins far above mean residual after placement.
    if post_residual as f64 > mean_residual + 0.5 * bin_capacity as f64 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core with a mild tightening of the gap preference
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64) * 0.35;

    // Penalize residual space that is too small to be useful (dead space).
    // A residual is "dead" if it's smaller than the minimum plausible item size.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Placing the current item here would destroy room for the next one
            score += 5.0;
        }
        // Chain bonus: post-residual fits next item and leftover after that is small
        if post_residual >= next_item_size {
            let chain_left = post_residual - next_item_size;
            score -= 4.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when the
    // fit into open bins is poor. Penalize opening new bins generally.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 25.0;
        // But if the item is large and fits nowhere tightly, a new bin is fine
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 20.0;
        }
        // Late in the stream, opening new bins is more wasteful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins already: discourage fragmentation
        score += (open_bins_count as f64).sqrt() * 1.5;
    }

    // Global state coupling: prefer bins whose residual deviates from the mean
    // in a useful way (pack into bins that are already tight).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Prefer filling bins with larger residual imbalance when many bins are open
    if open_bins_count > 4 {
        score += 0.5 * (post_residual as f64 / bin_capacity as f64);
    }

    // Small structural tie-break: favor bins with residual close to a multiple
    // of common item sizes (10..80) to enable future perfect fits.
    if post_residual >= 10 && post_residual <= 80 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_n = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_n * pr_n * (1.0 - progress) + pr_n * (0.5 + 0.5 * progress);

    let mut score = pr + 12.0 * poly;

    // Penalize residual that is too small to be useful (dead space), smoothly
    let dead = ((20.0 - pr).max(0.0) / 20.0).powi(2);
    score += 15.0 * dead;

    // Reward near-perfect fits smoothly
    let tight = (1.0 - pr / cap).powi(3);
    score -= 20.0 * tight;

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 8.0 * fit_quality * (1.0 + progress);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: prefer opening new bin only when residuals are tight
    if bin_residual == bin_capacity {
        score = mean_residual * 0.5 + 30.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 buckets.
    // Leftovers in "friendly" classes (multiples of 10, and small residues 1-9
    // that many item sizes can still consume) are rewarded.
    let hclass = post_residual % 10;
    if post_residual > 0 {
        match hclass {
            0 => score -= 8.0,                       // perfectly reusable class
            1..=3 => score += 6.0,                   // nearly dead space
            4..=7 => score += 2.0,                   // mildly awkward
            _ => score -= 2.0,                       // 8/9 still fits mid-size items
        }
    }

    // Integer-division thresholds on post_residual: how many "small" items (<=10)
    // could still fit? Reward high divisibility of the leftover.
    let small_slots = post_residual / 10;
    score -= (small_slots as f64) * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0; // perfect chain
        } else if gap < 10 {
            score -= 10.0; // near-perfect chain
        } else {
            score -= (gap as f64).recip() * 5.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this leftover; penalize proportional to waste risk.
        score += (next_item_size - post_residual) as f64 * 0.05;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Empty new-bin candidate: only attractive when open bins are crowded or
    // the item is huge relative to residual pattern.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let crowding = open_bins_count as f64 / (mean_residual + 1.0);
        if item_size >= 50 || mean_residual < item_size as f64 {
            score -= 5.0 + 10.0 * progress;
        } else {
            score += 12.0 + crowding * 0.5;
        }
    }

    // Prefer bins whose residual is close to item_size (tight fit) beyond raw post_residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 5.0;

    // Mild preference to balance residual dispersion across bins.
    score += ((mean_residual - bin_residual as f64).abs()) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let min_gap = 10u32.min(item_size);
        if post_residual < min_gap {
            score += 60.0; // gap too small for any plausible item
        } else if post_residual <= 15 {
            score += 25.0; // near-dead zone
        } else if post_residual <= 25 {
            score += 8.0; // mildly awkward gap
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Reward using the bin exactly (perfect fit).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap just barely too small for the next item (dead space trap).
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 6.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + pressure + 30.0 * progress;
        // Allow a new bin only if mean residual across open bins is very low (they are nearly full).
        if mean_residual < 8.0 {
            score -= 25.0;
        }
    } else {
        // Slight preference for fuller bins among open candidates.
        score += 0.1 * (bin_capacity - bin_residual) as f64;
    }

    // Mild penalty scaled by how much of the bin remains wasted relative to mean.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - next).abs();
        if gap < 1.0 {
            score -= 40.0; // perfect 2-step chain: place here
        } else if post >= next {
            // next item fits exactly into leftover: mild reward scaled by tightness
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item will NOT fit in leftover -> leftover likely dead space
            score += 8.0 + 0.25 * post;
        }
        // bonus if this bin can chain both item and next item snugly
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 12.0;
        }
    } else {
        // last item: just minimize leftover
        score += 0.0;
    }

    // Penalize large dead space relative to mean residual of open bins
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless no open bin fits well
    if bin_residual == bin_capacity {
        let open_fit_penalty = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += 25.0 + open_fit_penalty + 0.1 * open_bins_count as f64;
        // allow new bin if the item would leave huge waste in every existing bin
        if fitting_bins_count > 0 && (bin_residual - item_size) as f64 > post_residual as f64 + 35.0 {
            score -= 60.0;
        }
    }

    // Tight fit reward: small post residual is good, nonlinear squash
    score -= 10.0 * (-post_residual as f64 / 10.0).exp();

    // Early stream: slightly prefer consolidation into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftover space.
    let pr = post_residual as f64;
    score -= 12.0 * (1.0 - pr / bin_capacity as f64).powi(6);

    // Penalize dead space that is too small for typical future items
    // (residual < 20 is nearly unusable).
    if post_residual < 20 {
        score += 25.0 * (20 - post_residual) as f64;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward for a two-item perfect chain.
            if bin_residual == item_size + next_item_size {
                score -= 15.0;
            }
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score += 4.0; // blocks the next item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins with smaller-than-average residual (consolidate).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for opening new bins early in the stream (more future
    // items to fill them), slight aversion late.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so it only wins when open bins fit badly.
        score += 18.0;
        // Early stream: new bins are cheaper to open.
        score -= 10.0 * (1.0 - t);
        // Very late stream: avoid leaving a nearly-empty new bin.
        score += 15.0 * t * t;
    }

    // Mild pressure against accumulating many open bins.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth non-linear coupling: penalize residual more strongly as stream progresses
    let coupling = 1.0 + 2.0 * progress * progress;
    score *= coupling;

    // Reward tight fits (small post_residual) with a saturating non-linear bonus
    let tightness = 1.0 - pr / cap;
    score -= 15.0 * tightness * tightness * tightness;

    // Penalize large dead space quadratically, scaled by stream progress
    let waste = pr / cap;
    score += 20.0 * progress * waste * waste * cap;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize mildly early, more later if open bins are fragmented
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
        if mean_residual > item_size as f64 {
            score += 4.0;
        }
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 5.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // Fragmentation pressure: many open bins with high mean residual -> prefer consolidation
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later
    // (below the minimum item size) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 18.0;
    } else if post_residual <= 35 {
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, big reward;
    // if it almost fits (within 10), mild reward; if it's far off, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.2 * (next_item_size as f64);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(40.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits: tie-break on residual waste.
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so it
    // is only chosen when no open bin fits decently.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening fresh bins is less attractive (waste).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 align with
    // common item sizes; reward them slightly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Residuals just below a multiple of 10 (e.g. 9, 19, 29) are awkward.
    if post_residual % 10 == 9 {
        score += 5.0;
    }

    // Prefer bins whose residual deviates from the mean residual in a way that
    // reduces fragmentation: filling below-average-residual bins tightens the pool.
    if (mean_residual - pr).abs() < 8.0 {
        score -= 3.0;
    }
    if pr > mean_residual + 25.0 {
        score += 5.0;
    }

    // Scale by overall tightness of fit relative to capacity.
    score *= 1.0 - 0.3 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item * 10.0 && post_residual > 0 {
        score += 40.0; // unusable sliver -> strong penalty
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= 0.6 * (item_size as f64) / (1.0 + post_residual as f64);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0; // gap remains usable for the next item
    }

    // New-bin candidate: only attractive when the item barely fits elsewhere
    // or open-bin pressure is low. Penalize opening bins otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 15.0 + 10.0 * pressure - 12.0 * progress;
        if fitting_bins_count <= 1 && bin_residual >= item_size {
            score -= 30.0; // last chance elsewhere -> new bin is fine
        }
        if post_residual as f64 > mean_residual {
            score -= 5.0; // fresh bin keeps more usable space than average
        }
    } else {
        // Existing bin: reward when it's the only fitting option (avoid waste).
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Mild preference for bins below mean residual (consolidating emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins late in the stream.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits; residual left after that matters.
            let chain_residual = post_residual - next_item_size;
            score -= 60.0;
            score -= (chain_residual as f64) * 0.3;
        } else {
            // Next item won't fit here: penalize proportionally to the gap,
            // but only if post_residual is small (dead space).
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 25 {
                score += gap * 1.5;
            } else {
                score += gap * 0.2;
            }
        }
    }

    // Compare against mean residual: placing in a bin far below mean residual
    // concentrates waste; prefer bins whose residual is near the mean.
    let res = post_residual as f64;
    let dev = res - mean_residual;
    if dev > 0.0 {
        score += dev * 0.4;
    } else {
        score += dev * 0.1;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Mild penalty for opening a new bin when many bins are open and residual
    // is full capacity (i.e., candidate is a fresh bin) unless item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (item_size as f64) / (bin_capacity as f64);
        // New bins are fine early or for large items; penalize otherwise.
        score += 80.0 * (1.0 - scarcity) * (0.5 + 0.5 * (1.0 - progress));
        // If item is large, opening a fresh bin is often best.
        if item_size >= 60 {
            score -= 120.0;
        }
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits strongly (non-linear squashing of post-residual).
    let tight = post / cap;
    score -= 12.0 * (1.0 - tight).powi(6);

    // Penalize dead space: residuals too small for typical items (1..100 unknown, mid ~30).
    if post > 0.0 && post < 20.0 {
        score += 18.0 * (20.0 - post) / 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual; penalize if it barely misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else if nxt - post <= 15.0 {
            score += 6.0 * (nxt - post) / 15.0;
        }
    }

    // New-bin candidate logic: only attractive when open bins are crowded or fit would be awful.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let fit_quality = (bin_residual - item_size) as f64 / cap; // best achievable fit elsewhere proxy
        let poor_fit_elsewhere = (post_residual as f64) > 0.45 * cap;
        if poor_fit_elsewhere && mean_residual < 0.35 * cap {
            score -= 20.0 + 10.0 * progress + crowded;
        } else {
            score += 30.0 + 15.0 * (1.0 - progress);
        }
        let _ = fit_quality;
    } else {
        // Mild preference for fuller bins among open bins.
        score -= 4.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Global balance: if mean residual is high, encourage consolidation into open bins.
    if mean_residual > 0.5 * cap && !is_new_bin {
        score -= 5.0 * (mean_residual / cap - 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    // Base: post residual, with smooth non-linear penalty on mid-range waste
    let mut score = pr;

    // Non-linear coupling: quadratic waste curve, penalizing residual near half-capacity
    let x = pr / cap;
    score += 12.0 * x * (1.0 - x) * (1.0 - progress);

    // Tight fit reward: cubic in fit fraction, stronger as stream progresses
    score -= 10.0 * fit * fit * fit * (0.5 + progress);

    // Lookahead coupling: reward bins whose post-residual can host next item (smooth)
    if next > 0.0 {
        let gap = pr - next;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap) * (1.0 - progress);
        } else {
            score += 2.0 * (-gap / cap) * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: smooth sigmoid-like pressure to use it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Crowd penalty: many open bins favor filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * fit * 2.0;

    // Deviation from mean residual: smooth quadratic divergence penalty
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize slightly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small residue" classes are desirable (tight packing).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward exact zero residual strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Integer-division thresholds: residue classes of 10
        let class = post_residual / 10; // 0..=9
        let within = (post_residual % 10) as f64;
        // Prefer classes that leave residues hard to fill (small leftovers)
        // Penalize large leftover less if it is a "usable" class (>= 50).
        match class {
            0 => score -= 60.0 + (10.0 - within) * 2.0, // near-perfect fill
            1 => score -= 25.0,
            2 => score -= 10.0,
            3 => score += 5.0,
            4 => score += 10.0,
            5 => score -= 5.0, // 50-59 residue is still quite usable
            6 => score += 0.0,
            7 => score += 5.0,
            8 => score += 10.0,
            _ => score += 15.0,
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic-class of the slack after the next item
            let slack_class = (post_residual - next_item_size) / 10;
            score -= 40.0 - slack_class as f64 * 4.0 + slack * 0.3;
        } else {
            // next item won't fit here: mild penalty if this bin would be wasted
            score += 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score so it is only
    // chosen when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 120.0;
        // late in stream, new bins are cheaper to open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 80.0 * progress;
    }

    // Prefer bins below mean residual (tighter bins) slightly.
    score -= (mean_residual - post) * 0.15;

    // Prefer reusing bins over proliferating open bins.
    score += open_bins_count as f64 * 0.5;

    // Modulo-based dead-space detector: residual not expressible as sum of
    // common item sizes (multiples of 5) is dead space.
    if post_residual % 5 != 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small to fit the smallest item (1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residuals that can still hold the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0; // leaves dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // unless the fit is very tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Slightly prefer bins with below-average residual (keep large residuals for future big items).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New empty bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (30.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
    }
    // Dead space: post_residual too small for the smallest plausible item (1..100 range).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }
    if next_item_size == 0 {
        // Last item: just minimize waste.
        score -= 15.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless residual is very large (poor fits elsewhere).
    if bin_residual == bin_capacity {
        score += 70.0;
        // Late in the stream, opening bins is relatively cheaper.
        score -= 30.0 * (step_index as f64 / total_items.max(1) as f64);
        // If item is large, a fresh bin is often the right call.
        score -= 0.2 * item_size as f64;
    }

    // Mild preference for tighter existing bins.
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, be more willing to open new bins;
    // late in the stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize large post-residual dead space, more strongly late in the stream.
    score += (post_residual as f64 / bin_capacity as f64) * (30.0 + 40.0 * progress);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize stranding: post-residual too small for the next item.
        score += 12.0 + 0.3 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // (avoids opening a new bin just for this item).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize bins far from the mean residual (keeps residual profile uniform,
    // making future packing easier).
    score += (bin_residual as f64 - mean_residual).abs() * 0.25;

    // When many bins are open, prefer filling existing ones over opening more.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral baseline, penalized relative to decent fits
    // but competitive when all open bins would strand dead space.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * (0.9 + 0.2 * progress) + 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If item is large relative to capacity, opening a fresh bin is attractive.
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with smooth quadratic saturation.
    let mut score = norm_pr * (1.0 + 1.7 * norm_pr) * cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early, keep bins flexible.
    let tightness = norm_pr * norm_pr;
    score += (0.6 + 2.4 * progress) * tightness * cap;

    // Lookahead: reward residual that still fits the next item, smoothly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= (1.0 - progress) * (2.2 - 1.6 * slack) * 12.0;
    } else if next_item_size > post_residual {
        score += 3.0 + 4.0 * progress;
    }

    // Last-chance bin: strong smooth bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 14.0 * (1.0 - 0.5 * norm_pr);
    }

    // Penalize bins far from the mean residual (keeps bin pool homogeneous),
    // scaled smoothly by number of open bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * (1.0 + (open_bins_count as f64).ln().max(0.0)) * 2.0;

    // New-bin candidate: penalize unless it is genuinely better than a bad fit.
    if bin_residual == bin_capacity {
        score = cap * (1.6 + 1.1 * progress) + 0.35 * item_size as f64;
        if fitting_bins_count == 1 && post_residual <= 30 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors capture
    // "dead space" classes that future items (1..100) rarely fill exactly.
    let r = post_residual;
    if r == 0 {
        // Perfect fill: strongly reward.
        score -= 1000.0;
    } else {
        // Penalize unusable tiny slivers (< 10, or smaller than any plausible item).
        if r < 10 {
            score += 40.0;
        }
        // Harmonic classification: residues divisible by 10 are "good" classes
        // (many item sizes can combine to fill them).
        let good_class = (r % 10 == 0) as f64;
        score -= 12.0 * good_class;

        // Modulo-5 secondary class: semi-fillable residues.
        if r % 5 == 0 && r % 10 != 0 {
            score -= 5.0;
        }

        // Integer-division thresholds: very large residuals are wasteful to
        // "waste" on a small item unless nothing else fits.
        let big_waste = (r / 25) as f64; // 0..=4 buckets
        score += 2.5 * big_waste * (1.0 - good_class);

        // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
        if next_item_size > 0 {
            if next_item_size == r {
                score -= 300.0;
            } else if next_item_size <= r {
                // Next item fits but not exactly: mild reward scaled by fit quality.
                let fill = next_item_size as f64 / r as f64;
                score -= 20.0 * fill;
            } else {
                // Next item cannot use this residual: penalize proportional to slack class.
                let gap = (next_item_size - r) as f64;
                score += 0.15 * gap.min(50.0);
            }
        }

        // Last-chance bin: if this is the only bin that fits, avoid opening a new
        // bin unless the fit is truly terrible.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 25.0;
        }

        // New-bin candidate: penalize opening a new bin unless current residual is
        // in a bad harmonic class and large.
        if bin_residual == bin_capacity {
            let pressure = open_bins_count as f64;
            let bad_fit = if r == bin_capacity { 0.0 } else { 1.0 };
            score += 60.0 - 10.0 * pressure.min(6.0) * bad_fit;
            // Opening a new bin is fine early in the stream.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 30.0 * (1.0 - progress);
        }

        // Mean-residual coupling: prefer bins whose residual differs from the mean
        // in the "good" direction (below mean => tighter packing).
        score += 0.3 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else {
        // Larger usable residuals are mildly rewarded (subtract).
        score -= (post_residual as f64 - 30.0).min(20.0) * 0.2;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0; // chained perfect fit
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer packing into existing bins,
    // disfavor opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += pressure * 2.0;
    } else {
        score -= pressure * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin — using it consolidates space.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: waste-free placement is always excellent.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into the post-residual,
    // this placement is a chain of two perfect fits — heavily reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits, leaving a small new residual: mild reward,
            // stronger the tighter the secondary fit.
            let sec_res = post_residual - next_item_size;
            score -= 200.0 * (1.0 - sec_res as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize proportionally
            // to how much dead space we would strand.
            let waste = post_residual as f64;
            score += 0.5 * waste * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Penalize residuals that are too small to ever fit a typical item
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
    }

    // Relative-to-mean coupling: bins with residual far below the mean
    // are nearly full; placing there is good consolidation.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item
    // is large and no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 120.0 - 100.0 * tightness;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 80.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in the stream, keeping bins consolidated matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Slight preference to fill fuller bins first (smaller post_residual
    // already does this; add a mild non-linear term).
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is the raw waste; scale it by how much
    // of the bin was consumed by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 0.6 * fill_frac * (bin_residual as f64);

    // Penalize leaving dead space that can only fit small items:
    // if post_residual < 10, it's perfect packing (bonus).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score += 5.0; // awkward leftover
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 0.4 * next_item_size as f64;
        } else {
            // next item won't fit here; slight penalty if this bin was the
            // only fitting bin (last-chance usage still preferred over new bin)
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global state: prefer filling bins when many bins are open (consolidation).
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score -= 0.3 * pressure * fill_frac;

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., a fuller bin) is good; near-mean bins are less attractive.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, prioritize closing out bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 0.1 * post_residual as f64;
    score -= t * 5.0 * fill_frac;

    // New-bin candidate handling: an empty bin is a fallback; make it
    // unattractive unless the item is large or no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let item_relief = 0.5 * item_size as f64;      // big items justify new bins
        let scarcity_relief = if fitting_bins_count == 0 { 100.0 } else { 0.0 };
        score += base_penalty - item_relief + scarcity_relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Coupling of post-residual with stream progress: later in stream,
    // dead space becomes more costly (quadratic in progress)
    score += 8.0 * pr * progress * progress;

    // Reward tight fits: post-residual near zero gets extra discount
    score -= 6.0 * (1.0 - norm_pr).exp() * norm_item;

    // Penalize post-residual that cannot fit the next item (smooth hinge)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 5.0 * gap * gap * (1.0 + progress);
        // Reward if post-residual still accommodates next item
        let fits_next = ((pr - norm_next * cap).max(0.0)) / cap;
        score -= 2.0 * (1.0 - fits_next) * norm_next;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty when bin's residual is far above mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (0.5 + progress);

    // Slight preference for consolidating into fewer bins early
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by small item sizes
    // (10..=20) are "usable" dead space; odd prime-ish residues are dead.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        if pr % 10 == 0 { harmonic_bonus -= 12.0; }
        else if pr % 5 == 0 { harmonic_bonus -= 6.0; }
        else if pr % 2 == 0 { harmonic_bonus -= 2.0; }
        else { harmonic_bonus += 4.0; } // odd residue: likely dead space
        score += harmonic_bonus;

        // Perfect-fit harmonic: post_residual in the small-item class
        if pr >= 10 && pr <= 20 {
            score -= 10.0;
        }
        // Dead zone: tiny unusable slivers
        if pr < 10 {
            score += 8.0;
        }
    } else {
        // Perfect closure of the bin — strongly reward
        score -= 25.0;
    }

    // Lookahead coupling: does next_item_size land in the same harmonic class?
    if next_item_size > 0 && next_item_size <= pr {
        let class_match = (pr % 10 == next_item_size % 10) || (pr % 20 == next_item_size % 20);
        if class_match {
            score -= 9.0;
        } else {
            score -= 3.0;
        }
        // Exact next-item fit
        if pr == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: penalize opening a new bin when only this bin fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // New-bin candidate handling: empty bin gets a mild standing penalty so
    // it only wins when open bins are truly bad (large post_residual or dead zone).
    if bin_residual == bin_capacity {
        score += 18.0;
        // If item is large relative to capacity, opening fresh is fine
        if item_size * 5 >= bin_capacity * 3 {
            score -= 10.0;
        }
    }

    // Waste fraction penalty: quadratic in leftover fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 20.0;

    // Late in the stream: consolidate, prefer tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64 * -0.05);

    // Spread across many open bins is bad: reward using bins with low residual
    score += (mean_residual - post_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (size 1..=10 can still be used, but very small gaps are wasteful).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0; // barely usable gap
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 0.8;

    // Lookahead: if the next item can use the post_residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Prefer bins below mean residual (keep residuals balanced).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 0.5;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space non-linearly: small residuals are hard to reuse.
        let small_dead = (post_residual as f64) / bin_capacity as f64;
        if post_residual < 10 {
            score += 60.0 * (1.0 - small_dead * 10.0);
        }
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Slack left for next item: mild reward proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 40.0 - (after_next as f64) * 0.5;
        } else {
            // Next item cannot follow: penalize proportionally to the gap.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare against mean residual: bins tighter than average are worth filling.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.3;
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 120.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Late-stream pressure: consolidate more aggressively as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item cannot use the leftover: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Slight penalty so an existing decent fit beats a new bin, but a fresh bin
        // is attractive when open bins are fragmented (high mean residual spread).
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 60.0 + fragmentation * 0.5 - (open_bins_count as f64) * 0.3;
        if fitting_bins_count == 1 {
            score += 40.0; // strongly discourage abandoning the sole fitting bin
        }
    }

    // Global state: when many bins are open with large mean residual, prefer consolidating
    // into bins with residuals close to the mean (balance the pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Time horizon: early in the stream, be more conservative (favor tight packing);
    // late in the stream, just close out bins efficiently.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    // Mild penalty for very large items in nearly-full bins to preserve exact-fit options.
    if item_size > 60 && bin_residual - item_size > 0 && bin_residual - item_size < item_size / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (prn * prn) * (1.0 - progress) - (prn * prn * prn) * progress;
    score += 20.0 * poly;

    // Reward tight fits, more strongly late in the stream
    let tightness = 1.0 - prn;
    score -= 15.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (pr < next_item_size as f64) {
        score += 8.0 * (1.0 - pr / next_item_size.max(1) as f64) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // small reward if next item fits exactly in the post-residual
        let gap = (pr - next_item_size as f64) / cap;
        score -= 5.0 * (1.0 - gap * gap);
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - prn);
    }

    // Mild pressure from many open bins vs mean residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (prn - mean_residual / cap).abs();

    // New-bin candidate handling: make empty bins less attractive unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Class 0: perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Integer-division thresholds on post_residual: classes of leftover size.
        let cls = post_residual / 10; // harmonic class width 10
        score += cls as f64 * 8.0;    // larger class -> larger penalty
        // Penalize "awkward" residuals: those below the minimum item size (1) are fine,
        // but residuals in (0,10) can trap small items only; modulate by modulo class.
        let m = post_residual % 10;
        score += m as f64 * 0.15;
        // Dead-space penalty grows super-linearly if residual can't fit typical items.
        if post_residual < 10 {
            score += 40.0; // nearly unusable dead space
        }
    }

    // Reward bins whose residual tightly matches the item (small post_residual fraction).
    score += post_frac * post_frac * 120.0;

    // Lookahead coupling: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item packs into leftover.
            score -= 40.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit: leftover becomes dead unless tiny.
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Neutral base for new bin; slight penalty so decent fits win, but
        // subtract when many open bins already exist with fragmented residuals.
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing fits elsewhere: open a new bin
        }
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 30.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual (balance control).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight preference for bins with larger current residual when item is large
    // (large items need room; avoid wasting scarce small residuals on big items).
    if item_size > bin_capacity / 2 {
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (smaller than the minimum plausible item, here < 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // heavy penalty for creating tiny dead space
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Penalize leaving room that exactly blocks a common next fit,
    // reward leaving room that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // lookahead still fits here: good chaining
        } else if post_residual > 0 {
            score += 6.0; // lookahead cannot use the leftover: worse dead space
        }
    }

    // Open-bin pressure: when many bins are open, strongly prefer filling
    // existing bins over spreading; new-bin candidate (residual == capacity)
    // gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 20.0 + 6.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean (the "fuller" bins):
    // consolidates waste into few bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else if (bin_residual as f64) > mean_residual + 1.0 {
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Early in the stream, tolerate opening bins more freely; late in the
    // stream, squeeze everything into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space).
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 15.0;
    }

    // Penalize creating small unusable gaps that no future item (>=1..) can use well.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += (10.0 - gap) * 3.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            let nxt_gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - nxt_gap / bin_capacity as f64);
        } else {
            // next item cannot follow here: mild penalty for wasting space
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Tightness: prefer filling bins that are already mostly full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Prefer bins whose residual is close to the item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * snug;

    // Global state: many open bins -> consolidate; few open bins -> allow spreading.
    if open_bins_count > 4 {
        score -= 2.0 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    } else {
        score += 3.0;
    }

    // Time horizon: late in the stream, be conservative and avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when residuals are fragmented or item is big.
        score += 60.0 - 40.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 30.0; // open bins can't hold much anyway
        }
        if item_size > 60 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, tighter fits matter more
    score += 20.0 * progress * norm_pr * norm_pr;

    // Reward when post residual could host the next item (smooth interaction)
    let fit_next = if norm_next > 0.0 { (norm_pr - norm_next).abs() } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (-2.0 * fit_next * fit_next).exp();

    // Penalize dead space that nothing (min size 1%) can use, smoothly
    score += 5.0 * norm_pr * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual deviates from mean residual (balance pressure)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs() / cap;

    // Slight preference for keeping few open bins early, more consolidation later
    score += 0.5 * (1.0 - progress) * (open_bins_count as f64) / (open_bins_count as f64 + 5.0);

    // New-bin candidate: penalize slightly unless residuals of open bins are all poor
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
        // If next item is large and current item nearly fills bin, opening new bin is fine
        if norm_next > 0.5 && norm_item > 0.5 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the post residual: residues that are "friendly"
    // (divisible by small item sizes) are less wasteful than prime-like ones.
    let pr = post_residual;
    let mut friendliness = 0.0;
    for d in [10u32, 20, 25, 50, 5] {
        if pr % d == 0 {
            friendliness += 1.0;
        }
    }
    // Friendly residuals leave reusable space: reward.
    score -= 6.0 * friendliness;

    // Dead-space penalty: residual too small for the smallest plausible item.
    if pr < 10 {
        score += 60.0 * (10 - pr) as f64;
    }

    // Coupling with lookahead: if the next item fits exactly into post_residual,
    // this bin is a great chain candidate.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // next item cannot fit here; penalize proportionally to wasted potential
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Harmonic check: does post_residual divide into chunks matching next item?
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base bias toward reusing open bins.
        score += 25.0;
        // But if the current item is huge and open bins are fragmented, allow new bin.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > 50 && mean_residual < item_size as f64 * 0.8 {
            score -= 45.0;
        }
        if open_bins_count == 0 {
            score -= 500.0;
        }
        let _ = progress;
    }

    // Mild preference for bins tighter than the mean (better packing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (low post residual) more aggressively than linear.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
    } else {
        // Slight reward for using existing bins, stronger when few fitting bins.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
        score -= 25.0;
    } else if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) < 0 && (post_residual as i64 - next_item_size as i64) > -10 {
        score += 5.0; // next item almost fits: mild penalty for blocking
    }

    // Late in stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    // Prefer bins with residuals close to mean (balance spread) mildly.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a tight fit (small post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            // Perfect chaining: post_residual == next_item_size leaves a zero-dead-space chain.
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize proportionally to the wasted chain opportunity.
            score += 6.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
        // Reward post_residual large enough to keep future flexibility above mean residual.
        if post_residual as f64 >= mean_residual {
            score -= 3.0;
        } else {
            score += 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Still allow a fresh bin if lookahead chaining from a full bin is perfect.
        if next_item_size > 0 && (bin_capacity - item_size) as f64 == next_item_size as f64 {
            score -= 30.0;
        }
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // Penalize dead space: very small post_residual that can't fit anything is bad,
    // but so is large waste. Penalize residuals that are unusable (< 10 or awkward)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // nearly-full bin is fine actually; small penalty only
    }
    if post_residual >= 10 && post_residual <= 15 {
        score += 10.0; // awkward dead zone
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // mild penalty when many alternatives exist to prefer best fit
        score += fitting_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            score += 4.0; // placing here would force next item elsewhere
        }
        // chain fit: next item exactly fills post residual
        if next_item_size == post_residual {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin gets a penalty unless current fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_quality = if mean_residual > 0.0 {
            (mean_residual - item_size as f64).abs()
        } else { 0.0 };
        // open new bin when open bins have poor residual alignment, more so early
        score += 20.0 - progress * 8.0 - avg_fit_quality * 0.15;
        if open_bins_count == 0 {
            score -= 100.0; // must use it
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidating
    let spread = mean_residual - bin_residual as f64;
    score += spread * 0.08;

    // Time horizon: late in stream, be more conservative, favor filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post_residual, with non-linear sharpening
    let mut score = post + 40.0 * (post / cap).powi(2);

    // Tight-fit reward: smooth quadratic in item fraction, stronger late in stream
    let fit_frac = item / cap;
    let tightness = (1.0 - fit_frac) * fit_frac; // peaks at medium items
    score -= 25.0 * tightness * (0.5 + progress);

    // Exact-ish fill bonus (post_residual near zero), non-linearly scaled
    score -= 30.0 * (-post / 12.0).exp();

    // Penalize large post_residual more as stream progresses (waste compounds)
    score += 30.0 * (post / cap).powi(3) * progress;

    // Lookahead: reward leaving room for next item, penalize stranding it
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - (post - nxt) / cap).max(0.0);
        } else {
            score += 15.0 * (nxt - post) / cap;
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: mildly penalize early, allow when open bins are crowded
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
        score -= 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mild penalty when this bin is far above mean residual (imbalance)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic residue classes: leftover space in the lowest residue class
    // (post_residual <= 10) is nearly perfect — reward strongly.
    if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Dead-space analysis with lookahead (k=2):
    // if the next item cannot fit in the leftover, this leftover is likely wasted.
    if next_item_size > 0 {
        if (next_item_size as f64) > post {
            // leftover unusable by next item: penalize proportionally
            score += 0.5 * post;
        } else {
            // leftover reusable: reward chain compatibility
            score -= 5.0;
            // extra bonus if next item almost exactly fills the remainder
            let gap = post - next_item_size as f64;
            if gap <= 5.0 {
                score -= 10.0;
            }
        }
    }

    // New-bin candidate handling (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        let mut new_bin_penalty = 35.0;
        // if several bins fit the item, opening a new one is wasteful
        if fitting_bins_count > 1 {
            new_bin_penalty += 10.0 * (fitting_bins_count as f64).ln();
        }
        // early in the stream, opening bins is cheap (builds flexibility)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty -= 20.0 * (1.0 - progress);
        // if item is large, the new bin's post_residual is small -> better
        new_bin_penalty -= 0.2 * (item_size as f64);
        score += new_bin_penalty;
    } else {
        // Last-chance bonus: this is the only bin that fits the item
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // coupling with mean residual: prefer bins whose leftover deviates
        // favorably (below average) to keep the bin population homogeneous
        score += 0.1 * (mean_residual - post).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals that cannot fit the lookahead item (likely dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward a fit that also accommodates the next item (chained packing).
        score -= 10.0;
    }

    // Reward tight fits (small waste relative to item size).
    score -= 15.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, discourage new-bin creation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates below the mean (consolidate space).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover <= 10 {
            score -= 30.0 - leftover as f64 * 2.0;
        } else {
            score -= 8.0;
        }
    }
    // Next item cannot fit here -> mild penalty for wasting the gap.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Reward tight fits relative to current item (small post_residual is good).
    if post_residual <= 10 {
        score -= 20.0;
    }

    // Compare against mean residual: bins with below-average residual are
    // "almost full" -> prefer filling them to close them out.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely
    // needed (no good fit exists / many large items ahead).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 45.0;
        // If the item would leave a large unusable gap in existing bins, a
        // fresh bin becomes more attractive.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            new_bin_score -= 10.0;
        }
        // Early in the stream with few bins, opening a new bin is cheap.
        new_bin_score -= (1.0 - progress) * 10.0;
        // Many open bins with high mean residual: better to use one of them.
        new_bin_score += (open_bins_count as f64) * 1.5 + mean_residual * 0.2;
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid leaving
    // tiny unusable slivers (< 10) that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty for slivers
    } else if post_residual == 0 {
        score -= 30.0; // perfect closure bonus
    }

    // Relative fit quality: reward item filling a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - next_fit / bin_capacity as f64);
        } else {
            score += 6.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be pickier, penalize loose fits more.
        score += 3.0 * (1.0 - fill_ratio);
    }

    // New-bin candidate logic: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: proportional to wasted capacity of existing bins.
        let avg_waste = mean_residual;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = bin_capacity as f64 - 25.0 * fill_ratio;
        // Early on, opening bins is cheap (bins get filled later); late, prefer packing.
        new_bin_score += 20.0 * progress;
        // If existing bins have lots of room and few bins fit, discourage new bin.
        if avg_waste > item_size as f64 && fitting_bins_count >= 1 {
            new_bin_score += 10.0;
        }
        // A new bin is attractive if the item is large and wouldn't leave a sliver.
        if post_residual <= 20 {
            new_bin_score -= 15.0;
        }
        score = new_bin_score;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual deviates below the mean (more "committed" bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, shaped non-linearly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial coupling: large residuals become more tolerable late in stream
    score -= 60.0 * x * x * progress;
    score += 40.0 * x * x * x * (1.0 - progress);

    // Penalize near-wasted residuals (small but unusable dead space)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 50.0 * gap * gap;
        // Reward exact-ish fit for lookahead item
        let slack = (pr - next_item_size as f64).abs() / cap;
        score -= 25.0 * (1.0 - slack) * (1.0 - slack) * (1.0 - progress);
    } else {
        score -= 20.0 * x * x;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Pull toward mean residual to keep bins balanced
    score += 0.3 * (mean_residual - pr).abs();

    // Mild penalty for opening many bins
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover divisible into small
    // "harmonic" chunks is more reusable than awkward remainders.
    let pr = post_residual;
    if pr > 0 {
        // Perfect fit reward.
        if pr == 0 {
            score -= 1000.0;
        }
        // Harmonic classes of post_residual modulo capacity fractions.
        let cap_frac = bin_capacity as f64;
        let prf = pr as f64;
        // Class 0: tiny dead space (<= 10) is nearly wasted -> penalize hard.
        if pr <= 10 {
            score += 60.0;
        }
        // Class 1: leftover that can host the next item is golden.
        if next_item_size > 0 && pr >= next_item_size {
            score -= 40.0 + 0.5 * (next_item_size as f64);
        }
        // Class 2: modulo arithmetic on residual — leftovers divisible by
        // common small item sizes (mod classes) are reusable.
        let harmonic_bonus = (pr % 10 == 0) as i32 as f64 * 25.0
            + (pr % 5 == 0) as i32 as f64 * 10.0
            + (pr % 25 == 0) as i32 as f64 * 15.0;
        score -= harmonic_bonus;
        // Class 3: awkward primes / large odd remainders -> penalize.
        if pr > 30 && pr % 2 == 1 && pr % 5 != 0 {
            score += 12.0;
        }
        // Fractional capacity coupling: prefer bins whose fill ratio lands
        // on coarse integer-division thresholds (1/4, 1/2, 3/4 full).
        let filled = (bin_capacity - pr) as f64;
        let quarter = bin_capacity / 4;
        if filled as u32 % quarter == 0 {
            score -= 8.0;
        }
        // Scale residual by capacity fraction for cross-capacity sanity.
        score += prf * (1.0 + 0.25 * (prf / cap_frac));
    } else {
        // Perfect fit: strong reward.
        score -= 500.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation elsewhere.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: only attractive when residuals are fragmented or
    // the item barely fits nowhere well.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let tight_fit = next_item_size > 0 && next_item_size >= bin_residual && bin_residual < bin_capacity;
        let _ = tight_fit;
        // Open new bin when open bins are mostly full or stream is early
        // and we can afford spreading.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_bias = if open_bins_count == 0 { -200.0 } else {
            (fragmentation * 90.0) + (1.0 - progress) * 10.0 - open_bins_count as f64 * 4.0
        };
        score += 120.0 + open_bias;
        // Never open a new bin if post_residual would be a perfect fit for next item.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 30.0;
        }
    }

    // Lookahead pairing: if next item exactly complements this bin's residual,
    // big reward (harmonic pair).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 70.0;
    }
    // Next item nearly fits (within harmonic tolerance of 5).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 5 {
        score -= 20.0;
    }

    // Mild preference for fuller bins overall (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly worthless.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as i32) as f64 * 8.0; // up to +80 for 1-unit gaps
    }
    if post_residual > 10 && post_residual <= 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual in the "usable" zone).
    if post_residual == 0 {
        score -= 60.0; // perfect fill is ideal
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this bin's leftover -> leftover is truly dead
        score += post_residual as f64 * 0.3;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage new bins, encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += open_bins_count as f64 * 4.0 + progress * 30.0;
        // Only attractive if the item nearly fills a fresh bin.
        if item_size >= 90 {
            score -= 70.0;
        }
    } else {
        // Consolidation bonus for using existing bins.
        score -= 3.0 + open_bins_count as f64 * 0.5;
        // Prefer bins with residual above mean (keeps a spread of usable gaps).
        if (bin_residual as f64) < mean_residual {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 30.0;
        } else if slack <= 10.0 {
            score -= 15.0 - slack * 0.8;
        } else {
            score -= (10.0 / slack).min(5.0);
        }
    }

    // Penalize dead space: post_residual too small for any future item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.5;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // item leaves space the lookahead item cannot use
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer bins tighter than the mean (good fits), discourage loose bins.
    score -= (mean_residual - bin_residual as f64) * 0.25;

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    // Early stream: be slightly greedy to keep bins tight; late stream: consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else {
        // Penalize dead space quadratically for large leftovers.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post-residual, this is a great chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more waste: mild penalty proportional to leftover after next.
            let after_next = post_residual - next_item_size;
            score += (after_next as f64) * 0.3;
        } else {
            // Next item won't fit here: slightly favor bins whose residual is small anyway.
            score += 2.0;
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score -= 8.0; // only one fitting bin: opening is competitive
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 12.0;
        // If mean residual of open bins is large, prefer packing into them.
        score += mean_residual * 0.15;
    }

    // Prefer denser bins slightly (bins closer to full) to consolidate waste.
    let fullness = (bin_capacity.saturating_sub(bin_residual)) as f64 / bin_capacity as f64;
    score -= fullness * 3.0;

    // Late in the stream, avoid opening new bins even harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Base: reward filling the bin (smaller post_residual => lower score),
    // with a smooth quadratic penalty for extreme smallness (dead space) later in stream.
    let pr_norm = pr / cap;
    let mut score = pr_norm - 0.6 * pr_norm * (1.0 - pr_norm);

    // Non-linear coupling with stream progress: as stream advances,
    // tighter fills matter more (quadratic ramp on progress).
    score += (1.0 - pr_norm) * (1.0 - pr_norm) * (0.4 + 0.8 * progress * progress) * -1.0;

    // Lookahead synergy: if the next item fits into post_residual, reward strongly (smooth gate).
    if next_item_size > 0 {
        let fits = (pr - next_item_size as f64) / cap;
        if fits >= 0.0 {
            score -= 0.35 * (1.0 - fits) * (1.0 + progress);
        } else {
            // penalize residuals that likely become dead space, scaled by how unusable
            score += 0.15 * (-fits).sqrt() * (0.5 + progress);
        }
    }

    // Last-chance bonus: only one bin fits the item -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else if fitting_bins_count > 1 {
        // mild penalty for competing bins, encouraging tightest fit selection
        score += 0.02 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it's only
    // chosen when open bins have poor fits (their scores will be high).
    if bin_residual == bin_capacity {
        score += 0.9 + 0.3 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual coupling: penalize bins far above mean residual (relatively emptier),
    // smooth quadratic deviation.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.1 * dev * dev;

    // Small global tie-breaker favoring bins with less residual at high progress.
    score += 0.05 * pr_norm * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are "clean"
    // because typical item sizes (1..100) often align to decade classes.
    let class = post_residual % 10;
    if class == 0 {
        score -= 4.0; // clean residual, highly reusable
    } else if class <= 3 {
        score += 2.0; // awkward sliver, likely dead space
    } else if class >= 7 {
        score += 1.0; // near-decade but not aligned
    }

    // Dead-space penalty: residual too small for the smallest possible item.
    if post_residual < 1 {
        score += 50.0;
    } else if post_residual < 5 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or
    // within its own harmonic class, reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 6.0;
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 3.0; // chain fit leaves clean residual again
            }
        } else {
            // next item cannot use this bin's remainder: slight penalty
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins would leave ugly residuals. Base cost for opening a new bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If existing residuals are all poor (high mean fragmentation),
        // opening a new bin becomes more attractive.
        let frag = mean_residual / bin_capacity as f64;
        if frag > 0.35 {
            score -= frag * 20.0;
        }
        // Early in the stream, having many bins open is fine; late in the
        // stream, avoid opening extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer tighter fits overall: scale by fraction of capacity consumed.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 5.0;

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for the
    // smallest plausible item (or the lookahead item) are "dead space".
    let min_useful = next_item_size.max(1) as f64;
    if post_residual > 0 && (post_residual as f64) < min_useful {
        score += 40.0; // unusable sliver
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // below typical minimum item size
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item exactly fills the post-residual, strongly favor.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so add a penalty
    // proportional to open_bins_count for it (its tightness bonus is minimal).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.5 * open_bins_count as f64;
        // But if nothing fits well elsewhere (many bins, high mean residual spread),
        // opening fresh can still win via the base post_residual comparison.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder (avoid new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is a
    // fragmented bin — using it consolidates waste; slightly favor it.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits (low post_residual).
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 6 {
        score -= 30.0;
    }

    // 2-step lookahead: if next item fits into the post-residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 + 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement: penalize, scaled by how close it is.
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 + miss.min(40.0) * 0.5;
    }

    // Compare post_residual against mean residual: avoid creating below-average unusable gaps.
    let cap = bin_capacity as f64;
    let dead = (post_residual as f64) / cap;
    if dead > 0.0 && dead < 0.10 {
        score += 20.0; // tiny unusable sliver
    }

    // Penalize deviation from mean residual to balance bin pool.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor or no real alternative.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 30 || (next_item_size > 0 && next_item_size > post_residual);
        if poor_fit && fitting_bins_count > 1 {
            score -= 15.0;
        } else {
            score += 50.0; // discourage opening new bins by default
        }
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - dead);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scaled waste penalty (quadratic in dead space).
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Lookahead: if the next item fits in the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if next item leaves a small residual too (chained packing).
        let chained_waste = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - chained_waste / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: penalize more if it's "dead" space.
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_quality = (mean_residual - item_size as f64).max(0.0);
        // Base new-bin cost; grows with number of open bins (discourage bin sprawl).
        score += 20.0 + 2.0 * open_bins_count as f64;
        // If mean residual across open bins is generous relative to item, opening is wasteful.
        score += 0.5 * avg_fit_quality;
        // Early in the stream, opening new bins is cheaper (builds diverse residuals).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    } else {
        // Slight preference for bins with residual close to item (perfect-fit seeking).
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * fit_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with a non-linear polynomial coupling
    // to stream progress: late in the stream, tight fits matter more.
    let mut score = norm_pr * (1.0 + 1.5 * progress * progress);

    // Cubic dead-space penalty: residuals that are very small but nonzero
    // are almost unusable; strongly penalize near-zero but positive waste.
    let dead = norm_pr * (1.0 - norm_pr);
    score -= 0.8 * dead * dead;

    // Coupling with mean residual: placing into a bin far from the mean
    // residual balance is mildly penalized (smooth quadratic deviation).
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else {
        // More competing bins -> slight penalty to encourage spreading.
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly into the resulting residual,
    // reward heavily; if next item barely misses, penalize mildly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 1.2 * (1.0 - slack).max(0.0);
        } else {
            score += 0.4 * ((nxt - pr) / cap);
        }
    }

    // Smooth open-bins pressure: many open bins favor consolidation.
    score += 0.02 * (open_bins_count as f64).powf(1.3) * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and few bins fit it (smooth logistic-style gate).
    if bin_residual == bin_capacity {
        let largeness = item_size as f64 / cap;
        let gate = 1.0 / (1.0 + (-(8.0 * (largeness - 0.6))).exp());
        score += 3.0 * (1.0 - gate) + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "complementary"
    // to common item sizes (multiples of 10, and small usable remainders).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill_frac = 1.0 - pr / cap;
    score -= 40.0 * fill_frac * fill_frac;

    // Harmonic class: post_residual mod 10. Residuals that are exact multiples
    // of 10 are "harmonic" and more likely reusable; penalize awkward classes.
    let m = post_residual % 10;
    let harmonic_bonus = match m {
        0 => 12.0,
        1 | 9 => 2.0,
        2 | 8 => 0.0,
        3 | 7 => -3.0,
        4 | 6 => -5.0,
        _ => -7.0, // m == 5 worst: half-slots rarely pair well
    };
    score -= harmonic_bonus;

    // Integer division threshold: tiny residuals are dead space
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    } else if post_residual <= 20 {
        score -= 6.0; // sweet spot for medium items
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic match: next item leaves a multiple-of-10 remainder
            let nm = (post_residual - next_item_size) % 10;
            if nm == 0 { score -= 14.0; } else { score += 3.0; }
        } else {
            // next item won't fit here; mild penalty scaled by overflow
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Prefer placing into relatively full bins among open bins
    if bin_residual < bin_capacity {
        score -= 8.0 * (1.0 - bin_residual as f64 / cap);
    } else {
        // New-bin candidate: penalize slightly unless current bin would be near-full
        let tight = (bin_residual - item_size) == 0;
        if tight { score -= 60.0; } else { score += 10.0; }
    }

    // Early stream: be more willing to open bins; late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    } else {
        score += 6.0 * progress;
    }

    // Mean residual context: when mean residual is large, spreading is okay
    score -= 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item (>=1)
    // can use are pure waste; the worst gaps are "small but nonzero".
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver -> heavy penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 25 {
        // gaps 10..24 are usable only by small items: moderate penalty scaled
        score += 0.8 * (25.0 - post_residual as f64);
    }

    // Reward tight fits: fill fraction of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new one is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // here would be poor or when no open bin fits well.
    if bin_residual == bin_capacity {
        let would_fill = item_size as f64 / bin_capacity as f64;
        // Penalize new bin unless the item is large (good fill of fresh bin).
        score += 45.0 - 40.0 * would_fill;
        // If no existing bin fits at all, opening new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: if the next item would fit exactly in the post_residual,
    // reward this placement strongly (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0; // next item leaves near-perfect state
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            score += 20.0; // next item cannot use this gap anyway
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already "tight" — favor consolidating into it.
    let dev = mean_residual - post_residual as f64;
    score -= 0.25 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post residual
    // closely matches the next item size (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize residual too small for the next item (dead space risk).
        score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
    }

    // Compare post residual relative to mean residual across open bins.
    score -= 0.35 * (post_residual as f64 - mean_residual);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0; // small unusable slivers still better than medium waste
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item
    // fits poorly everywhere (large item, tight stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (item_size as f64 / bin_capacity as f64) > 0.6
            || (fitting_bins_count as f64) <= 1.0;
        if poor_fit {
            score -= 5.0 + 10.0 * progress;
        } else {
            score += 30.0;
        }
    }

    // Mild preference for tighter bins early on.
    score += 0.05 * (bin_residual as f64 - item_size as f64) * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving residual just below next item size (near-miss waste).
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
            if gap < 10 {
                score += 12.0 * (1.0 - gap as f64 / 10.0);
            }
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = mean_residual * (open_bins_count as f64).sqrt();
    score -= pressure * 0.05;

    // Time horizon: early in stream, opening new bins is cheaper; late, consolidate.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 * t + 5.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        score -= 8.0 * t;
    }

    // Mild preference for bins whose residual is close to item size (best-fit flavor).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * norm_pr);

    // Smooth coupling: dead space matters more as the stream progresses.
    score += 3.0 * norm_pr * progress;

    // Reward filling bins deeply (large item relative to residual).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 4.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Lookahead: penalize if next item cannot use the post-residual.
    if next_item_size > 0 {
        let next_fit = next_item_size as f64;
        if pr < next_fit {
            score += 2.0 * (next_fit - pr) / cap;
        } else {
            // Smooth reward when next item fits snugly afterwards.
            score -= 1.5 * (1.0 - (pr - next_fit) / cap);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Keep new-bin candidate competitive only when residuals are badly fragmented.
    score -= 0.3 * (mean_residual / cap - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by small
    // "denominators" (5, 10, 25) are more reusable by typical item sizes.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit: strongly favored
    } else if pr % 25 == 0 {
        -14.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        0.0
    };
    score += class_bonus;

    // Dead-space penalty: small non-harmonic leftovers are unusable.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual,
    // penalize if next item nearly fits but leaves a bad residue.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let nxt_pr = pr - next_item_size;
            if nxt_pr % 5 == 0 || nxt_pr == 0 {
                score -= 8.0;
            } else if nxt_pr < 10 {
                score += 6.0;
            }
        } else {
            // next item won't fit here: mild penalty for hoarding space
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are quite full
    // (mean residual low) or the fit here would be poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        if mean_residual < 20.0 || poor_fit {
            score -= 22.0 + 10.0 * progress;
        } else {
            score += 15.0; // discourage opening bins when good fits exist
        }
    }

    // Mild preference for filling fuller bins (lower residual before place).
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64).recip() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward leaving useful space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap just below the next item size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // toward tighter fits when the mean is already large.
    if mean_residual > 40.0 {
        score -= (bin_residual as f64 - mean_residual).abs() * 0.15;
    }

    // Late in stream: be more conservative, favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // New-bin candidate: penalize opening a new bin mildly, so only truly
    // poor fits among open bins trigger it.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (post_residual small)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if the next item fits in the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            score -= 20.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit here: penalize dead space creation
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins that are more filled than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when a fitting open bin exists
    if bin_residual == bin_capacity {
        score += 30.0;
        // but allow new bin if current item is large and open bins are crowded
        if item_size >= 50 && mean_residual < item_size as f64 {
            score -= 60.0;
        }
    }

    // Mild late-stream consolidation bias
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that cannot hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }

    // Lookahead coupling: reward bins whose post residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0;
        }
        // Penalize leaving residual that only barely excludes the next item.
        if post_residual < next_item_size && post_residual >= next_item_size - 3 {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: bins far from the mean residual get a nudge.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in stream, be more willing to open new bins (score for new bin lower);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has large post_residual; make it attractive
    // only when the item is large relative to capacity or existing residuals are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * frac;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a smooth non-linear penalty on residual
    let mut score = norm_pr * norm_pr * cap;

    // Stream-progress coupling: later in the stream, be stricter about residual
    score += 20.0 * progress * norm_pr * (1.0 - norm_pr);

    // Dead-space penalty: residuals too small to fit typical items
    let small_dead = (norm_pr - 0.15).tanh();
    score += 10.0 * small_dead * small_dead * cap * 0.1;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // smooth penalty when next item won't fit
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 6.0 * gap * gap * cap;
    }

    // Mean-residual coupling: penalize bins far from mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // Slight preference to fill existing bins when many are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (capacity fraction classes)
    let residue = post_residual % 10;
    // Perfect-fit class (residual 0) gets strong reward
    if post_residual == 0 {
        score -= 60.0;
    }
    // Tiny dead space classes are bad: penalize residuals 1..=5
    if residue >= 1 && residue <= 5 && post_residual > 0 {
        score += 12.0 + 2.0 * (5 - residue) as f64;
    }
    // Nice harmonic classes (10,20,...) get slight reward
    if residue == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division threshold: can next item fit exactly or at least snugly?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward, extra if it fills the bin
            score -= 10.0;
            if post_residual - next_item_size == 0 {
                score -= 25.0;
            } else if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
        } else {
            // lookahead cannot fit here: penalize leaving large unusable-looking space
            score += 4.0;
        }
    }

    // Capacity fraction coupling: waste fraction of the bin
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 20.0;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when current fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open a new bin late in stream with many open bins
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            // new bin can hold next item too
            score -= 12.0;
        }
        // if many bins fit the item, opening new bin is wasteful
        score += (fitting_bins_count as f64) * 3.0;
    }

    // Prefer tighter bins among fitting candidates
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Slight preference to balance mean residual when many bins open
    if open_bins_count > 3 && (post_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item.max(1) * 10 {
            // gap too small for anything meaningful in typical streams
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        }
        // penalize gaps below the smallest plausible item size harder
        if post_residual < 10 {
            score += 40.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 50.0;
    }

    // Reward tight fits relative to capacity
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Open-bin pressure: discourage scattering across many bins
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // New-bin candidate: neutral baseline with slight penalty so it is only
    // chosen when all open bins fit poorly
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 0.5;
    }

    // Stream progression: as stream matures, tighten dead-space tolerance
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: post_residual equals next_item_size => strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residuals that are too small for any plausible item (dead space)
        if post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: just minimize waste
        score += 5.0;
    }

    // Penalize large post_residual only mildly (keeps bins flexible),
    // but reward using a bin whose residual was tight relative to item
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Relative to mean residual: prefer filling below-average-residual bins
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, mildly prefer tighter fits (handled by tightness)
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // base penalty so we prefer existing bins with decent fits
        score += 15.0;
        // but if many open bins are fragmented (high mean residual spread), opening fresh is fine
        if mean_residual < 30.0 {
            score -= 10.0;
        }
        // early in stream, opening bins is cheap
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 5.0;
        }
    }

    // Slight preference to keep number of open bins bounded
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual strongly favored.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Penalize wasted capacity relative to bin size.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 20.0;

    // Lookahead coupling: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 12.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
    } else if next_item_size > 0 {
        // If next item nearly fits, small penalty for near-miss dead space.
        let gap = (next_item_size as f64 - post_residual as f64).abs();
        score += gap * 0.15;
    }

    // Last-chance bonus: only one fitting bin left, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins with high mean residual: prefer consolidating into fullest bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > (bin_residual as f64) {
        score += (mean_residual - bin_residual as f64) * 0.05 * (1.0 + progress);
    }

    // Time horizon: late in stream, be conservative — favor tight packing, avoid new bins.
    if progress > 0.7 {
        score -= post_residual as f64 * 0.1;
    } else {
        score += progress * 5.0;
    }

    // Penalize opening a new bin unless current bins have small residuals.
    if bin_residual == bin_capacity {
        let avg = mean_residual.max(0.0);
        score += 8.0 + avg * 0.2 - (open_bins_count as f64) * 0.3;
        // New bin attractive when item is large and nothing fits well.
        if fit_ratio > 0.9 {
            score -= 10.0;
        }
    }

    // Slight penalty for very small dead space that's hard to reuse (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with a smooth non-linear
    // polynomial in the normalized post-residual.
    let x = post / cap; // in [0,1]
    let mut score = 2.0 * x * x + x;

    // Smooth penalty for unusable dead space: residual too small for the next item.
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - post) / cap;
        if gap > 0.0 {
            // grows quadratically as the dead space becomes worse relative to next item
            score += 3.0 * gap * gap * (1.0 + progress);
        } else {
            // reward bins that can also host the next item, smoothly
            score -= 0.5 * (-gap) * (1.0 - progress);
        }
    }

    // Interaction of post_residual with stream progress: late in the stream,
    // tightening packing matters more; early on, keep bins flexible.
    score += progress * post / cap * (post / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 + 0.5 * progress;
    }

    // Slight preference to spread load when many bins are open and mean residual is high.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // New-bin candidate: make the empty bin attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 1.2 + mean_residual / cap - progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Residuals divisible by large powers of 2 or by 10 pair well with common sizes.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -15.0
    } else if pr % 20 == 0 {
        -12.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds: leftover in the "dead zone" (< smallest item) is worthless.
    if pr > 0 && pr < 10 {
        score += 35.0;
    } else if pr < 20 {
        score += 10.0;
    }

    // Lookahead coupling: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 40.0; // next item will close this bin perfectly
            } else if slack % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 6.0; // next item can't use this bin
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if item is large, a new bin is fine
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Fraction-of-capacity classes for the item itself.
    let frac = item_size as f64 / cap;
    if (frac * 4.0).fract() < 1e-9 {
        score -= 5.0; // item divides capacity into quarters nicely
    }

    // Progress scaling: tighten criteria as the stream proceeds.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Mild tie-break toward consolidating into fewer bins.
    score -= mean_residual / cap * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // realistic future item (min size 1, but practically small gaps < 10)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else {
            // Smooth penalty for moderately wasteful gaps
            score += 0.15 * (post_residual as f64).powi(2) / 10.0;
        }
    }

    // Reward tight fits (item fills most of the bin)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // If next item does NOT fit in post residual but would fit a larger
    // residual, penalize blocking the lookahead
    if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
        score += 6.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing
    // bins rather than spreading.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate handling: opening a new bin is expensive when many
    // bins are open; make the empty bin less attractive unless the current
    // item would leave a large dead gap in every existing bin.
    if bin_residual == bin_capacity {
        score += 35.0 + 1.2 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is fine
        score -= 0.3 * item_size as f64;
        // Late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mean-residual coupling: if the average open residual is already small,
    // this bin's slack is precious; discourage wasting it.
    if mean_residual > 0.0 {
        let rel_waste = post_residual as f64 / mean_residual;
        score += 5.0 * rel_waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base reward for tight fits: penalize large post_residual quadratically.
    score += 0.6 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if nr <= pr {
            let match_quality = 1.0 - (pr - nr) / bin_capacity as f64;
            score -= 12.0 * match_quality * match_quality; // next item fits snugly here
        } else {
            // Next item won't fit after placement; penalize proportionally to overflow.
            score += 4.0 * ((nr - pr) / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste.
        score -= 8.0;
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    let pr = post_residual as f64;
    score += 1.5 * (pr - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty to spread load when fit is loose.
        score += 0.5 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: only attractive when no open bin is a good home.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is penalized early, tolerated late or when item is huge.
        let huge_item = (item_size as f64) > 0.8 * bin_capacity as f64;
        let poor_open_options = mean_residual < item_size as f64;
        if huge_item || poor_open_options || progress > 0.9 {
            score -= 5.0;
        } else {
            score += 20.0 + 10.0 * (1.0 - progress);
        }
    }

    // Slight preference for using more-opened bins to close them out.
    score -= 0.05 * open_bins_count as f64 * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual > 0 && next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0; // lookahead item cannot use this residual
        } else {
            score -= 6.0; // lookahead fits nicely after placement
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate logic: opening a new bin is expensive when many bins
    // are open and residual capacity is spread thin; allow it early or when
    // the item is huge relative to mean residual (poor fit everywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_pressure = (mean_residual - item_size as f64).max(0.0);
        let new_bin_penalty = 15.0 + 20.0 * progress + 0.6 * open_bins_count as f64 - 0.25 * waste_pressure;
        score += new_bin_penalty;
        // Huge items fit perfectly alone; encourage fresh bin for them.
        if item_size >= 90 {
            score -= 20.0;
        }
    }

    // Slight preference for filling bins with larger residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Time-horizon modulation: as stream ends, prioritize compacting existing bins.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * horizon * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fills (low post_residual) but tolerate some slack.
    // Late stream: strongly prefer small post_residual to close bins out.
    let w_tight = 0.5 + 1.5 * progress * progress;
    score -= w_tight * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.5;

    // Penalize very small dead space (unusable fragments) with a smooth quadratic term.
    let frag = if pr < cap * 0.2 { (cap * 0.2 - pr) / cap } else { 0.0 };
    score += 40.0 * frag * frag;

    // Reward filling a bin almost exactly (smooth gaussian-like bump near zero residual).
    score -= 30.0 * (-(norm_pr * norm_pr) / 0.02).exp();

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64) / pr.max(1.0));
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild coupling with mean residual: prefer bins below mean residual (consolidating slack).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for bins with more residual (keep big bins flexible) early on.
    score += (1.0 - progress) * 0.2 * (bin_residual as f64 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small dead space" class (post_residual < 10) are excellent.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect, unusable sliver
    } else if post_residual <= 20 {
        score -= 8.0; // still potentially usable for small items
    }

    // Penalize large leftover classes: 21..50 (medium waste), >50 (bad).
    if post_residual > 50 {
        score += 12.0;
    } else if post_residual > 30 {
        score += 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly reward; if next item cannot fit, penalize (dead space ahead).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic compatibility: next item divides/leaves small remainder
            let r2 = post_residual - next_item_size;
            if r2 < 10 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            score += 10.0; // next item blocked by this placement
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it is chosen only
    // when all open bins score poorly, but keep it competitive for big items.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.15 * open_bins_count as f64;
    }

    // Prefer tighter-than-average bins (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, waste matters more; tighten selection.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in unusable small gaps is heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item (1) but practically
    // smaller than typical item sizes; treat gaps below a threshold as dead space.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 2.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open with scattered residuals;
    // encourage consolidating into fewer bins when open_bins_count is high.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if next item would not fit here but the current fit is loose.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.3;
    }

    // Slight preference to fill bins with lower residual first (best-fit core),
    // modulated by mean residual across bins.
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.2;
    score += (mean_residual - bin_residual as f64).abs() * 0.1;

    // New-bin candidate handling: opening a new bin is acceptable only when residual
    // pressure is high or the fit elsewhere is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if open_bins_count as f64 * 1.5 > 30.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let match_gap = post_residual as f64 - nxt;
            // strong reward for near-exact match with next item
            score -= 60.0 * (1.0 - match_gap / bin_capacity as f64);
            // extra bonus for exact lookahead fit
            if match_gap == 0.0 {
                score -= 250.0;
            }
        } else {
            // next item cannot fit here; penalize leaving large unusable-looking space
            score += 15.0 + 0.3 * (nxt - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening new bins as stream progresses, unless residual is tiny
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 + 80.0 * progress;
        // allow new bin if current item is huge and would leave awkward space elsewhere
        if item_size > bin_capacity / 2 && post_residual < 20 {
            score -= 30.0;
        }
    }

    // Mild penalty for very small dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively than linear.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else {
        let slack_ratio = post_residual as f64 / bin_capacity as f64;
        score += slack_ratio * 15.0; // penalize large dead space
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item would fit in the post-residual, reward this placement
    // (chains items nicely). If next item cannot fit here anyway, mild penalty for
    // leaving awkward residuals.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // residual that nothing (next item) can use is more wasteful
            score += 6.0;
        }
    }

    // Compare against mean residual: prefer bins that are already emptier than average
    // when fit is loose (keeps tight bins for tight fits), but prefer fuller bins
    // when fit is tight (best-fit style consolidation).
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
    let fullness_gap = fullness - mean_fullness;
    score -= fullness_gap * 10.0 * (item_size as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (spread items); late in the stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0; // mild early penalty on using existing bins

    // New-bin candidate handling: an empty bin is only attractive when the item
    // fits poorly in all open bins or there are very few open bins.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > bin_capacity / 3);
        if poor_fit_elsewhere || open_bins_count <= 1 {
            score -= 20.0; // opening a new bin is justified
        } else {
            score += 25.0; // discourage wasting fresh bins
        }
    }

    // Slight preference to fill bins with many open bins around (reduce bin count pressure)
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post / cap;

    // Base: post residual (tighter fit preferred)
    let mut score = post;

    // Non-linear coupling of post residual with stream progress:
    // late in the stream, small residuals matter more (dead space penalty grows)
    let dead_space_penalty = norm_post.powi(3) * (1.0 + 3.0 * progress * progress);
    score += dead_space_penalty * cap;

    // Reward filling bins completely (post_residual near zero)
    score -= (1.0 - norm_post).powi(4) * cap * (0.3 + 0.5 * progress);

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= fit_quality * cap * 0.8;
    } else if next_item_size > 0 {
        // next item can't use this residual: penalize leaving medium dead space
        score += norm_post * (1.0 - norm_post) * cap * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.6;
    }

    // Penalize opening new bins when open bins have slack, more so early on
    if bin_residual == bin_capacity {
        score += cap * (0.4 + 0.6 * (1.0 - progress)) + (open_bins_count as f64).sqrt() * 2.0;
        // but allow new bin if mean residual is very low relative to item
        if mean_residual < item_size as f64 {
            score -= cap * 0.7;
        }
    }

    // Slight preference for bins with below-average residual (concentrate fills)
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 10 integer bands.
    // Small post_residual classes (tight fits) are rewarded strongly.
    let class = (post_residual / (bin_capacity / 10).max(1)) as f64;
    score -= (10.0 - class) * 3.0;

    // Perfect / near-perfect fits get a strong discount.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Dead space penalty: leftover that no typical item (>=1) can use well.
    // Penalize leftovers in awkward mid ranges (11..30) that rarely pair with
    // small items drawn from an unknown distribution.
    if post_residual > 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // next item cannot follow here; mildly penalize
            score += 5.0;
        }
    }

    // Last chance: this is the only bin that fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish baseline that
    // keeps it attractive only when no open bin fits decently.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // slight discount if next item is small (new bin stays flexible)
            score -= next_item_size as f64 * 0.1;
        }
        if fitting_bins_count == 1 {
            // an existing bin can take it; discourage opening a new bin
            score += 30.0;
        }
    }

    // Stream progression: early on, be a bit greedy toward tight fits;
    // later, slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0;

    // Deviation from mean residual: bins far below mean residual are already
    // fragmented; prefer bins whose residual is close to item_size.
    let resid_f = bin_residual as f64;
    let fit_gap = (resid_f - item_size as f64).abs();
    score += fit_gap * 0.15;
    score -= (mean_residual - resid_f).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 50.0;
    }
    // Dead space relative to the smallest plausible item (sizes 1..100): gaps < ~10 are near-unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Open-bin pressure: prefer spreading across existing bins when many are open,
    // but penalize opening new bins when plenty of fitting bins exist.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { -60.0 } else { 25.0 + fitting_bins_count as f64 * 5.0 };
        score += pressure;
        score += mean_residual * 0.5; // opening a bin wastes existing mean residual
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // next item can't use the gap
    }

    // Stream progression: early on, be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(6);

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // the next item size (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    } else if next_item_size > 0 {
        // Penalize post_residual that cannot fit the next item but is small
        // (dead space for the lookahead item).
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // post_residual can fit next item: mild bonus proportional to closeness.
            score -= 12.0 * (1.0 - gap / (bin_capacity as f64));
        }
    }

    // Relative-to-mean coupling: bins with residual well below mean are "fuller",
    // prefer filling them further.
    score -= 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize leaving awkward residuals in [1, 9] (unusable dead space).
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }

    // New-bin candidate: only attractive early in the stream or when open bins
    // are all quite full (mean residual low) and the item would leave big dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_elsewhere = if post_residual < next_item_size && next_item_size > 0 { 20.0 } else { 0.0 };
        score += 45.0 + 30.0 * (1.0 - progress) - waste_elsewhere
                 + 0.5 * mean_residual;
    }

    // Slight preference for bins that remain versatile after placement.
    score -= 0.15 * (post_residual as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize large post-residuals that are too small to be useful later
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect pairing: item + next item exactly fills the bin.
            if post_residual == next_item_size {
                score -= 30.0;
            } else {
                score -= 12.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
            }
        } else {
            // Next item can't follow here; slight penalty.
            score += 6.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Early in the stream, prefer spreading into many bins (keeps residuals flexible).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += 0.05 * (post_residual as f64);
    } else if progress > 0.8 {
        // Late: pack tightly, avoid opening new bins.
        if bin_residual == bin_capacity {
            score += 15.0;
        }
    }

    // New-bin candidate: only attractive when mean residual is badly fragmented
    // (mean residual too small to be useful) or no good fit exists.
    if bin_residual == bin_capacity {
        let frag = if mean_residual > 0.0 { (mean_residual - item_size as f64).abs() } else { 0.0 };
        score += 30.0;                       // base cost of opening a bin
        score -= 0.10 * mean_residual;       // reward when open bins are fragmented
        if fitting_bins_count == 0 { score -= 50.0; }
        if frag > 20.0 { score -= 10.0; }
    }

    // Mild penalty for wasting a large bin on a tiny item.
    if item_size < bin_capacity / 4 && bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space matters more; early, keep bins flexible.
    let norm_post = post / cap; // 0..1
    let progress_weight = 1.0 + 2.0 * progress * progress; // quadratic in progress
    score += progress_weight * (norm_post * norm_post) * cap * 0.5;

    // Reward near-perfect fits (small post_residual) with a smooth bonus.
    let tightness = (1.0 - norm_post).clamp(0.0, 1.0);
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize the brand-new empty bin candidate smoothly, unless the fit
    // into open bins would be very poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * progress;
        // Allow new bin if placing here would leave big dead space anyway.
        score -= 0.15 * post;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 4.0 * (1.0 - ((post - nxt) / cap).abs());
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading residual far from mean (bin diversity control).
    let dev = (res - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // Harmonic class of post_residual: residues divisible by common size classes are valuable
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 6.0;
    }

    // Dead-space penalty: tiny unusable gaps
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does post_residual accommodate next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let next_fit = pr - next_item_size;
            if next_fit == 0 {
                score -= 40.0; // enables a perfect follow-up
            } else if next_fit < 10 {
                score += 10.0; // leaves a near-dead sliver
            } else {
                score -= 8.0;
            }
        } else {
            score += 15.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would waste a lot
    if bin_residual == bin_capacity {
        let waste = bin_residual - item_size;
        score = 55.0 + waste as f64 * 0.3;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    // Stream progression: tighten packing in late stages
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space that cannot fit even the smallest plausible item is very bad.
        if post_residual < 10 {
            score += 120.0;
        } else if post_residual < 20 {
            score += 45.0;
        } else if post_residual < 30 {
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward filling a bin deeply (high fill ratio).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
        // Extra reward for a near-perfect chain fit.
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item would have fit before this placement but won't after: penalize.
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer using existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // Mean residual coupling: bins far below the mean residual are "fresher";
    // prefer placing into bins with residual close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Prefer bins whose residual is below the mean (they are already partly used).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: make it unattractive unless existing bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * -1.0;
        // If no other bin fits, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead match: post residual exactly fits next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 20.0 * (1.0 - progress);
    }
    // Near match: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - leftover / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to how much it misses
        let miss = (next_item_size - post_residual) as f64;
        score += 0.4 * miss;
    }

    // Reward tight fits (small post residual) more strongly
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize creating dead space below typical small item size
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 30.0 };
        score += 55.0 - bad_fit + 10.0 * progress;
    }

    // Prefer bins with residual below mean (consolidate emptier space usage)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space too small for any future item (min size 1..100 unknown; use 10 as soft floor).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        score -= 10.0 + 0.15 * next_fit as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly prefer using this bin now.
        score -= 3.0;
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Relative deviation from mean residual: prefer bins tighter than average.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 6.0 * dev;

    // Prefer filling already-open bins as stream progresses; more open bins -> more pressure to use them.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 4.0 + (open_bins_count as f64).sqrt() * 1.5;

    // New-bin candidate: penalize opening a new bin unless the item is large and residual waste would be big.
    if bin_residual == bin_capacity {
        let waste_here = bin_residual.saturating_sub(item_size) as f64;
        score += 8.0 - 0.08 * waste_here;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, with quadratic coupling to stream progress.
    let mut score = pr * (1.0 + 1.5 * progress * progress);

    // Non-linear polynomial coupling: cubic in normalized residual, modulated by progress.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (2.0 - norm_pr);
    score += 40.0 * poly * (0.5 + progress);

    // Dead-space penalty: tiny post-residuals are useless unless next item fits.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 25.0 * fits_next * (1.0 - progress);
        // Reward when post-residual matches next item size closely (smooth kernel).
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 15.0 * gap * gap;
    } else {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer bins below mean residual (tighter bins) with smooth interaction.
    score += 0.3 * (mean_residual - bin_residual as f64) * (0.5 + progress);

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common small sizes) are more valuable to keep tight.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Dead-space penalty grows super-linearly for small unusable leftovers,
    // unless the leftover is a "harmonic" size (divisible by 5 or 10).
    if pr > 0 {
        let harmonic = (pr % 10 == 0) as i32 + (pr % 5 == 0) as i32 + (pr % 20 == 0) as i32;
        if harmonic == 0 {
            // awkward leftover: penalize
            score += 6.0 + (10.0 - (pr % 10) as f64) * 0.8;
        } else {
            // clean leftover: reward proportionally
            score -= 2.0 * harmonic as f64;
        }
    }

    // Perfect fit bonus
    if pr == 0 {
        score -= 25.0;
    }

    // Fraction-of-capacity coupling: filling a bin past half is good.
    let fill_frac = (cap - prf) / cap;
    if fill_frac > 0.5 {
        score -= 8.0 * (fill_frac - 0.5);
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residual: mild reward scaled by fit tightness
            let tight = 1.0 - ((pr - next_item_size) as f64) / cap;
            score -= 6.0 * tight;
        } else {
            // next item won't fit here: if this bin is the only option, penalize
            // wasting a near-full bin on the current item
            if pr < 10 {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline that keeps it
    // competitive only when open bins have large residuals.
    if bin_residual == bin_capacity {
        // neutral-ish score relative to mean residual of open bins
        score = cap * 0.55 + mean_residual * 0.3 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big next item: fresh bin attractive
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer tightening
    // existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - fill_frac);

    // Mild penalty when bin residual deviates far from mean residual
    // (encourages balanced bin usage across the fleet).
    let dev = (prf - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward filling the bin deeply with the current item
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Penalize the brand-new empty bin candidate: prefer using open bins
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead (k=2): reward if the next item can also fit in the leftover space
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            // penalize leftovers that block the next item
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Mild pressure from mean residual: prefer bins below-average fullness targets
    score += mean_residual * 0.05;

    // Progression: early in the stream, be slightly more willing to consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills (minimal dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // exact two-item match
        } else if post_residual >= next_item_size {
            // prefer leaving a residual the next item can still use
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack.min(120.0);
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    } else {
        // last item: just minimize residual
        score -= 150.0;
    }

    // Relative-to-mean coupling: bins tighter than average are good candidates.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when current item is huge
    // (little point squeezing into a small gap) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin wastes space equal to (capacity - item); penalize
        // unless the item is large and no open bin is tight.
        let waste_penalty = (bin_capacity - item_size) as f64;
        score += waste_penalty * (0.5 + 0.5 * (1.0 - item_frac)) * (0.5 + 0.5 * progress);
        // discourage proliferation of open bins
        score += open_bins_count as f64 * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the bin.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Dead-space penalty: small post_residual that can never be used again
    // (too small for the smallest plausible item) is worthless.
    if post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward;
    // if the next item cannot fit, the leftover is likely dead space, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        } else {
            score -= 2.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin at almost any cost.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer filling bins with large residual (reduce fragmentation):
    // a bin whose residual is close to the item size is a great match.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Global state coupling: when many bins are open, avoid opening new ones;
    // when few bins are open, new-bin candidate is less penalized.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.5 * mean_residual;
        // If no open bin can fit the item, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= 0.2 * open_bins_count as f64;
        // Prefer bins with residual below the mean (consolidate small leftovers).
        score -= 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) dead-space penalty.
    let mut score = pr + 0.004 * pr * pr;

    // Reward tight fits: normalized fit quality, smoothly amplified by stream progress.
    let fit_ratio = item / cap;
    let tightness = (1.0 - fit_ratio) * (1.0 - fit_ratio);
    score -= 22.0 * (1.0 - tightness) * (0.6 + 0.8 * progress);

    // Lookahead coupling: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = ((pr - nxt) / cap).abs();
        let match_reward = (-4.0 * gap * gap).exp();
        score -= 10.0 * match_reward * (0.5 + 0.7 * progress);
        // Penalize leaving a residual just below the next item (unusable wedge).
        if pr < nxt {
            score += 6.0 * (1.0 - pr / cap) * (0.4 + 0.6 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 18.0 * (0.5 + 0.9 * progress);
    }

    // Smoothly penalize scattering residual across many bins.
    score += 0.35 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    // New-bin candidate: penalize mildly early, more strongly late in the stream,
    // but relax the penalty when existing residuals are poor.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let mean_quality = 1.0 - (mean_residual / cap).powi(2);
        score += 8.0 + 14.0 * progress - 10.0 * mean_quality;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    score -= 40.0 * (-post_residual as f64 / 15.0).exp();

    // Penalize dead space that is too small to be useful later (below min item size 1..10 band).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (1.0 - dead / 10.0);
    }

    // Harmonic class: if next item fits exactly into post_residual, big reward (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (-gap / 10.0).exp();
        // exact match bonus
        if gap == 0.0 { score -= 30.0; }
    } else if next_item_size > 0 {
        // next item cannot fit here; leftover space is pure dead weight
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Modulo-class logic on residual: residuals in friendly classes (multiples of 10)
    // chain better with typical item sizes.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Discourage opening new bins when a reasonable fit exists.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow new bin if all open bins would leave very awkward residuals.
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate: fewer open bins relative to stream length -> prefer reusing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (open_bins_count as f64 / (mean_residual.max(1.0))) * (1.0 - progress);

    // Slight preference for bins already below mean residual (keeps large spaces for large items).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= tightness * 12.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; when few,
    // opening a new bin is cheaper, so mildly favor tight existing fits anyway.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item can't use the leftover: leftover is likely dead space.
            score += post_residual as f64 * 0.5;
        }
    }

    // Mean residual coupling: prefer bins with residual below the mean
    // (concentrate filling), penalize above-mean bins.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: baseline competitiveness; make it attractive only
    // when item is large or existing fits are poor.
    if bin_residual == bin_capacity {
        score = 55.0 - (item_size as f64) * 0.3 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= post_residual_max(item_size, bin_capacity) {
            score -= 5.0;
        }
    }

    score
}

#[inline]
fn post_residual_max(item_size: u32, bin_capacity: u32) -> u32 {
    bin_capacity - item_size
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: prefer tight fits (low post residual), with non-linear urgency
    // on small residuals (dead space becomes unusable quickly).
    if post > 0.0 {
        score += (cap - post) / cap * 8.0;      // mild reward for fullness
        if post < 10.0 {
            score -= 6.0;                        // near-perfect fit bonus
        } else {
            score += (post / cap) * 12.0;        // penalty for large leftovers
        }
    } else {
        score -= 15.0;                           // perfect closure is best
    }

    // 2-step lookahead: does post_residual match the next item?
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let gap = post - next_item_size as f64;
        // Reward exact/loose matching of the next item into the leftover space
        score -= (1.0 - gap / cap) * 20.0;
        if gap < 5.0 {
            score -= 10.0; // chain fit: post_residual ~ next item size
        }
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize proportional waste
        let unusable = (next_item_size as f64 - post).min(cap);
        score += (unusable / cap) * 14.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer;
    // filling them is more valuable than filling an above-mean bin.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when the item is large relative to capacity or the
    // stream is early (many future items justify a fresh bin).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Empty-bin cost: high by default so tight fits in open bins win.
        score += 25.0;
        // Large items or early stream make a fresh bin more acceptable.
        score -= frac * 20.0 + (1.0 - progress) * 10.0;
        // If next item is large too, a fresh bin preserves big residual elsewhere.
        if next_item_size as f64 > 0.5 * cap {
            score -= 8.0;
        }
    }

    // Slight preference to keep number of open bins low late in the stream.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals that can't fit the next item (wasted dead space).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            // Reward bins that can still host the lookahead item.
            score -= 2.0;
            // Extra reward if lookahead fits snugly (low slack after lookahead).
            let after_next = post_residual - next_item_size;
            score -= (after_next as f64).min(10.0) * 0.1;
        }
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    } else if post_residual < 10 {
        // Small dead space is bad: it's below the minimum item size.
        score += (10 - post_residual) as f64 * 0.4;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future to use them); late, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 12.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced early in the stream.
        score += 5.0 - new_bin_bias;
        // Opening a bin is more attractive when existing bins are quite full
        // (mean residual low) or few bins fit the item.
        score -= mean_residual * 0.05;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Prefer fuller bins (smaller residual) generally.
        score += (bin_capacity - bin_residual) as f64 * 0.02;
        // When many bins fit, prefer the tightest; add mild penalty coupling
        // with mean residual to spread load when residuals are high.
        score += (mean_residual - post_residual as f64).max(0.0) * 0.05;
        // Late stream: penalize leaving big residuals in open bins.
        score += progress * (post_residual as f64) * 0.15;
    }

    // If many bins are open, discourage opening yet another one.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let quad = norm_pr * norm_pr;
    score += 12.0 * (1.0 - progress) * quad * cap * 0.5;
    score -= 8.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.5;

    // Reward tight fits smoothly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Penalize waste relative to mean residual
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead compatibility
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (0.3 + 0.7 * progress);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for bin proliferation late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fit is best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small dead space, especially when next item can use it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Dead space the lookahead item cannot use: penalize by wasted fraction.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless current bin would leave a bad modulo class.
    if bin_residual == bin_capacity {
        // Prefer new bin only if best fitting open bin would leave tiny unusable gap.
        let gap_class = post_residual % 10;
        if gap_class > 0 && gap_class < 5 && post_residual > 0 && post_residual < 10 {
            score -= 40.0;
        } else {
            score += 60.0;
        }
    }

    // Harmonic threshold on post_residual: leftovers divisible by common item
    // sizes (10, 20, 25, 50) are more reusable.
    let r = post_residual;
    if r > 0 && (r % 10 == 0 || r % 25 == 0 || r % 50 == 0) {
        score -= 10.0;
    }

    // Fractional capacity coupling: prefer filling to >= 80% of capacity.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if fill_frac >= 0.8 {
        score -= 15.0;
    }

    // Slight preference for tighter bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Early stream: be conservative, prefer new bins less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1..100 unknown,
    // but typical small items) can use are wasted. Penalize tiny residual gaps hard.
    if post_residual > 0 {
        // gap smaller than a plausible minimum item -> strong penalty
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 20 {
            score += 18.0;
        }
        // non-linear coupling: dead space ratio weighted by tightness of fit
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fit_ratio;
        // perfect fit bonus
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Last chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins would leave bad dead space. Add pressure proportional to
    // open bin count so we reuse bins when reasonable.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 35.0;
        // pressure grows with number of open bins
        score += 2.0 * open_bins_count as f64;
        // late in the stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to mean residual (balanced packing)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if next item exactly fits the post-residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // if next item cannot fit in post-residual but could in bin_residual alternatives,
    // slight penalty for stranding space
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // open_bins_count pressure: mildly discourage adding load that keeps many bins open
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight non-linearity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Dead space for the next item: penalize proportionally to leftover.
            let waste = (post_residual as f64).min((next_item_size - 1) as f64);
            score += 0.5 * waste;
        }
        // Perfect chaining: post_residual exactly equals next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 5.0;
    }

    // Compare against mean residual: bins tighter than average are precious, keep them.
    if (bin_residual as f64) < mean_residual {
        score += 4.0; // tighter-than-average bin: penalize using it unless fit is tight
    } else {
        score -= 2.0; // looser-than-average bin: prefer filling it
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // gives a decent fit. Penalize opening a new bin, more so early in the stream
    // and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin may be right.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never be used by typical items (residual < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Perfect fit: extreme reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_waste = post_residual - next_item_size;
            score -= 15.0 * (1.0 - pair_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to leftover gap.
            score += 0.1 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global congestion: many open bins with low mean residual -> prefer consolidation.
    let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * congestion;

    // Time horizon: early in the stream, be conservative (favor new bins for large items);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // New-bin candidate handling: only attractive when item is large relative to capacity
    // and open bins are fragmented.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
        score -= 18.0 * large_item * fragmentation;
        // But late in the stream, opening new bins is wasteful.
        score += 15.0 * progress;
    }

    // Mild penalty for bins whose residual deviates strongly from the mean (keeps diversity).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tight = 1.0 - norm_pr;
    score -= (10.0 + 30.0 * progress) * tight * tight;

    // Penalize dead space below typical next-item size (non-linear in gap)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Reward leaving room for the lookahead item
        let room = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 8.0 * (room - room * room);
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    let frag = (mean_residual - pr).abs() / cap;
    score += 5.0 * frag * frag * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact-fit residue classes.
    let post = post_residual;
    if post == 0 {
        score -= 50.0; // perfect packing, best possible outcome
    } else if post < 10 {
        score -= 20.0; // near-perfect, tiny dead space
    } else {
        // Dead-space penalty grows super-linearly for large unusable gaps.
        let frac = post as f64 / cap;
        score += 25.0 * frac * frac;
        // Modulo classes: residues near capacity/2 are the worst (hardest to fill later)
        let half = bin_capacity / 2;
        let dist_half = (post as i32 - half as i32).unsigned_abs() as f64;
        score += 0.3 * dist_half;
        // Integer-division threshold: post_residual bucketed into eighths of capacity
        let bucket = post / (bin_capacity / 8).max(1);
        score += 4.0 * bucket as f64;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Harmonic match: next item size divides or complements the residue class
            if post % next_item_size == 0 && post > 0 {
                score -= 15.0; // residue is an exact multiple of next item
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; penalize more if the gap is large
            let gap = (next_item_size - post) as f64;
            score += 0.2 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win
        score += 45.0;
        // But if existing residuals are all bad (mean residual small = tight bins),
        // opening a fresh bin is attractive.
        let mean_frac = mean_residual / cap;
        if mean_frac < 0.25 {
            score -= 35.0;
        }
        // Late in stream, avoid opening new bins for small items
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size <= 30 && progress > 0.8 {
            score += 25.0;
        }
        // Large items justify fresh bins more readily
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild pressure against hoarding many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // for future items (sizes >= 1, but typical items are large), so punish
    // them super-linearly.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead <= 20.0 {
            score += (21.0 - dead) * (21.0 - dead) * 2.5; // harsh penalty for unusable slivers
        }
    } else {
        // Perfect fit: strong reward.
        score -= 150.0;
    }

    // Reward tight fits relative to item size (low wasted fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 3.0;

    // New-bin candidate: neutral-ish baseline, but allow it when current bin
    // would leave a bad gap AND the next item could use the fresh bin.
    if bin_residual == bin_capacity {
        score = 50.0 + pressure * 0.5;
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 * 0.9 {
            score -= 20.0;
        }
        // Late in the stream, avoid spawning bins for marginal gains.
        score += progress * 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // Penalize if next item barely misses the leftover (wasted pairing).
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Slight preference for bins below mean residual (consolidating slack).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (low post_residual), scaled by fraction of stream done.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly-ish: strong reward for chaining placements.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.4 * slack.min(50.0) as f64;
            if post_residual == next_item_size {
                score -= 25.0; // perfect 2-item pairing
            }
        } else {
            // Post residual too small for the lookahead item: penalize proportionally
            // to how stranded that dead space is.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste.min(60.0);
        }
        // Bonus when the *pair* (item + next) perfectly matches the residual.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    } else {
        // Last item: just minimize residual.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than average are worth filling.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev; // lower residual than mean => subtract => favored

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize scattering across many open bins slightly; encourage consolidation.
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64 - 4.0);
    }

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space: residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here after placement; slight penalty if
            // post_residual becomes stranded relative to next item.
            score += 5.0;
        }
    }

    // Time horizon: early in stream, prefer keeping residuals flexible
    // (penalize very small residuals); late in stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.15;
    score -= progress * 10.0;

    // Global state: many open bins -> discourage spreading, favor filling.
    if open_bins_count > 2 {
        score -= 3.0 * (open_bins_count as f64).ln() * tight;
    }

    // Mean residual coupling: if this bin is much emptier than average,
    // prefer filling it to balance residuals.
    let dev = (bin_residual as f64) - mean_residual;
    if dev > 0.0 {
        score -= 0.05 * dev;
    } else {
        score += 0.05 * (-dev);
    }

    // New-bin candidate: only open a new bin when no open bin fits well
    // (item barely fits nowhere) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count <= 1 && post_residual < 15);
        if poor_fit {
            score -= 45.0;
        } else {
            score += 60.0 + 5.0 * (fitting_bins_count as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping.
    let mut score = post_norm * (1.0 + 2.0 * post_norm * post_norm);

    // Smooth stream-progress coupling: tighten bins more aggressively later in the stream.
    score += 3.0 * post_norm * progress * (1.0 - progress + 0.5);

    // Penalize dead space relative to mean residual (wasted capacity vs fleet average).
    score += 0.4 * (post - mean_residual) / cap;

    // Lookahead: reward bins whose post-residual still fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 1.5 * (1.0 - slack * slack);
        } else {
            score += 0.8 * (nxt - post) / cap;
        }
    }

    // Last-fitting-bin urgency: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.5;
    } else if fitting_bins_count > 2 {
        score += 0.15 * (fitting_bins_count as f64 - 2.0);
    }

    // Mild penalty for spreading across too many open bins; smooth in open_bins_count.
    score += 0.05 * (open_bins_count as f64).sqrt();

    // New-bin candidate: prefer opening a fresh bin only when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 1.2 + 2.0 * post_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue class mod 10
    let class = post_residual % 10;
    let harmonic_penalty = match class {
        0 => -6.0,   // perfectly reusable chunk (e.g. exactly fits a 10-multiple item)
        5 => -3.0,   // half-class, still fairly reusable
        2 | 8 => -1.5,
        4 | 6 => -0.5,
        1 | 9 => 2.5,   // awkward slivers
        3 | 7 => 3.0,
        _ => 0.0,
    };
    score += harmonic_penalty;

    // Integer-division tiering of post residual: small leftovers are dead space
    let tier = post_residual / 10;
    score += match tier {
        0 => 14.0,          // 0..9 : unusable for most items
        1 => 6.0,
        2 => 2.0,
        3 => 0.0,
        4 => -2.0,
        5 => -3.0,
        6 => -3.5,
        7 => -4.0,
        _ => -4.5,
    };

    // Reward tight fits: post_residual close to the next item's size means this bin
    // remains perfectly usable by the lookahead item (harmonic coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // leftover cannot host the next item: penalize proportionally
        score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large relative to capacity and existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally, but discount the penalty for big items
        // late in the stream when open bins are highly fragmented.
        score += 12.0 - 14.0 * large_item * (0.5 + 0.5 * progress) * fragmentation;
    }

    // Prefer bins whose residual is far above mean (keep mean residual balanced):
    // placing into an above-average bin spreads remaining space more evenly.
    if (bin_residual as f64) > mean_residual {
        score -= 1.0;
    }

    // Slight preference to keep many small bins available early on
    if open_bins_count > 4 && post_residual >= 20 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly useless.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual <= 20 {
            score += 25.0; // hard-to-fill gap
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        score -= 40.0; // perfect fill
    }

    // Reward tight fits (waste ratio relative to capacity).
    score += (item_size as f64 / bin_capacity as f64) * -10.0;

    // Pressure from number of open bins: discourage opening new bins
    // unless the fit is bad, by penalizing the empty-bin candidate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + open_bins_count as f64 * 1.5 + progress * 10.0;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // leaves a gap the next item cannot use
    }

    // Mild preference for bins tighter than the current mean residual.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already the core term).

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item fits into the post-residual: strong reward scaled by snugness
    if next_item_size > 0 && post_residual >= next_item_size {
        let snugness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 60.0 + 80.0 * snugness;
    } else if next_item_size > 0 {
        // Dead space unusable by the next item: penalize proportionally
        let dead = post_residual as f64;
        let waste_ratio = dead / bin_capacity as f64;
        score += 25.0 * waste_ratio * waste_ratio;
    }

    // Penalize post_residual that is smaller than the minimum conceivable item (1),
    // i.e. unusable slivers, but mildly since items can be small.
    if post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: bins already tighter than average are good targets
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (residual_f - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item would leave a very poor fit elsewhere (large item, loose fit).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // New bin score = residual after placement; make it unattractive unless
        // the item is large (would leave little usable space anyway).
        score += 90.0 - 70.0 * tightness;
    }

    // Mild stream-progression pressure: later in the stream, consolidate more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual so small leftovers dominate.
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize bins whose residual is far below the mean (fragmented bins).
    score += 0.5 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item could exactly fill this bin's post-residual,
    // reward heavily (perfect pairing).
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item fits into post_residual, mild bonus; otherwise mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 8.0;
        }
    }

    // Penalize opening a brand-new bin when open bins fit, scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // But if next item is large, a fresh bin may be valuable.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight preference for bins with larger residual among similar fits.
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let base = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    let mut score = base - 60.0 * poly * (0.5 + progress);

    // Reward tight fits, penalize dead space as stream progresses
    score += (pr_norm * pr_norm) * 30.0 * (1.0 - progress);

    // Lookahead: penalize if next item cannot fit in post_residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 12.0 * ((nx - pr) / cap);
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }

    // Crowd effect: prefer bins below mean residual when many bins open
    let mean_pr = mean_residual / cap;
    score += (pr_norm - mean_pr) * 10.0 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space buckets by integer division.
    // Small post_residual is good (tight fit); reward quadratically.
    score -= (cap - post_residual as f64).powi(2) / cap;

    // Perfect-fit harmonic class: post_residual divisible into clean fractions of capacity
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // exact fit, always take it
    } else if pr <= 10 {
        score -= 60.0;
    } else if pr % 25 == 0 || pr % 20 == 0 {
        score -= 25.0; // residual re-usable by common item sizes
    } else if pr < 10 {
        score += 40.0; // tiny unusable dead space penalty
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // next item won't fit here: penalize proportional to wasted potential
            let overflow = (next_item_size - pr) as f64;
            score += overflow.min(50.0) * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins early/mid stream; mild late-stream when fragmentation high
        let new_bin_penalty = 220.0 - 120.0 * progress;
        // attractive if mean residual of open bins is small (all bins nearly full)
        let mean_bonus = (cap - mean_residual).max(0.0) * 1.5;
        score += new_bin_penalty - mean_bonus;
    } else {
        // mild preference for fuller bins among open bins
        score += (cap - bin_residual as f64) * -0.1;
        // penalize scattering across many open bins
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot hold the minimum
    // item size (1) are pure waste; but gaps below the typical small item
    // threshold are nearly useless. Penalize unusable small gaps hard.
    if post_residual > 0 {
        let dead = (10u32.saturating_sub(post_residual)) as f64;
        score += dead * dead * 0.35; // quadratic penalty for tiny gaps
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 12.0;

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from too many open bins: prefer reusing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual deviates from the mean (consolidate slack).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Lookahead: if next item fits in the post-residual, reward keeping
    // that option; if not, penalize leaving a gap that blocks the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Early in the stream, be more willing to open bins (keep flexibility);
    // later, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0;

    // New-bin candidate: make empty bins moderately attractive only when
    // no good reuse exists; add a mild baseline cost.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize dead space
        score += 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins exist with decent fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + mean_residual * 0.1;
    }

    // Late in stream: consolidation matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 + 0.4 * progress);

    score
}
